// Generated by scripts/gen-l10n.mjs (gdetail n5, vi) — 不要手改;改翻譯請改 scripts/out/l10n/vi/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["vi"]=Object.assign(window.GRAMMAR_DETAIL_L10N["vi"]||{},{"n5-54":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Ba mẫu câu này dùng để sắp xếp <b>thứ tự làm việc</b>, rất dễ hiểu:<br><span class='gd-jp'>〜てから</span>＝「làm ～ trước, rồi mới ～」<br><span class='gd-jp'>〜たあとで</span>＝「sau khi ～」<br><span class='gd-jp'>〜まえに</span>＝「trước khi ～」<br>Cứ như bạn đang kể với bạn bè về một ngày của mình: đánh răng xong rồi mới đi ngủ, ăn cơm xong thì xem TV, trước khi ra khỏi nhà thì xem thời tiết.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>～ trước, rồi ～</span>Động từ <b>thể て</b> ＋ から。<br><span class='gd-pair'><span class='gd-jp'>磨く</span> → <span class='gd-jp'>磨いて</span> → <span class='gd-jp'>磨いてから</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べてから</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>してから</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>歯を磨いてから、寝ます。</span>（Đánh răng xong rồi mới đi ngủ）</div><div class='gd-ex-line'>・<span class='gd-jp'>手を洗ってから、食べてください。</span>（Hãy rửa tay trước rồi hãy ăn）</div><div class='gd-sec'><span class='gd-tag'>sau khi ～</span>Động từ <b>thể た</b> ＋ あとで。Thể た là đổi 「て」 của thể て thành 「た」, đổi 「で」 thành 「だ」。<br><span class='gd-pair'><span class='gd-jp'>見て</span> → <span class='gd-jp'>見た</span> → <span class='gd-jp'>見たあとで</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだあとで</span></span><br>Nếu phía trước là danh từ thì thêm 「の」 ở giữa：<span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事のあとで</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>映画を見たあとで、ご飯を食べました。</span>（Sau khi xem phim xong thì đã đi ăn cơm）</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事のあとで、ビールを飲みます。</span>（Sau giờ làm thì uống bia）</div><div class='gd-sec'><span class='gd-tag'>trước khi ～</span>Động từ <b>thể từ điển</b> (dạng gốc bạn tra thấy trong từ điển) ＋ まえに。<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝るまえに</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くまえに</span></span><br>Phía trước là danh từ thì cũng thêm 「の」：<span class='gd-pair'><span class='gd-jp'>食事</span> → <span class='gd-jp'>食事のまえに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>寝るまえに、シャワーを浴びます。</span>（Tắm một cái trước khi đi ngủ）</div><div class='gd-ex-line'>・<span class='gd-jp'>食事のまえに、手を洗います。</span>（Rửa tay trước khi ăn）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trước まえに <b>luôn là thể từ điển</b>, kể cả khi bạn kể chuyện đã xảy ra：<span class='gd-jp'>日本へ来るまえに、英語を勉強しました。</span>（Trước khi đến Nhật, tôi đã học tiếng Anh）. Không được nói 「来たまえに」.<br>・Trước あとで <b>luôn là thể た</b>, kể cả khi việc đó chưa xảy ra：<span class='gd-jp'>食べたあとで、歯を磨きます。</span>（Ăn xong rồi sẽ đánh răng）. Không được nói 「食べるあとで」.<br>・Cả câu là quá khứ hay hiện tại thì <b>nhìn cuối câu</b> để quyết định (磨きます／磨きました), vế đầu không cần đổi theo.<br>・Với danh từ, nối thẳng sẽ bị thiếu 「の」: phải nói <span class='gd-jp'>授業のあとで</span>, không phải 「授業あとで」.<br>・Khi <span class='gd-jp'>あとで</span> đứng một mình, không có gì phía trước, nó có nghĩa là 「lát nữa, để sau」：<span class='gd-jp'>あとで電話します。</span>（Lát nữa mình sẽ gọi cho bạn）</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>てから và あとで đều có nghĩa là 「làm xong A rồi mới B」, nhiều lúc dùng cái nào cũng được, chỉ khác sắc thái：<br><span class='gd-jp'>お風呂に入ってから、ご飯を食べます。</span>（<b>Trước tiên</b> tắm xong, <b>rồi mới</b> ăn cơm: nhấn mạnh thứ tự, có cảm giác 「tắm xong mới ăn」）<br><span class='gd-jp'>お風呂に入ったあとで、ご飯を食べます。</span>（Sau khi tắm xong thì ăn cơm: chỉ cho biết thời điểm ăn cơm là ở phía sau）<br>Khi muốn đối phương 「nhất định phải làm xong A trước」, dùng てから là tự nhiên nhất：<br><span class='gd-jp'>電話してから来てください。</span>（Hãy gọi điện trước rồi hãy đến）</div><div class='gd-warn'>Mẹo phân biệt: muốn nói 「làm ～ trước rồi mới ～」 thì dùng <b>てから</b>; chỉ nói 「sau khi ～」 thì dùng <b>たあとで</b>; nói 「trước khi ～」 thì dùng <b>まえに</b>, và phía trước nhất định là thể từ điển.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Nếu sau てから là một khoảng thời gian, nghĩa sẽ thành 「từ khi ～ đến nay đã…」：<span class='gd-jp'>日本に来てから、もう三年です。</span>（Từ khi đến Nhật đã ba năm rồi）</div>","n5-58":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ながら」 chính là <b>「vừa ～ vừa ～」</b> trong tiếng Việt. Nhưng tiếng Nhật có một thói quen: <b>việc quan trọng hơn được đặt ở phía sau</b>. Ví dụ 「vừa nghe nhạc vừa học bài」, việc chính của bạn là học, nhạc chỉ là phụ, nên tiếng Nhật nói <span class='gd-jp'>音楽を聞きながら勉強します。</span></div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đầu tiên chuyển động từ sang thể ます, rồi <b>bỏ 「ます」 đi</b> và thêm thẳng 「ながら」. Cả ba nhóm động từ đều giống nhau.<br><span class='gd-pair'><span class='gd-jp'>聞きます</span> → bỏ ます → <span class='gd-jp'>聞きながら</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べながら</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見ながら</span></span><span class='gd-pair'><span class='gd-jp'>運転します</span> → <span class='gd-jp'>運転しながら</span></span><br>Phía sau là hành động chính. Bản thân 「ながら」 <b>không bao giờ thay đổi</b>; thì quá khứ, phủ định hay lịch sự hay không, tất cả giao cho động từ cuối câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>歌を歌いながら、料理しました。</span>（Tôi vừa hát vừa nấu ăn）</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Làm hai việc cùng lúc</span>Tay đang làm việc này, đồng thời cũng đang làm việc kia.</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビを見ながら、ご飯を食べます。</span>（Vừa xem TV vừa ăn cơm）</div><div class='gd-ex-line'>・<span class='gd-jp'>歩きながらスマホを見るのは危ないです。</span>（Vừa đi bộ vừa xem điện thoại rất nguy hiểm）</div><div class='gd-sec'><span class='gd-tag'>Trong khoảng thời gian này làm cả hai việc</span>Không nhất thiết phải cùng một giây, cũng có thể là dạo này hai việc song song với nhau, giống như 「vừa đi làm vừa đi học」.</div><div class='gd-ex-line'>・<span class='gd-jp'>アルバイトをしながら、日本語を勉強しています。</span>（Tôi vừa làm thêm vừa học tiếng Nhật）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phải nối với <b>thể ます bỏ ます</b>, không phải thể từ điển: <span class='gd-jp'>聞きながら</span> mới đúng, không được nói 「聞くながら」; <span class='gd-jp'>食べながら</span> mới đúng, không được nói 「食べるながら」.<br>・Hai việc trước và sau phải do <b>cùng một người</b> làm. 「Mẹ nấu cơm, trong lúc đó tôi xem TV」 là hai người, không dùng được ながら, phải đổi sang 「とき」：<span class='gd-jp'>母が料理をしているとき、私はテレビを見ていました。</span><br>・Đừng tự ý đảo chỗ như trong tiếng Việt. Tiếng Việt 「vừa A vừa B」 đổi chỗ A và B thì nghĩa gần như không đổi, còn tiếng Nhật thì <b>vế sau mới là việc chính</b>. <span class='gd-jp'>勉強しながら音楽を聞きます</span> nghe sẽ thành 「chủ yếu là nghe nhạc, tiện thể học bài」.<br>・Quá khứ và lịch sự chỉ đổi ở động từ cuối, phía trước ながら đừng thêm ました: không được nói 「聞きましたながら」, phải nói <span class='gd-jp'>聞きながら勉強しました</span>.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'><b>Nối bằng thể て</b>＝làm xong một việc <b>rồi</b> làm việc tiếp theo, có thứ tự trước sau.<br><b>ながら</b>＝hai việc diễn ra <b>cùng lúc</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯を食べて、テレビを見ます。</span>（Ăn cơm xong rồi xem TV）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご飯を食べながら、テレビを見ます。</span>（Vừa ăn cơm vừa xem TV）</div><div class='gd-sec'><b>〜たり〜たりします</b>＝nêu ví dụ vài việc đã làm, không phải làm cùng lúc.</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は本を読んだり、映画を見たりします。</span>（Cuối tuần tôi hay đọc sách, xem phim, v.v.）</div><div class='gd-warn'>Mẹo phân biệt: làm cùng lúc là ながら, làm xong việc này rồi làm việc kia là thể て, còn liệt kê vài việc đã làm là たり〜たり.</div>","n5-34":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「が」giống như bạn đưa ngón tay chỉ và nói <b>“Chính là nó!”</b>. Khi muốn chỉ ra <b>ai</b> làm một việc hay <b>cái gì</b> đã xảy ra, tức là chỉ ra nhân vật chính của câu, bạn đặt が ngay sau đó.<br>Ví dụ có người hỏi “Ai đến vậy?” và bạn trả lời “Anh Tanaka đến”. “Anh Tanaka” chính là đáp án được chỉ ra, nên ta dùng <span class='gd-jp'>田中さんが来ました</span>.</div><div class='gd-h'>Cách kết hợp</div><div class='gd-sec'>Thêm が thẳng vào sau danh từ, không cần biến đổi gì.<br><span class='gd-jp'>私が</span>、<span class='gd-jp'>雨が</span>、<span class='gd-jp'>田中さんが</span>、<span class='gd-jp'>誰が</span>、<span class='gd-jp'>何が</span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Hỏi ai, hỏi cái gì</span>Khi “ai” hoặc “cái gì” là nhân vật chính của câu, bạn dùng が lúc hỏi và cũng dùng が lúc trả lời.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰が来ましたか。</span>（Ai đến vậy?）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんが来ました。</span>（Anh Tanaka đến.）</div><div class='gd-ex-line'>・<span class='gd-jp'>何が一番おいしいですか。</span>（Cái gì ngon nhất?）</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンが一番おいしいです。</span>（Tô ramen này ngon nhất.）</div><div class='gd-sec'><span class='gd-tag'>Việc đang diễn ra trước mắt</span>Với việc vừa nhìn thấy hoặc vừa xảy ra, bạn cứ nói thẳng cảnh tượng đó ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、バスが来ました。</span>（A, xe buýt đến rồi.）</div><div class='gd-ex-line'>・<span class='gd-jp'>雪が降っています。</span>（Tuyết đang rơi.）</div><div class='gd-sec'><span class='gd-tag'>Lần đầu nhắc đến</span>Người hoặc việc mà đối phương chưa biết, bạn đưa ra lần đầu tiên.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、友達が家に来ました。</span>（Hôm qua có bạn đến nhà mình.）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Sau “ai, cái gì, ở đâu” không dùng は được</b>. <span class='gd-jp'>誰は来ましたか</span> là sai, phải nói <span class='gd-jp'>誰が来ましたか</span>. Các từ nghi vấn khác cũng vậy, ví dụ <span class='gd-jp'>どこが痛いですか</span> (Đau ở đâu?).<br>・<b>Hỏi bằng が thì trả lời cũng bằng が</b>. Nếu người ta hỏi <span class='gd-jp'>誰が作りましたか</span> (Ai làm vậy?), bạn trả lời <span class='gd-jp'>私が作りました</span> (Là tôi làm). Nếu trả lời “私は作りました” thì nghĩa thành “Tôi thì có làm đấy (còn người khác thì không biết)”, nghe rất lạ.<br>・Bạn dễ quen tay gắn は vào chủ ngữ của mọi câu. Nhưng khi nhìn ra cửa sổ thấy trời bỗng đổ mưa, bạn phải nói <span class='gd-jp'>あ、雨が降っています</span>. Với những câu tả thẳng cảnh trước mắt như vậy, dùng が mới tự nhiên.<br>・<span class='gd-jp'>日本語が好きです</span> và <span class='gd-jp'>ピアノができます</span> cũng dùng が, nhưng đó là cách dùng của “thích gì, biết làm gì”. Thẻ “Trợ từ が (khả năng・sở thích)” sẽ nói riêng, đừng trộn vào đây vội.</div><div class='gd-h'>Phân biệt với từ trông giống nhau</div><div class='gd-sec'><b>は</b> nghĩa là “nói đến ～ thì…”, bạn đặt chủ đề ra trước và <b>trọng tâm nằm ở phía sau</b>.<br><b>が</b> nghĩa là “chính là ～”, và <b>trọng tâm nằm ngay ở danh từ phía trước</b>.<br><br>Cùng là nói mình là Tanaka:<br>Khi tự giới thiệu, bạn nói <span class='gd-jp'>私は田中です。</span>（Tôi là Tanaka.）Lúc này mọi người đang nghe xem “tôi là ai”.<br>Khi có người hỏi <span class='gd-jp'>田中さんはどの人ですか。</span>（Anh Tanaka là người nào vậy?）bạn nói <span class='gd-jp'>私が田中です。</span>（Tôi chính là Tanaka.）Lúc này bạn đang chỉ Tanaka ra từ một nhóm người.<br><br>Cùng là nói Tanaka có đến:<br><span class='gd-jp'>田中さんが来ました。</span>（Anh Tanaka đến rồi.）Chỉ đơn giản báo ai đã đến.<br><span class='gd-jp'>田中さんは来ました。</span>（Anh Tanaka thì có đến đấy.）Lấy Tanaka làm chủ đề trước, kèm sắc thái “còn người khác thì chưa chắc”.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: muốn trả lời “là ai, là cái gì” thì dùng が; muốn nói “người này, vật này thế nào” thì dùng は. Khi từ nghi vấn làm nhân vật chính, phía sau luôn dùng が.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>“Có cái gì ở đâu” cũng dùng が: <span class='gd-jp'>あそこに猫がいます。</span>（Ở đằng kia có một con mèo.）Tiếp theo bạn có thể học cách diễn đạt sự tồn tại, và cách dùng が với “thích, biết làm”.</div>","n5-31":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「から」giống <b>“vì ～ nên ～”</b> trong tiếng Việt. Điểm khác là tiếng Việt hay đặt “vì” ở đầu câu, còn「から」của tiếng Nhật đứng <b>ở cuối vế nêu lý do</b>: nói lý do xong rồi mới nói kết quả.</div><div class='gd-ex-line'>・<span class='gd-jp'>時間がないから、急ぎましょう。</span>（Hết thời gian rồi nên chúng ta nhanh lên nhé）</div><div class='gd-sec'>Thứ tự là: <b>lý do ＋ から、kết quả</b>.</div><div class='gd-h'>Cách kết hợp</div><div class='gd-sec'>Trước「から」là một câu hoàn chỉnh, có thể ở dạng thông thường hoặc dạng lịch sự với です・ます.<br><b>Động từ</b>：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くから</span></span><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますから</span></span><br><b>Tính từ đuôi い</b>：<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いから</span></span><span class='gd-pair'><span class='gd-jp'>寒いです</span> → <span class='gd-jp'>寒いですから</span></span><br><b>Tính từ đuôi な</b>：phải thêm「だ」hoặc「です」trước. <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだから</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かですから</span></span><br><b>Danh từ</b>：cũng phải thêm「だ」hoặc「です」. <span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だから</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨ですから</span></span><br>Việc trong quá khứ cũng dùng được：<span class='gd-pair'><span class='gd-jp'>寝なかった</span> → <span class='gd-jp'>寝なかったから</span></span></div><div class='gd-sec'>Vế trước dùng dạng thông thường, cuối câu dùng ます là kiểu rất hay gặp trong đời sống; muốn nói lịch sự hơn thì dùng です・ます ở cả hai vế.</div><div class='gd-h'>Cách hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Giải thích lý do</span>Nói nguyên nhân trước, kết quả sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いから、よく来ます。</span>（Quán này rẻ nên mình hay đến）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は日曜日だから、学校は休みです。</span>（Hôm nay là Chủ nhật nên trường nghỉ）</div><div class='gd-sec'><span class='gd-tag'>Nhờ vả, nhắc nhở, rủ rê</span>Phía sau nối với lời nhờ hoặc lời mời cũng rất tự nhiên.</div><div class='gd-ex-line'>・<span class='gd-jp'>危ないですから、触らないでください。</span>（Nguy hiểm nên xin đừng chạm vào）</div><div class='gd-sec'><span class='gd-tag'>Chỉ trả lời lý do</span>Khi người ta hỏi “tại sao” mà kết quả ai cũng biết rồi, bạn chỉ cần nói lý do rồi thêm から.</div><div class='gd-ex-line'>・<span class='gd-jp'>「どうして食べないの？」「辛いから。」</span>（“Sao bạn không ăn?” “Vì cay.”）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ và tính từ đuôi な <b>không thể nối thẳng から</b>: phải nói <span class='gd-jp'>雨だから</span>, không phải “雨から”; phải nói <span class='gd-jp'>静かだから</span>, không phải “静かから”.<br>・Tính từ đuôi い thì ngược lại, <b>không được thêm だ</b>: phải nói <span class='gd-jp'>高いから</span>, không phải “高いだから”.<br>・Đừng đặt から ở đầu câu theo thói quen của “vì” trong tiếng Việt. “Vì trời mưa” là <span class='gd-jp'>雨だから</span>, から nằm ở phía sau.<br>・Khi <span class='gd-jp'>だから</span> đứng một mình ở đầu câu, nó có nghĩa là “vì vậy”: <span class='gd-jp'>雨です。だから、行きません。</span>（Trời mưa. Vì vậy mình không đi）<br>・Khi giải thích hoàn cảnh của mình với thầy cô hay cấp trên (ví dụ lý do đến muộn), から nghe khá thẳng, đôi khi giống như đang viện cớ. Còn trong lúc nói chuyện hằng ngày thì dùng から hoàn toàn không sao.</div><div class='gd-h'>Phân biệt với từ trông giống nhau</div><div class='gd-sec'>Bạn đã học「から」chỉ điểm bắt đầu (<b>từ ～</b>), và hai từ này trông giống hệt nhau.<br><b>Điểm bắt đầu</b>：<span class='gd-jp'>9時から働きます。</span>（Làm việc từ 9 giờ）<br><b>Lý do</b>：<span class='gd-jp'>雨だから、働きません。</span>（Vì trời mưa nên không làm việc）<br>Khác nhau ở thứ đứng trước: から chỉ điểm bắt đầu đi ngay sau danh từ chỉ thời gian hoặc địa điểm; から chỉ lý do đi sau phần cuối của một câu, chẳng hạn động từ, tính từ, hoặc「だ」「です」.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: nếu trước から chỉ có danh từ như <span class='gd-jp'>9時</span>、<span class='gd-jp'>駅</span> thì đó là “từ”; nếu trước から là một câu đầy đủ như <span class='gd-jp'>雨だ</span>、<span class='gd-jp'>寒い</span>、<span class='gd-jp'>あります</span> thì đó là “vì”.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Đưa lý do xuống cuối câu thành「〜からです」để trả lời câu hỏi “tại sao”: <span class='gd-jp'>熱があるからです。</span>（Vì bị sốt）. Sau này bạn sẽ học thêm「〜ので」, cũng nghĩa là “vì”, nhưng giọng mềm hơn から, dùng nhiều hơn khi xin nghỉ hay xin lỗi cấp trên.</div>","n5-56":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜たり〜たりします」giống kiểu nói tiếng Việt <b>“nào là đọc sách, nào là xem phim…”</b>. Bạn chọn hai, ba việc trong cả đống việc để làm ví dụ, với ý “mình chỉ nêu ví dụ thôi, còn làm nhiều việc khác nữa”. Mẫu này còn một cách dùng thứ hai: <b>“lúc thế này, lúc thế kia”</b>, giống như “lúc nóng lúc lạnh”, “lúc mưa lúc tạnh” trong tiếng Việt.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Liệt kê ví dụ</span>Khi ai đó hỏi bạn thường làm gì, bạn không cần kể hết, chỉ cần chọn vài việc tiêu biểu để nói.</div><div class='gd-ex-line'>・<span class='gd-jp'>休みの日は、本を読んだり映画を見たりします。</span>（Ngày nghỉ mình đọc sách, xem phim các kiểu）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は掃除したり、買い物に行ったりします。</span>（Cuối tuần mình dọn dẹp một chút, đi mua sắm này nọ）</div><div class='gd-sec'><span class='gd-tag'>Lúc thế này lúc thế kia</span>Hai hành động hoặc trạng thái trái ngược nhau thay phiên xuất hiện.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、暑かったり寒かったりします。</span>（Dạo này thời tiết lúc nóng lúc lạnh）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は雨が降ったりやんだりしています。</span>（Hôm nay trời lúc mưa lúc tạnh）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Ba bước: <b>chia động từ sang thể た → thêm り phía sau → cuối câu thêm します</b>.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んだ</span> → <span class='gd-jp'>読んだり</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったり</span></span><br><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span> → <span class='gd-jp'>見たり</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span> → <span class='gd-jp'>したり</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たり</span></span><br>Nếu bạn chưa quen thể た, hãy nghĩ đơn giản là <b>đổi「て」của thể て thành「た」, đổi「で」thành「だ」</b>:<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んだ</span></span><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span></span></div><div class='gd-sec'><b>Tính từ い</b>: bỏ「い」, thay bằng「かったり」.<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑かったり</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったり</span></span>（<span class='gd-jp'>いい</span>phải đổi thành<span class='gd-jp'>よかったり</span>）<br><b>Danh từ, tính từ な</b>: thêm「だったり」phía sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ごはんはパンだったりご飯だったりします。</span>（Bữa sáng khi thì ăn bánh mì, khi thì ăn cơm）</div><div class='gd-sec'>Thì quá khứ và mức độ lịch sự đều giao cho <b>する ở cuối câu</b> biến đổi:</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は友達と話したり、ゲームをしたりしました。</span>（Hôm qua mình nói chuyện với bạn, chơi game này nọ）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は家で寝たり、テレビを見たりする。</span>（Cuối tuần ở nhà ngủ nghỉ, xem tivi: cách nói với bạn bè）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Phải nối với <b>thể た</b>, không phải thể ます: là <span class='gd-jp'>行ったり</span>, không phải 行きたり; là <span class='gd-jp'>読んだり</span>, không phải 読みたり。<br>・Đừng bỏ <span class='gd-jp'>します</span> (hoặc <span class='gd-jp'>する</span>) ở cuối câu. Thiếu nó, câu nghe như chưa nói xong.<br>・Thì quá khứ chỉ đổi ở cuối cùng: <span class='gd-jp'>行ったりしました</span> mới đúng, không nói 行きましたり。<br>・Có từ hai hành động trở lên thì sau mỗi hành động đều phải thêm たり. Trong văn nói đôi khi bạn sẽ nghe người ta lược たり thứ hai, nhưng khi thi và viết thì nên viết đầy đủ. Chỉ nêu một việc cũng được, ví dụ <span class='gd-jp'>映画を見たりします</span>（mình hay xem phim này nọ）。<br>・たり <b>không biểu thị thứ tự trước sau</b>. Muốn nói “làm A rồi làm B” thì phải dùng thể て。</div><div class='gd-h'>Phân biệt với các mẫu dễ lẫn</div><div class='gd-sec'>Cùng nói về “hôm qua đã làm gì”:<br><b>て</b> = kể theo thứ tự, và chỉ có những việc này thôi: <span class='gd-jp'>昨日は本を読んで、映画を見ました。</span>（Hôm qua mình đọc sách, rồi đi xem phim）<br><b>たり</b> = chọn vài việc làm ví dụ, còn việc khác nữa, không quan tâm thứ tự: <span class='gd-jp'>昨日は本を読んだり、映画を見たりしました。</span>（Hôm qua mình đọc sách, xem phim các kiểu）<br><b>や</b> = cũng là liệt kê ví dụ, nhưng nối <b>đồ vật (danh từ)</b>: <span class='gd-jp'>昨日は本や漫画を読みました。</span>（Hôm qua mình đọc sách, truyện tranh này nọ）</div><div class='gd-warn'>Mẹo nhỏ để chọn: kể hết mọi việc theo thứ tự thì dùng「て」; chọn vài <b>hành động</b> làm ví dụ thì dùng「たり」; chọn vài <b>đồ vật</b> làm ví dụ thì dùng「や」.</div>","n5-1":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「名詞＋です」nghĩa là <b>“là ～”</b>, còn「名詞＋じゃありません」nghĩa là <b>“không phải ～”</b>. <span class='gd-jp'>私は学生です。</span>nghĩa là “Tôi là sinh viên”. Đây là câu cơ bản nhất của tiếng Nhật, câu đầu tiên khi tự giới thiệu bạn sẽ dùng ngay.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Rất đơn giản: <b>thêm thẳng</b> vào sau danh từ, bản thân danh từ hoàn toàn không phải biến đổi.<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生です</span></span>（là sinh viên）<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生じゃありません</span></span>（không phải sinh viên）<br>Mẫu câu là「A<span class='gd-jp'>は</span>B<span class='gd-jp'>です</span>」= A là B.</div><div class='gd-ex-line'>・<span class='gd-jp'>林です。よろしくお願いします。</span>（Mình là Lâm, rất mong được bạn giúp đỡ）</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の傘です。</span>（Đây là cái ô của tôi）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは先生じゃありません。</span>（Anh Tanaka không phải giáo viên）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休みじゃありません。</span>（Ngày mai không phải ngày nghỉ）</div><div class='gd-sec'>Thêm <span class='gd-jp'>か</span> phía sau là thành câu hỏi: <span class='gd-jp'>学生ですか。</span>（Bạn là sinh viên à?）</div><div class='gd-h'>Mấy cách nói “không phải”</div><div class='gd-sec'>Ý nghĩa đều giống nhau, khác nhau ở hoàn cảnh dùng:<br><span class='gd-tag'>Dùng nhiều nhất</span><span class='gd-jp'>学生じゃありません</span>: cách nói lịch sự thường ngày.<br><span class='gd-tag'>Trang trọng hơn</span><span class='gd-jp'>学生ではありません</span>: dùng khi viết văn, trong hoàn cảnh trang trọng. 「じゃ」chính là「では」khi nói nhanh.<br><span class='gd-tag'>Nhẹ nhàng hơn</span><span class='gd-jp'>学生じゃないです</span>: vẫn lịch sự nhưng giọng mềm hơn, người Nhật hiện nay nói rất thường xuyên.</div><div class='gd-h'>Khi nói với bạn bè</div><div class='gd-sec'>Với người nhà, bạn thân thì không dùng です mà đổi thành <b>だ／じゃない</b>:<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃない</span></span><br>Có điều khi trò chuyện thật, người ta hay lược「だ」, hoặc thêm「よ」phía sau cho tự nhiên, nếu không nghe hơi cứng:</div><div class='gd-ex-line'>・<span class='gd-jp'>うん、学生だよ。</span>（Ừ, mình là sinh viên đó）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chữ <span class='gd-jp'>は</span> trong「AはB」đọc là <b>wa</b>, không phải ha.<br>・Âm「す」ở cuối <span class='gd-jp'>です</span> thường đọc rất nhẹ, nghe giống「des」.<br>・です không phải lúc nào cũng dịch là “là”: <span class='gd-jp'>今日は雨です。</span>nghĩa là “Hôm nay trời mưa”, tiếng Việt không nói “hôm nay là mưa”.<br>・Sau động từ không được thêm です: chỉ cần <span class='gd-jp'>食べます</span>, không thể nói「食べるです」.<br>・Không cần câu nào cũng nói <span class='gd-jp'>私は</span>; khi người nghe đã biết bạn đang nói về chính mình, người Nhật thường lược đi.</div><div class='gd-h'>Phân biệt với các mẫu dễ lẫn</div><div class='gd-sec'>Danh từ và tính từ な đều phủ định bằng じゃありません, còn <b>tính từ い thì khác</b>, đây là chỗ dễ nhầm nhất.<br><b>Danh từ</b>: <span class='gd-jp'>ここは駅じゃありません。</span>（Đây không phải nhà ga）<br><b>Tính từ な</b>: <span class='gd-jp'>ここは静かじゃありません。</span>（Ở đây không yên tĩnh）<br><b>Tính từ い</b>: <span class='gd-jp'>ここは高くないです。</span>（Ở đây không đắt）<br>Không thể nói「高いじゃありません」, phải đổi い thành <b>くない</b>.</div><div class='gd-warn'>Mẹo nhỏ để chọn: danh từ và tính từ な thì thêm thẳng「じゃありません」; tính từ い thì đổi い thành「くないです」. Lưu ý <span class='gd-jp'>きれい</span> tuy kết thúc bằng い nhưng thật ra là tính từ な, nên phải nói <span class='gd-jp'>きれいじゃありません</span>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cách nói ở quá khứ: <span class='gd-jp'>学生でした</span>（trước đây là sinh viên）, <span class='gd-jp'>学生じゃありませんでした</span>（trước đây không phải sinh viên）.</div>","n5-51":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt dù ai cho ai cũng chỉ nói \"cho\". Tiếng Nhật thì nhìn xem <b>đồ vật đi theo hướng nào</b>. Từ phía mình <b>trao đi</b> thì dùng <span class='gd-jp'>あげます</span>. Từ phía người khác <b>trao đến</b> thì dùng <span class='gd-jp'>くれます</span>. Đứng ở phía mình và nói \"mình <b>nhận được</b>\" thì dùng <span class='gd-jp'>もらいます</span>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>あげます</span>Mình (hoặc người phía mình) cho người khác, đồ vật đi ra ngoài. Người khác cho người khác cũng dùng từ này.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に誕生日プレゼントをあげました。</span>（Mình đã tặng bạn quà sinh nhật）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは山田さんに花をあげました。</span>（Anh Tanaka đã tặng hoa cho chị Yamada）</div><div class='gd-sec'><span class='gd-tag'>くれます</span>Người khác cho <b>mình</b>, hoặc cho <b>người nhà của mình</b>, đồ vật đi đến phía mình. Không cần nói \"cho mình\" ra, người Nhật nghe là hiểu ngay.</div><div class='gd-ex-line'>・<span class='gd-jp'>母が時計をくれました。</span>（Mẹ đã cho mình một chiếc đồng hồ）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が妹にお菓子をくれました。</span>（Bạn đã cho em gái mình bánh kẹo）</div><div class='gd-sec'><span class='gd-tag'>もらいます</span>Đứng ở phía người nhận và nói \"mình được cho, mình nhận được\".</div><div class='gd-ex-line'>・<span class='gd-jp'>先生から手紙をもらいました。</span>（Mình nhận được thư của thầy/cô）</div><div class='gd-h'>Cách ghép câu</div><div class='gd-sec'>Cả ba câu đều có \"ai, cho ai, cái gì\". Khác nhau ở chỗ <b>ai là chủ ngữ</b>:<br><b>あげます</b>：người cho<span class='gd-jp'>は</span>　người nhận<span class='gd-jp'>に</span>　đồ vật<span class='gd-jp'>を</span>　<span class='gd-jp'>あげます</span><br><b>くれます</b>：người cho<span class='gd-jp'>が</span>　（mình<span class='gd-jp'>に</span>）　đồ vật<span class='gd-jp'>を</span>　<span class='gd-jp'>くれます</span><br><b>もらいます</b>：mình<span class='gd-jp'>は</span>　người cho<span class='gd-jp'>に</span>／<span class='gd-jp'>から</span>　đồ vật<span class='gd-jp'>を</span>　<span class='gd-jp'>もらいます</span><br>Thì quá khứ cũng giống vậy, đổi ます thành ました：<span class='gd-pair'><span class='gd-jp'>くれます</span> → <span class='gd-jp'>くれました</span></span></div><div class='gd-h'>Phân biệt với những mẫu dễ nhầm</div><div class='gd-sec'>Cùng một việc: <b>bạn cho mình một quyển sách</b>.<br>・<span class='gd-jp'>友達が本をくれました。</span>（Bạn đã cho mình một quyển sách）Chủ ngữ là bạn, sách đi về phía mình.<br>・<span class='gd-jp'>友達に本をもらいました。</span>（Mình nhận được một quyển sách từ bạn）Chủ ngữ là mình, mình là người nhận.<br>Hai câu này nghĩa giống nhau, câu nào cũng nói được.<br>・<span class='gd-jp'>友達が私に本をあげました。</span>　Câu này <b>sai</b>, あげます không dùng cho trường hợp \"cho mình\".<br><br>Ngược lại, nếu là <b>mình cho bạn một quyển sách</b> thì chỉ có thể nói:<br>・<span class='gd-jp'>友達に本をあげました。</span>（Mình đã cho bạn một quyển sách）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: hãy tự hỏi \"đồ vật có đi về phía mình không?\". Nếu có thì dùng くれます hoặc もらいます. Nếu đi ra ngoài thì dùng あげます.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Theo phản xạ tiếng Việt, \"mẹ cho mình\" nhiều bạn sẽ viết thành <span class='gd-jp'>母があげました</span>, như vậy là sai. Cho mình hay cho người nhà mình thì luôn dùng <b>くれます</b>.<br>・Chủ ngữ của くれます sẽ không bao giờ là \"mình\". <span class='gd-jp'>私が友達にくれました</span>là sai, phải nói <span class='gd-jp'>友達にあげました</span>.<br>・<span class='gd-jp'>に</span> đứng trước もらいます có nghĩa là \"<b>từ</b>\", không phải \"cho\". <span class='gd-jp'>友達にもらいました</span>là \"nhận được từ bạn\", không phải \"đưa cho bạn\". Sợ nhầm thì đổi sang dùng <span class='gd-jp'>から</span>, nghĩa vẫn như vậy.<br>・Người nhà được tính là \"người phía mình\". Vì vậy khi bạn bè cho em gái bạn đồ gì, cũng dùng くれます.<br>・Khi cho thầy cô hay cấp trên mà nói thẳng あげます thì nghe hơi bề trên. Sau này bạn sẽ học cách nói lịch sự hơn.<br>・Đôi khi bạn sẽ nghe <span class='gd-jp'>花に水をやります</span>（tưới nước cho hoa）. やります dùng khi cho động vật, thực vật. Nói やります với người nghe khá thô, nên người mới học cứ dùng あげます là được.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Lên N4, ba động từ này sẽ đi sau thể て và biến thành nghĩa \"làm giúp ai việc gì\"：<span class='gd-jp'>友達が駅まで送ってくれました。</span>（Bạn đã đưa mình đến ga）Cách phán đoán hướng hoàn toàn giống ở đây, bây giờ phân biệt rõ thì sau này sẽ rất nhẹ nhàng.</div>","n5-38":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「だけ」và「しか」đều có nghĩa là \"chỉ\". <b>だけ</b> giống \"chỉ ~\" trong tiếng Việt, đơn thuần nói về phạm vi. <b>しか〜ません</b> thì giống \"mới ~\", \"chỉ có ~ thôi\", trong câu có cảm giác <b>\"ít quá, không đủ\"</b>. Đặc điểm lớn nhất là: <b>sau しか nhất định phải là phủ định</b>.</div><div class='gd-h'>Cách ghép câu</div><div class='gd-sec'><b>だけ</b>：đặt ngay sau danh từ hoặc số lượng.<br><span class='gd-pair'><span class='gd-jp'>水</span> → <span class='gd-jp'>水だけ</span></span><span class='gd-pair'><span class='gd-jp'>一つ</span> → <span class='gd-jp'>一つだけ</span></span><br>Động từ cũng ghép được, dùng thể từ điển (dạng bạn thấy trong từ điển)：<span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るだけ</span></span>（chỉ xem thôi）</div><div class='gd-sec'><b>しか</b>：đặt sau danh từ hoặc số lượng, động từ cuối câu nhất định phải chuyển sang phủ định.<br><span class='gd-pair'><span class='gd-jp'>水を飲みます</span> → <span class='gd-jp'>水しか飲みません</span></span>（chỉ uống nước）</div><div class='gd-sec'><b>「を」「が」vốn có phải bỏ đi</b>：<span class='gd-jp'>水を</span>trở thành<span class='gd-jp'>水だけ</span>、<span class='gd-jp'>水しか</span>。（Sau だけ giữ lại を cũng được, nhưng bình thường đa phần bỏ luôn.）<br>Còn「に」「で」「へ」thì <b>phải giữ lại</b>, đặt trước しか：</div><div class='gd-ex-line'>・<span class='gd-jp'>友達にしか言いませんでした。</span>（Mình chỉ nói với bạn thôi）</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>だけ：đơn thuần nói về phạm vi</span>Không đặc biệt thấy nhiều hay ít, chỉ nói rõ \"chỉ có cái này\".</div><div class='gd-ex-line'>・<span class='gd-jp'>サラダだけ注文します。</span>（Mình chỉ gọi salad）</div><div class='gd-ex-line'>・<span class='gd-jp'>見ているだけです。</span>（Mình chỉ xem thôi）</div><div class='gd-sec'>Câu thứ hai rất hữu ích khi đi dạo mua sắm ở Nhật. Khi nhân viên đến chào hỏi, bạn trả lời như vậy là được.</div><div class='gd-sec'><span class='gd-tag'>しか：thấy ít, không đủ</span>Trong lòng thấy \"ít quá\", \"ít hơn mình tưởng\".</div><div class='gd-ex-line'>・<span class='gd-jp'>10分しか残っていません。</span>（Chỉ còn 10 phút thôi）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は3時間しか寝ませんでした。</span>（Hôm qua mình mới ngủ có ba tiếng）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Sau しか nhất định là phủ định</b>：nói <span class='gd-jp'>千円しかありません</span>, không thể nói「千円しかあります」.<br>・<b>Đừng để ません đánh lừa</b>：thấy「ません」đừng vội nghĩ là \"không có\". <span class='gd-jp'>千円しかありません</span>là \"chỉ có một nghìn yên\", không phải \"không có một nghìn yên\". <span class='gd-jp'>肉しか食べません</span>là \"chỉ ăn thịt\", không phải \"không ăn thịt\". Bạn có thể nghĩ là \"ngoài một nghìn yên ra thì không có gì cả\".<br>・<b>Trước しか không được giữ を, が</b>：không thể nói「水をしか」, phải nói <span class='gd-jp'>水しか</span>.<br>・<b>だけ không có nghĩa là \"đủ\"</b>：だけ chỉ là \"chỉ\" mang tính trung lập, bản thân nó không có ý \"đủ dùng\".</div><div class='gd-h'>Phân biệt với những mẫu dễ nhầm</div><div class='gd-sec'>Cùng một việc, dùng だけ là đang thông báo, dùng しか là đang than \"ít quá\".</div><div class='gd-ex-line'>・<span class='gd-jp'>パーティーに一人だけ来ました。</span>（Bữa tiệc chỉ có một người đến: thông báo đơn thuần）</div><div class='gd-ex-line'>・<span class='gd-jp'>パーティーに一人しか来ませんでした。</span>（Bữa tiệc mới có một người đến: ít người quá）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少しだけ分かります。</span>（Mình hiểu một chút tiếng Nhật: nói khiêm tốn là mình biết chút ít）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少ししか分かりません。</span>（Mình chỉ hiểu chút xíu tiếng Nhật: nhấn mạnh là hiểu không nhiều, nhờ đối phương đừng nói khó quá）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: khi bạn muốn nói \"mới ~\", \"chỉ có ~ thôi\" và trong lòng thấy ít, hãy dùng「しか＋ません」. Nếu chỉ nói rõ phạm vi thì dùng「だけ」. Nhớ là しか luôn đi với ません.</div>","n5-62":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt nói “cửa mở rồi” và “tôi mở cửa” đều dùng chung một chữ “mở”. Tiếng Nhật thì <b>phải đổi sang động từ khác</b>: nói “cửa mở” dùng <span class='gd-jp'>開く</span>, nói “có người mở cửa” dùng <span class='gd-jp'>開ける</span>. Loại đầu gọi là <b>tự động từ</b>, loại sau gọi là <b>tha động từ</b>, và trợ từ đứng trước cũng phải đổi theo.</div><div class='gd-h'>Làm quen hai khái niệm</div><div class='gd-sec'><span class='gd-tag'>Tự động từ＋が</span>Chỉ nói “sự vật trở nên như thế nào”, không quan tâm ai làm, phía trước dùng <b>が</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアが開きます。</span>(Cửa sắp mở: thông báo hay nghe trên tàu điện)</div><div class='gd-sec'><span class='gd-tag'>Tha động từ＋を</span>Nói “có người tác động lên một vật nào đó”, vật bị tác động đứng trước <b>を</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアを開けます。</span>(Tôi mở cửa)</div><div class='gd-sec'>Cách phân biệt đơn giản: tự hỏi xem có “ai đó” đang làm gì lên đồ vật không. “Mở cửa” (có người mở) thì dùng tha động từ＋を; “cửa mở” (chỉ là trạng thái, không nhắc ai làm) thì dùng tự động từ＋が.</div><div class='gd-h'>Vài cặp thường gặp nhất</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がつきました。</span>(Đèn sáng rồi)</div><div class='gd-ex-line'>・<span class='gd-jp'>電気をつけてください。</span>(Làm ơn bật đèn)</div><div class='gd-ex-line'>・<span class='gd-jp'>授業が始まります。</span>(Sắp vào học rồi)</div><div class='gd-ex-line'>・<span class='gd-jp'>授業を始めます。</span>(Chúng ta bắt đầu giờ học)</div><div class='gd-ex-line'>・<span class='gd-jp'>財布が落ちました。</span>(Ví bị rơi rồi)</div><div class='gd-ex-line'>・<span class='gd-jp'>財布を落としました。</span>(Tôi làm rơi ví mất rồi)</div><div class='gd-sec'>Còn mấy cặp này nữa, bên trái là tự động từ, bên phải là tha động từ:<br><span class='gd-jp'>閉まる</span>／<span class='gd-jp'>閉める</span> (đóng)<br><span class='gd-jp'>消える</span>／<span class='gd-jp'>消す</span> (tắt, biến mất / tắt đi)<br><span class='gd-jp'>入る</span>／<span class='gd-jp'>入れる</span> (vào / cho vào)<br><span class='gd-jp'>出る</span>／<span class='gd-jp'>出す</span> (ra / lấy ra)<br>Cái nào là tự động từ, cái nào là tha động từ thì không có một quy tắc nào áp dụng cho tất cả, nên tốt nhất là <b>học từng cặp kèm câu ví dụ</b>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trợ từ và động từ phải ghép đúng cặp: <span class='gd-jp'>電気を消します</span> và <span class='gd-jp'>電気が消えます</span> đều đúng, còn 「電気を消えます」 thì sai.<br>・Nhờ người khác làm gì thì phải dùng tha động từ: <span class='gd-jp'>窓を閉めてください</span>, không thể nói 「窓が閉まってください」.<br>・<span class='gd-jp'>開く</span> ở đây đọc là <b>あく</b>. Chữ Hán này còn có cách đọc 「ひらく」 với cách dùng khác, tạm thời đừng trộn lẫn.<br>・<span class='gd-jp'>入る</span> và <span class='gd-jp'>出る</span> hay đi với địa điểm: <span class='gd-jp'>部屋に入ります</span> (vào phòng) dùng に; còn <span class='gd-jp'>家を出ます</span> (ra khỏi nhà) thì を chỉ “nơi rời đi”, không phải “vật bị tác động”, nên 出る vẫn là tự động từ.<br>・Tự động từ không chỉ nói về việc “tự xảy ra”: <span class='gd-jp'>行く</span>, <span class='gd-jp'>寝る</span> cũng là tự động từ, là hành động do chính người đó làm. Điểm mấu chốt là <b>có vật nào bị tác động hay không</b>.</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>Thêm 「〜ています」 vào hai loại động từ, nghĩa khác nhau khá nhiều:<br><span class='gd-jp'>窓が開いています。</span> (Cửa sổ đang mở) → chỉ tả trạng thái bạn nhìn thấy<br><span class='gd-jp'>夏はいつも窓を開けています。</span> (Mùa hè tôi lúc nào cũng mở cửa sổ) → nói về hành động và thói quen của con người</div><div class='gd-warn'>Mẹo nhỏ: nếu chỉ là nhìn thấy trạng thái “đang mở, đang sáng, đang đóng” thì dùng “が＋tự động từ ています”.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tha động từ thêm 「〜てあります」 nghĩa là “có người cố ý làm sẵn rồi để đó”: <span class='gd-jp'>窓が開けてあります。</span> (Cửa sổ đã được ai đó mở sẵn)</div>","n5-15":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「は」giống như <b>“Nói đến ～ thì…”</b> trong tiếng Việt. Bạn đặt thứ muốn nói lên đầu câu, như báo với người nghe “bây giờ mình nói về cái này nhé”, rồi mới nói nó như thế nào. <span class='gd-jp'>私は学生です。</span> nghĩa là “nói đến tôi thì là sinh viên”, tức là “Tôi là sinh viên”.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Chỉ cần thêm は ngay sau danh từ:<br><span class='gd-pair'><span class='gd-jp'>私</span> → <span class='gd-jp'>私は</span></span><span class='gd-pair'><span class='gd-jp'>伊藤さん</span> → <span class='gd-jp'>伊藤さんは</span></span><span class='gd-pair'><span class='gd-jp'>今日</span> → <span class='gd-jp'>今日は</span></span><br><b>Cách đọc rất quan trọng</b>: khi làm trợ từ, viết là <span class='gd-jp'>は</span> nhưng đọc là <b>wa</b>, cùng âm với <span class='gd-jp'>わ</span>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Giới thiệu, giải thích</span>Cách dùng cơ bản nhất: nói trước “ai / cái gì”, rồi nói “như thế nào”.</div><div class='gd-ex-line'>・<span class='gd-jp'>伊藤さんは建築家です。</span>(Anh 伊藤 là kiến trúc sư)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暑いですね。</span>(Hôm nay nóng nhỉ)</div><div class='gd-sec'><span class='gd-tag'>Nêu chủ đề trước, chi tiết sau</span>Trước は là “câu này đang nói về cái gì”, phía sau có thể xuất hiện thêm một nhân vật khác.</div><div class='gd-ex-line'>・<span class='gd-jp'>象は鼻が長いです。</span>(Voi thì vòi dài)</div><div class='gd-ex-line'>・<span class='gd-jp'>そのケーキは姉が焼きました。</span>(Cái bánh đó là chị gái tôi nướng)</div><div class='gd-sec'>Câu thứ hai nhiều người bị vướng: người nướng bánh là chị gái, không phải cái bánh. Vì vậy <b>trước は không nhất thiết là “người làm hành động”</b>, nó chỉ cho biết “câu này đang nói về cái gì”. Câu này nói về cái bánh, rồi bổ sung “là chị gái nướng”.</div><div class='gd-sec'><span class='gd-tag'>So sánh hai thứ</span>Dùng は ở cả hai vế sẽ tạo cảm giác đối chiếu: “cái này thì như vậy, còn cái kia thì khác”.</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーは好きですが、お茶はあまり飲みません。</span>(Cà phê thì tôi thích, còn trà thì ít uống)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・は làm trợ từ đọc là wa. Lời chào <span class='gd-jp'>こんにちは</span>, <span class='gd-jp'>こんばんは</span> có は ở cuối cũng đọc là wa. は trong các từ khác vẫn đọc là ha, như <span class='gd-jp'>はい</span>, <span class='gd-jp'>花</span>.<br>・Khi dùng từ để hỏi như 「誰」「どれ」 làm chủ ngữ của câu hỏi thì phải đi với が, không dùng は: <span class='gd-jp'>誰は来ましたか</span> là sai, phải nói <span class='gd-jp'>誰が来ましたか</span> (Ai đã đến vậy?).<br>・Chủ đề đã nói một lần thì phía sau có thể lược bỏ. Tiếng Việt hay nhắc “tôi” ở mỗi câu, còn tiếng Nhật đã nói <span class='gd-jp'>私は</span> một lần thì thường không lặp lại nữa, cứ nhắc mãi sẽ nghe rất dài dòng: <span class='gd-jp'>私は陳です。台湾から来ました。</span> (Tôi là 陳, đến từ Đài Loan)</div><div class='gd-h'>Phân biệt với mẫu na ná</div><div class='gd-sec'>は và が là cặp dễ lẫn nhất. Hãy xem cùng một tình huống: công ty có đồng nghiệp mới đến.<br>Mọi người chưa biết bạn, bạn tự giới thiệu: <span class='gd-jp'>私は陳です。</span> (Tôi là 陳) → điều mọi người muốn biết là “陳” ở <b>phía sau</b>.<br>Có người đang tìm bạn: <span class='gd-jp'>陳さんはどちらですか。</span> (Xin hỏi ai là anh/chị 陳 ạ?) Bạn giơ tay nói: <span class='gd-jp'>私が陳です。</span> (Chính tôi là 陳) → lúc này trọng tâm là “tôi” ở <b>phía trước</b>.<br>Ngoài ra, việc vừa nhìn thấy, vừa xảy ra ngay trước mắt cũng dùng が: <span class='gd-jp'>あ、バスが来ました。</span> (A, xe buýt đến rồi)</div><div class='gd-warn'>Mẹo nhỏ: dùng は thì trọng tâm nằm ở <b>phía sau は</b>; dùng が thì trọng tâm nằm ở <b>phía trước が</b>. Câu trả lời cho “ai? cái nào?” và việc vừa nhìn thấy thì dùng が.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Đổi は thành <b>も</b> thì nghĩa là “cũng”: <span class='gd-jp'>私も学生です。</span> (Tôi cũng là sinh viên). Lưu ý là thay thẳng chứ không chồng lên nhau, không có cách nói 「私はも」.</div>","n5-4":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Những từ dùng để miêu tả sự vật như \"lạnh\", \"đắt\", \"ngon\" trong tiếng Nhật gọi là <b>tính từ い</b>, vì chữ cuối của chúng đều là 「い」, ví dụ <span class='gd-jp'>寒い</span>、<span class='gd-jp'>高い</span>、<span class='gd-jp'>おいしい</span>.<br>Muốn nói \"lạnh\" một cách lịch sự, bạn thêm <b>です</b> ngay phía sau. Muốn nói \"không lạnh\", bạn đổi い ở cuối thành <b>く</b>, rồi thêm <b>ないです</b>.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'><span class='gd-tag'>Khẳng định</span>Giữ nguyên từ gốc rồi thêm です, không cần đụng đến い ở cuối.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いです</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いです</span></span></div><div class='gd-sec'><span class='gd-tag'>Phủ định</span>Đổi い ở cuối thành く, rồi thêm ないです.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → đổi い thành く → <span class='gd-jp'>寒く</span> → <span class='gd-jp'>寒くないです</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くないです</span></span><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしくないです</span></span><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きくないです</span></span></div><div class='gd-sec'>Trong sách giáo khoa bạn cũng sẽ gặp <span class='gd-jp'>寒くありません</span>, nghĩa giống hệt, chỉ nghe trang trọng hơn một chút. Nói chuyện hằng ngày chỉ cần dùng 「くないです」 là đủ rồi.</div><div class='gd-h'>Thử nói thật nhé</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしいです。</span>（Tô ramen này ngon）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は広くないです。</span>（Căn phòng này không rộng）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はあまり寒くないです。</span>（Hôm nay không lạnh lắm）</div><div class='gd-sec'>Tiếng Việt hay nói \"<b>rất</b> lạnh\", nhưng thật ra bản thân <span class='gd-jp'>寒いです</span> đã mang nghĩa đó rồi, không cần cố thêm 「とても」. Khi thật sự rất lạnh và muốn nhấn mạnh, bạn mới nói <span class='gd-jp'>とても寒いです</span>.<br>Ngoài ra, <span class='gd-jp'>あまり</span> đi với phủ định nghĩa là \"<b>không ～ lắm</b>\", nghe nhẹ nhàng hơn so với nói thẳng \"không ～\", người Nhật dùng rất thường xuyên.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>いい</span> là trường hợp ngoại lệ: phủ định là <b><span class='gd-jp'>よくないです</span></b>, không phải いくないです. Vì いい vốn bắt nguồn từ <span class='gd-jp'>よい</span>, nên khi biến đổi phải dùng よ. <span class='gd-jp'>かっこいい</span> cũng vậy, phủ định là <span class='gd-jp'>かっこよくないです</span>.<br>・Muốn nói \"không lạnh\", không được nói 寒いじゃないです. Phủ định của tính từ い luôn là đổi い thành く, không dùng じゃない.<br>・Đừng chèn thêm だ vào giữa: 寒いだです là sai. Muốn lịch sự thì nói <span class='gd-jp'>寒いです</span>, nói với bạn bè thì chỉ cần <span class='gd-jp'>寒い</span>.<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>嫌い</span>、<span class='gd-jp'>有名</span> nghe cũng có 「い」 ở cuối, nhưng chúng là tính từ な, phủ định là <span class='gd-jp'>きれいじゃないです</span>, không phải きれくない.</div><div class='gd-h'>Phân biệt với những dạng trông giống nhau</div><div class='gd-sec'>Cùng là nói \"căn phòng này không ～\", nhưng từ đứng trước thuộc loại nào thì cách phủ định sẽ khác:<br><b>Tính từ い</b>: đổi い thành く, thêm ないです<br>・<span class='gd-jp'>この部屋は明るくないです。</span>（Căn phòng này không sáng）<br><b>Tính từ な</b>: thêm じゃないです ở phía sau<br>・<span class='gd-jp'>この部屋は静かじゃないです。</span>（Căn phòng này không yên tĩnh）<br><b>Danh từ</b>: cũng thêm じゃないです ở phía sau<br>・<span class='gd-jp'>ここは私の部屋じゃないです。</span>（Đây không phải phòng của tôi）</div><div class='gd-warn'>Mẹo nhận biết: từ gốc kết thúc bằng 「い」 thì đổi い thành く rồi thêm ないです. Tính từ な và danh từ thì thêm thẳng じゃないです. Gặp きれい、嫌い、有名 nhớ cẩn thận, chúng là tính từ な.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thì quá khứ: <span class='gd-pair'><span class='gd-jp'>寒いです</span> → <span class='gd-jp'>寒かったです</span></span>（lúc trước đã lạnh）<br>Diễn tả sự thay đổi: <span class='gd-jp'>寒くなります</span>（sẽ trở nên lạnh）, dạng 「く」 dùng trong phủ định cũng sẽ xuất hiện lại ở đây.</div>","n5-5":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜です」 nghĩa là \"là ～\", còn 「〜でした」 là <b>\"(hồi đó) đã là ～\"</b>. Tiếng Việt kể chuyện quá khứ chỉ cần thêm \"hôm qua\", \"trước đây\" hoặc \"đã\" là xong; tiếng Nhật thì không được, <b>nói về quá khứ phải đổi です thành でした</b>.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'><span class='gd-tag'>Là</span>Thêm でした ngay sau danh từ.<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生でした</span></span><span class='gd-pair'><span class='gd-jp'>休みです</span> → <span class='gd-jp'>休みでした</span></span></div><div class='gd-sec'><span class='gd-tag'>Không phải</span>Dùng 「じゃありません」 ở hiện tại trước, rồi thêm でした phía sau.<br><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃありませんでした</span></span><br>Khi viết văn bản thì dạng trang trọng hơn là <span class='gd-jp'>ではありませんでした</span>, nghĩa giống nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は雨でした。</span>（Hôm qua trời mưa）</div><div class='gd-ex-line'>・<span class='gd-jp'>先週の月曜日は祝日でした。</span>（Thứ Hai tuần trước là ngày lễ）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は休みじゃありませんでした。</span>（Hôm qua không phải ngày nghỉ）</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Hỏi về quá khứ</span>Thêm か vào cuối câu là thành câu hỏi.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は休みでしたか。</span>（Hôm qua bạn nghỉ à?）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、休みでした。</span>（Vâng, tôi nghỉ）</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、休みじゃありませんでした。</span>（Không, tôi không nghỉ）</div><div class='gd-sec'><span class='gd-tag'>Kiểu nói với bạn bè</span>Khi nói với bạn thân, đổi でした thành <b>だった</b>, đổi じゃありませんでした thành <b>じゃなかった</b>.<br><span class='gd-pair'><span class='gd-jp'>雨でした</span> → <span class='gd-jp'>雨だった</span></span><span class='gd-pair'><span class='gd-jp'>休みじゃありませんでした</span> → <span class='gd-jp'>休みじゃなかった</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Theo thói quen tiếng Việt, chỉ cần có \"hôm qua\" ở đầu câu là đủ, nên dễ nói thành <span class='gd-jp'>昨日は休みです</span>. Tiếng Nhật phải sửa thành <span class='gd-jp'>休みでした</span>.<br>・Quá khứ của \"không phải\" là chỗ dễ ghép sai nhất: <span class='gd-jp'>学生じゃないでした</span>、<span class='gd-jp'>学生じゃでした</span> đều sai, phải nói <span class='gd-jp'>学生じゃありませんでした</span>.<br>・Trong khẩu ngữ hằng ngày bạn cũng hay nghe <span class='gd-jp'>学生じゃなかったです</span>, vẫn lịch sự và cũng đúng, nghe thấy đừng ngạc nhiên nhé.<br>・でした chỉ đi sau danh từ (và tính từ な). Tính từ い như <span class='gd-jp'>寒い</span>、<span class='gd-jp'>高い</span> không thể thêm でした trực tiếp: <span class='gd-jp'>寒いでした</span> là sai, phải nói <span class='gd-jp'>寒かったです</span>.</div><div class='gd-h'>Phân biệt với những dạng trông giống nhau</div><div class='gd-sec'>Cùng là kể chuyện \"hôm qua\", nhưng từ đứng trước khác loại thì phần đuôi câu cũng khác:<br><b>Danh từ</b> ＋ でした：<span class='gd-jp'>昨日は雨でした。</span>（Hôm qua trời mưa）<br><b>Động từ</b> đổi ます thành ました：<span class='gd-jp'>昨日は雨が降りました。</span>（Hôm qua trời đã mưa）<br><b>Tính từ い</b> đổi い thành かったです：<span class='gd-jp'>昨日は寒かったです。</span>（Hôm qua trời lạnh）<br><b>Tính từ な</b> giống danh từ, thêm でした：<span class='gd-jp'>昨日は静かでした。</span>（Hôm qua rất yên tĩnh）</div><div class='gd-warn'>Mẹo nhận biết: đứng trước là danh từ hoặc tính từ な thì dùng でした; đứng trước là động từ thì dùng ました; đứng trước là tính từ い (như 寒い、高い) thì dùng かったです.<br>Lưu ý: <span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span>、<span class='gd-jp'>嫌い</span> tuy kết thúc bằng い nhưng thuộc tính từ な, phải dùng でした, ví dụ <span class='gd-jp'>きれいでした</span>, không phải きれかったです.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Quá khứ của động từ <span class='gd-jp'>〜ました・〜ませんでした</span>, và quá khứ của tính từ い <span class='gd-jp'>〜かったです</span>, nhớ cả ba dạng này cùng nhau thì kể chuyện quá khứ sẽ không bị vấp nữa.</div>","n5-2":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ます」là <b>thể lịch sự</b> của tiếng Nhật, dùng với thầy cô, nhân viên cửa hàng, người mới quen. Với gia đình và bạn thân thì mới dùng cách nói không có ます. Muốn nói \"không (làm)\", bạn đổi ます thành <b>ません</b>. Khi mới học, <b>cứ dùng ます hết là an toàn nhất</b>, không sợ bất lịch sự.</div><div class='gd-h'>Một dạng, dùng cho cả hiện tại lẫn tương lai</div><div class='gd-sec'>Tiếng Nhật không có \"thì tương lai\" riêng. Thói quen thường ngày và việc sắp làm đều dùng「〜ます」, còn thời gian thì nhờ các từ như「毎日」「明日」「来週」để diễn đạt.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日コーヒーを飲みます。</span>(Mỗi ngày tôi uống cà phê: thói quen)</div><div class='gd-ex-line'>・<span class='gd-jp'>来週、京都へ行きます。</span>(Tuần sau tôi sẽ đi Kyoto: tương lai)</div><div class='gd-ex-line'>・<span class='gd-jp'>田村先生はお酒を飲みません。</span>(Thầy Tamura không uống rượu)</div><div class='gd-h'>Cách chia: trước tiên xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 1 (động từ 五段動詞)</b>: đổi âm cuối sang âm hàng「い」cùng hàng, rồi thêm ます.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → む đổi thành み → <span class='gd-jp'>飲みます</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行きます</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買います</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ります</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ 一段動詞)</b>: bỏ「る」ở cuối rồi thêm ます.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ます</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きます</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, cứ học thuộc)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ます</span>(きます)</span><br>Những từ dạng「danh từ＋する」như「勉強する」「出張する」cũng chia giống vậy: <span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span></div><div class='gd-sec'>Phủ định chỉ cần đổi ます thành ません, cả ba nhóm đều giống nhau: <span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べません</span></span></div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span> trông giống nhóm 2 nhưng thật ra là nhóm 1: phải là <span class='gd-jp'>帰ります</span>, không phải 帰ます.<br>・「ません」nghĩa là \"không (làm)\", không phải \"không thể\": <span class='gd-jp'>お酒を飲みません</span> là \"tôi không uống rượu\", không phải \"tôi không uống được\".<br>・ます chỉ gắn sau <b>động từ</b>. Muốn nói \"tôi là học sinh\" phải dùng <span class='gd-jp'>学生です</span>, không thể nói 学生ます.<br>・Âm「す」trong ます thường đọc rất nhẹ, nghe như \"mas\". Nghe thấy vậy bạn đừng nghi ngờ tai mình nhé.</div><div class='gd-h'>Phân biệt với dạng trông giống nhau</div><div class='gd-sec'>Nhiều bạn hay dùng ます cho cả câu \"tôi đang ~\", nhưng ます nói về <b>thói quen</b> hoặc <b>việc sắp làm</b>. Muốn nói \"đang làm\" thì phải dùng <b>ています</b>.<br><span class='gd-jp'>今、ご飯を食べます。</span>(Bây giờ tôi sắp ăn cơm: chưa bắt đầu ăn)<br><span class='gd-jp'>今、ご飯を食べています。</span>(Bây giờ tôi đang ăn cơm: đã bắt đầu ăn rồi)</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: chưa bắt đầu hoặc ngày nào cũng làm thì dùng ます; đang làm dở trên tay thì dùng ています.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Nói về chuyện quá khứ: <span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みました</span></span>(đã uống), <span class='gd-pair'><span class='gd-jp'>飲みません</span> → <span class='gd-jp'>飲みませんでした</span></span>(đã không uống).<br>Muốn rủ ai đó làm gì, bạn có thể học tiếp <span class='gd-jp'>〜ませんか</span> và <span class='gd-jp'>〜ましょう</span>.</div>","n5-3":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Những tính từ như <span class='gd-jp'>静か</span>(yên tĩnh), <span class='gd-jp'>きれい</span>(đẹp, sạch), <span class='gd-jp'>親切</span>(tốt bụng) được gọi trong tiếng Nhật là <b>な形容詞</b>. Nói \"yên tĩnh\" là <span class='gd-jp'>静かです</span>, nói \"không yên tĩnh\" là <span class='gd-jp'>静かじゃありません</span>. Cách dùng gần như câu danh từ, chỉ thêm một quy tắc: <b>khi đứng ngay trước danh từ, phải thêm「な」</b>.</div><div class='gd-h'>な形容詞 là gì</div><div class='gd-sec'>Đây là những từ miêu tả trạng thái, cảm giác; tiếng Việt thường dịch là \"rất ~\" hoặc \"thì ~\". Gọi là「な形容詞」vì khi nối với danh từ sẽ có thêm な. Phần「語幹」ghi trên thẻ chính là dạng gốc bạn thấy trong bảng từ vựng, ví dụ <span class='gd-jp'>静か</span>, không thêm gì phía sau.<br>Trước hết hãy nhớ những từ hay dùng nhất này:<br><span class='gd-jp'>静か</span>(yên tĩnh), <span class='gd-jp'>きれい</span>(đẹp, sạch sẽ), <span class='gd-jp'>元気</span>(khỏe, có sức sống), <span class='gd-jp'>有名</span>(nổi tiếng), <span class='gd-jp'>便利</span>(tiện lợi), <span class='gd-jp'>暇</span>(rảnh), <span class='gd-jp'>大変</span>(vất vả), <span class='gd-jp'>好き</span>(thích), <span class='gd-jp'>嫌い</span>(ghét), <span class='gd-jp'>上手</span>(giỏi)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>Khẳng định</span>Dạng gốc thêm <span class='gd-jp'>です</span> trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この喫茶店は静かです。</span>(Quán cà phê này yên tĩnh)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の近くは便利です。</span>(Gần ga rất tiện)</div><div class='gd-sec'><span class='gd-tag'>Phủ định</span>Dạng gốc thêm <span class='gd-jp'>じゃありません</span> trực tiếp, từ phía trước hoàn toàn không đổi.<br><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇じゃありません</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暇じゃありません。</span>(Hôm nay tôi không rảnh)</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は有名じゃありません。</span>(Thị trấn này không nổi tiếng lắm)</div><div class='gd-sec'>Phủ định còn hai cách nói khác, nghĩa giống nhau: <span class='gd-jp'>ではありません</span> trang trọng hơn, hay gặp trong sách giáo khoa và văn viết; <span class='gd-jp'>じゃないです</span> khẩu ngữ hơn nhưng vẫn lịch sự.</div><div class='gd-sec'><span class='gd-tag'>Đặt câu hỏi</span>Chỉ cần thêm <span class='gd-jp'>か</span> ở cuối.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は大変ですか。</span>(Công việc có vất vả không?)</div><div class='gd-h'>Đứng trước danh từ: phải thêm な</div><div class='gd-sec'>Muốn nói \"thị trấn yên tĩnh\", \"người tốt bụng\", bạn thêm <span class='gd-jp'>な</span> vào giữa. Lưu ý thứ tự khác tiếng Việt: tiếng Nhật đặt tính từ <b>trước</b> danh từ, còn tiếng Việt đặt sau (\"thị trấn yên tĩnh\"). Có thể xem な như một mối nối giữa tính từ và danh từ.<br><span class='gd-pair'><span class='gd-jp'>静か</span>＋<span class='gd-jp'>町</span> → <span class='gd-jp'>静かな町</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>静かな町です。</span>(Là một thị trấn yên tĩnh)</div><div class='gd-ex-line'>・<span class='gd-jp'>京都はきれいな所です。</span>(Kyoto là một nơi rất đẹp)</div><div class='gd-ex-line'>・<span class='gd-jp'>親切な人ですね。</span>(Đúng là một người tốt bụng nhỉ)</div><div class='gd-sec'>Cách nhớ rất đơn giản: <b>phía sau là です thì không thêm な; phía sau là danh từ thì mới thêm な</b>.</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>嫌い</span> kết thúc bằng「い」nên trông như い形容詞, nhưng thật ra là な形容詞. Phủ định là <span class='gd-jp'>きれいじゃありません</span>, không phải「きれくないです」.<br>・Trước です không thêm な: phải là <span class='gd-jp'>静かです</span>, không phải「静かなです」.<br>・Trước danh từ không được thiếu な, và cũng đừng tự thêm の: phải là <span class='gd-jp'>静かな町</span>, không phải「静か町」, cũng không phải「静かの町」.<br>・Đối tượng của <span class='gd-jp'>好き</span>, <span class='gd-jp'>嫌い</span> dùng <b>が</b>: <span class='gd-jp'>猫が好きです</span>(Tôi thích mèo). Tiếng Việt nói \"thích mèo\" giống kiểu động từ + tân ngữ nên nhiều bạn viết thành「猫を好きです」. Mới học cứ nhớ dùng が là đúng.<br>・Nói thẳng「嫌いです」nghe hơi gắt. Người Nhật hay dùng <span class='gd-jp'>あまり好きじゃありません</span>(không thích lắm), nghe nhẹ nhàng hơn nhiều.</div><div class='gd-h'>Phân biệt với dạng trông giống nhau</div><div class='gd-sec'>Cùng nói về \"quán này\", nhưng phủ định của ba loại từ khác nhau:<br><b>い形容詞</b>: い ở cuối đổi thành くない.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安くないです。</span>(Quán này không rẻ)</div><div class='gd-sec'><b>な形容詞</b>: phần thân giữ nguyên, phía sau thêm じゃありません.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店はきれいじゃありません。</span>(Quán này không sạch)</div><div class='gd-sec'><b>Danh từ</b>: giống な形容詞, phía sau thêm じゃありません.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここは銀行じゃありません。</span>(Đây không phải ngân hàng)</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: khi học từ vựng, hãy học luôn cả な, nhớ thành <span class='gd-jp'>きれいな</span>, <span class='gd-jp'>静かな</span>. Từ nào nói được dạng「～な＋danh từ」thì phủ định cứ thêm じゃありません; chỉ có い形容詞 mới đổi い thành くない.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thì quá khứ: đổi です thành でした: <span class='gd-jp'>昨日は暇でした。</span>(Hôm qua tôi rảnh)</div>","n5-6":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ました」là <b>thể quá khứ</b> của 「〜ます」, còn 「〜ませんでした」là thể quá khứ của 「〜ません」. Tiếng Việt chỉ cần thêm \"đã\" là xong: \"Hôm qua tôi đã đi\". Tiếng Nhật thì phải đổi đuôi động từ: <span class='gd-pair'><span class='gd-jp'>行きます</span> (đi) → <span class='gd-jp'>行きました</span> (đã đi)</span>. Giống ます, đây cũng là cách nói lịch sự, nói với thầy cô hay nhân viên cửa hàng đều không bị thất lễ.</div><div class='gd-h'>Cách chia: biết thể ます là xong</div><div class='gd-sec'>Lấy động từ \"uống\" làm ví dụ, bạn xem cả bốn dạng một lượt nhé:<br>Hiện tại, có làm: <span class='gd-jp'>飲みます</span> (uống)<br>Hiện tại, không làm: <span class='gd-jp'>飲みません</span> (không uống)<br>Quá khứ, đã làm: <span class='gd-jp'>飲みました</span> (đã uống)<br>Quá khứ, không làm: <span class='gd-jp'>飲みませんでした</span> (đã không uống)<br><br>Quy tắc chỉ có hai điều: <b>ます đổi thành ました</b>; <b>thêm でした sau ません</b>.<br>Vì đều bắt đầu chia từ thể ます nên quy tắc của ba nhóm động từ hoàn toàn giống nhau:<br><b>Nhóm 1 (động từ ngũ đoạn)</b>: <span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きました</span></span><br><b>Nhóm 2 (động từ nhất đoạn)</b>: <span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べました</span></span><br><b>Nhóm 3 (する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しました</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ました</span> (きました)</span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đã làm</span>Nói về việc đã xảy ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>先月、札幌へ行きました。</span> (Tháng trước tôi đã đi Sapporo)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、映画を見ました。</span> (Hôm qua tôi đã xem phim)</div><div class='gd-sec'><span class='gd-tag'>Không làm</span>Nói về việc đã không làm trong khoảng thời gian trong quá khứ.</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は朝ご飯を食べませんでした。</span> (Sáng nay tôi không ăn sáng)</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題をしませんでした。</span> (Tôi đã không làm bài tập)</div><div class='gd-sec'><span class='gd-tag'>Hỏi người khác</span>Thêm か ở cuối là thành câu hỏi.</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、何をしましたか。</span> (Cuối tuần bạn đã làm gì?)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Phủ định quá khứ là 「ません＋<b>でした</b>」. Nhiều người nói nhầm thành 「食べませんました」, như vậy là sai nhé.<br>・<span class='gd-jp'>来ました</span> đọc là <b>きました</b>, không phải こました.<br>・Chữ 「し」 trong 「ました」 thường đọc rất nhẹ, nghe giống như 「ma-shta」. Khi nghe, bạn đừng tưởng là bị thiếu mất một âm.<br>・Đừng dùng ませんでした để nói \"chưa ăn\". Khi bạn bè hỏi <span class='gd-jp'>もう食べましたか。</span> (Ăn rồi chưa?), nếu chưa ăn và lát nữa mới ăn, hãy trả lời <span class='gd-jp'>いいえ、まだです。</span> (Chưa). <span class='gd-jp'>食べませんでした</span> có nghĩa là \"lúc đó đã không ăn\", việc đó đã qua rồi.<br>・<span class='gd-jp'>分かりました</span> có nghĩa là \"tôi hiểu rồi, vâng ạ\", nói về trạng thái ở hiện tại chứ không phải chuyện quá khứ. Nhân viên hay đồng nghiệp đáp câu này với bạn nghĩa là \"đã rõ ạ\".</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Khi học thể quá khứ, dễ nhất là lẫn lộn giữa 「ました」 và 「でした」. Lấy \"bữa tiệc hôm qua\" làm ví dụ, bạn xem một lượt cho rõ:</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、パーティーに行きました。</span> (Hôm qua tôi đã đi dự tiệc: động từ dùng ました)</div><div class='gd-ex-line'>・<span class='gd-jp'>料理は和食でした。</span> (Món ăn là món Nhật: danh từ dùng でした)</div><div class='gd-ex-line'>・<span class='gd-jp'>会場はきれいでした。</span> (Hội trường rất đẹp: tính từ な dùng でした)</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span> (Rất vui: tính từ い dùng かったです)</div><div class='gd-sec'>Những lỗi thường gặp:<br>「学生ました」→ phải nói <span class='gd-jp'>学生でした</span><br>「行きでした」→ phải nói <span class='gd-jp'>行きました</span><br>「おいしいでした」→ phải nói <span class='gd-jp'>おいしかったです</span></div><div class='gd-warn'>Mẹo nhỏ để phân biệt: phía trước là động từ thì dùng ました; phía trước là danh từ hoặc tính từ な thì dùng でした; phía trước là tính từ い thì dùng かったです.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Khi nói chuyện với bạn bè, thể quá khứ sẽ đổi sang cách nói không có ます, gọi là \"thể た／thể なかった\": <span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>行きませんでした</span> → <span class='gd-jp'>行かなかった</span></span>.</div>","n5-7":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'><span class='gd-jp'>静かです</span> nghĩa là \"bây giờ yên tĩnh\". Muốn nói \"<b>trước đây</b> yên tĩnh\", bạn đổi <span class='gd-jp'>です</span> thành <span class='gd-jp'>でした</span>: <span class='gd-jp'>静かでした</span>. Giống như tiếng Việt thêm \"đã\" hay \"hồi đó\" vào câu, tiếng Nhật thì đổi phần đuôi sang dạng quá khứ. Cách chia này <b>giống hệt</b> danh từ (<span class='gd-jp'>学生でした</span>), học một là biết luôn hai.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Tính từ な là loại tính từ khi đứng trước danh từ phải thêm 「な」, ví dụ <span class='gd-jp'>静かな部屋</span>, <span class='gd-jp'>きれいな花</span>.<br>Bước 1: bỏ 「な」, phần còn lại gọi là \"gốc từ\" (phần thân chính).<br><span class='gd-pair'><span class='gd-jp'>静かな</span> → bỏ な → <span class='gd-jp'>静か</span></span><br>Bước 2: nối đuôi bạn cần vào phía sau.<br>Hiện tại: <span class='gd-jp'>静かです</span> (yên tĩnh) ／ <span class='gd-jp'>静かじゃありません</span> (không yên tĩnh)<br>Quá khứ: <span class='gd-jp'>静かでした</span> (trước đây yên tĩnh) ／ <span class='gd-jp'>静かじゃありませんでした</span> (trước đây không yên tĩnh)</div><div class='gd-sec'><span class='gd-tag'>Khẳng định quá khứ</span>Lúc đó là như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は暇でした。</span> (Hôm qua tôi rảnh)</div><div class='gd-ex-line'>・<span class='gd-jp'>テストは簡単でした。</span> (Bài kiểm tra rất dễ)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものとき、野菜が嫌いでした。</span> (Hồi nhỏ tôi ghét rau)</div><div class='gd-sec'><span class='gd-tag'>Phủ định quá khứ</span>Lúc đó không như vậy. Thường đi cùng <span class='gd-jp'>あまり</span> (không... lắm).</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋はあまりきれいじゃありませんでした。</span> (Căn phòng không sạch lắm)</div><div class='gd-ex-line'>・<span class='gd-jp'>あまり有名じゃありませんでした。</span> (Hồi đó không nổi tiếng lắm)</div><div class='gd-h'>Những cách nói khác hay nghe</div><div class='gd-sec'><span class='gd-tag'>Trang trọng hơn</span>Đổi <span class='gd-jp'>じゃ</span> thành <span class='gd-jp'>では</span>: <span class='gd-jp'>静かではありませんでした</span>, dùng khi viết văn hoặc trong tình huống trang trọng.<br><span class='gd-tag'>Lịch sự khẩu ngữ</span><span class='gd-jp'>静かじゃなかったです</span>, nghĩa giống nhau, rất hay nghe trong hội thoại hằng ngày.<br><span class='gd-tag'>Giữa bạn bè</span>Đổi でした thành <span class='gd-jp'>だった</span>, còn phủ định dùng <span class='gd-jp'>じゃなかった</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、暇だった。</span> (Hôm qua rảnh)</div><div class='gd-ex-line'>・<span class='gd-jp'>全然大変じゃなかった。</span> (Chẳng vất vả chút nào)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Phải bỏ 「な」: nói <span class='gd-jp'>静かでした</span>, không phải 「静かなでした」.<br>・<span class='gd-jp'>きれい</span>, <span class='gd-jp'>嫌い</span>, <span class='gd-jp'>有名</span> tuy kết thúc bằng 「い」 nhưng chúng là <b>tính từ な</b>: nói <span class='gd-jp'>きれいでした</span>, không phải 「きれいかったです」.<br>・Phủ định quá khứ đừng tự ghép thành 「静かじゃないでした」, cách đúng là <span class='gd-jp'>静かじゃありませんでした</span> hoặc <span class='gd-jp'>静かじゃなかったです</span>.<br>・Sau <span class='gd-jp'>あまり</span> nhất định phải là phủ định: <span class='gd-jp'>あまり暇じゃありませんでした</span>, không thể nói 「あまり暇でした」.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>Quá khứ của tính từ い</b> chia hoàn toàn khác: đổi い thành <span class='gd-jp'>かった</span> rồi thêm です. Cùng nói về khách sạn hôm qua ở:<br><span class='gd-jp'>ホテルは静かでした。</span> (Khách sạn rất yên tĩnh: tính từ な)<br><span class='gd-jp'>ホテルは高かったです。</span> (Khách sạn rất đắt: tính từ い)<br>Ngược lại, tính từ い cũng không thể gắn でした: không thể nói 「高いでした」.</div><div class='gd-sec'><b>になりました</b> nghĩa là \"<b>trở nên</b> ～\", nói về sự thay đổi chứ không chỉ là trạng thái trong quá khứ:<br><span class='gd-jp'>町は静かでした。</span> (Hồi đó thị trấn này rất yên tĩnh)<br><span class='gd-jp'>町は静かになりました。</span> (Thị trấn này đã trở nên yên tĩnh: trước đây không yên tĩnh)</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: trước hết xem có phải tính từ な không, nếu phải thì \"bỏ な＋でした\"; còn khi muốn nói \"đã trở nên ～\" thì dùng <span class='gd-jp'>になりました</span>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tiếp theo hãy xem quá khứ của tính từ い <span class='gd-jp'>〜かったです</span>. Luyện cả hai loại cùng nhau thì bạn sẽ không bị lẫn nữa.</div>","n5-8":"<div class='gd-h'>Nắm ý chính trong một câu</div><div class='gd-sec'>Muốn nói「hôm qua <b>lạnh</b>」「mì ramen <b>ngon</b>」, tức là cảm nhận về chuyện đã qua, thì bạn dùng mẫu câu này. Tiếng Việt chỉ cần thêm「hôm qua」hay「đã」là xong. Còn tính từ い trong tiếng Nhật (tính từ kết thúc bằng「い」, như <span class='gd-jp'>暑い</span>、<span class='gd-jp'>おいしい</span>) thì <b>bản thân tính từ phải biến đổi</b>: <span class='gd-pair'><span class='gd-jp'>暑いです</span> → <span class='gd-jp'>暑かったです</span></span>.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'><span class='gd-tag'>Quá khứ・khẳng định</span>Bỏ「い」ở cuối, thêm「かったです」.<br><span class='gd-pair'><span class='gd-jp'>暑い</span> → bỏ い → <span class='gd-jp'>暑かったです</span></span><br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → <span class='gd-jp'>おいしかったです</span></span><span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しかったです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は寒かったです。</span>（Hôm qua trời lạnh）</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはおいしかったです。</span>（Tô ramen này ngon）</div><div class='gd-sec'><span class='gd-tag'>Quá khứ・phủ định</span>Đổi「い」thành「く」, thêm「なかったです」.<br><span class='gd-pair'><span class='gd-jp'>難しい</span> → đổi い thành く → <span class='gd-jp'>難しくなかったです</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>テストは難しくなかったです。</span>（Bài kiểm tra không khó）</div><div class='gd-sec'>Một cách nói khác là <span class='gd-jp'>難しくありませんでした</span>, nghĩa giống hệt, nghe trang trọng hơn một chút, cả hai đều đúng.</div><div class='gd-sec'><span class='gd-tag'>Một trường hợp đặc biệt</span><span class='gd-jp'>いい</span> (tốt) khi chia phải đổi về <span class='gd-jp'>よい</span> trước rồi mới chia, bạn cứ học thuộc luôn nhé:<br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よかったです</span></span>（rất tốt）、<span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくなかったです</span></span>（không tốt）</div><div class='gd-ex-line'>・<span class='gd-jp'>天気はよくなかったです。</span>（Thời tiết không được tốt lắm）</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'>Bạn đi du lịch về, người khác hỏi cảm tưởng, thì sẽ là một hỏi một đáp như thế này:</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行はどうでしたか。</span>（Chuyến du lịch thế nào?）</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>（Rất vui）</div><div class='gd-sec'>Câu hỏi dùng <span class='gd-jp'>でした</span>, nhưng câu trả lời lại là <span class='gd-jp'>楽しかったです</span>. Đừng để câu hỏi dẫn đi rồi nói thành「楽しいでした」nhé.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Không được nói</b> <span class='gd-jp'>暑いでした</span>. Quá khứ của tính từ い dựa vào「かった」, không phải thêm でした.<br>・Cũng đừng nói thành <span class='gd-jp'>暑かったでした</span>. 「かった」đã là quá khứ rồi, です phía sau chỉ để câu lịch sự, không cần đổi thành でした nữa.<br>・Giữa「かった」có っ nhỏ, phải ngắt một nhịp: あつ<b>か</b>っ<b>た</b>. Đọc thành「あつかた」nghe sẽ rất lạ.<br>・<span class='gd-jp'>いい</span> không thể chia thành「いかったです」「いくなかったです」, luôn phải bắt đầu chia từ <span class='gd-jp'>よ</span>.<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span> tuy cuối từ có âm「い」nhưng là tính từ な, không thể chia thành「きれかったです」, phải nói <span class='gd-jp'>きれいでした</span>.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng nói về「chuyến du lịch tuần trước」:<br><b>Tính từ い</b>：<span class='gd-jp'>ホテルは高かったです。</span>（Khách sạn rất đắt）<br><b>Tính từ な</b>：<span class='gd-jp'>ホテルはきれいでした。</span>（Khách sạn rất đẹp）<br><b>Danh từ</b>：<span class='gd-jp'>天気は雨でした。</span>（Thời tiết là mưa）<br>Tính từ い tự biến thành「かった」, còn tính từ な và danh từ thì đổi です thành でした.</div><div class='gd-warn'>Mẹo phân biệt: trước hết xem từ đó trong từ điển có phải tính từ い kết thúc bằng「い」không. Nếu phải thì dùng「〜かったです」; nếu không (như きれい、元気、雨) thì dùng「〜でした」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bỏ です đi là cách nói giữa bạn bè: <span class='gd-jp'>昨日、寒かった。</span>（Hôm qua lạnh quá）. Bạn cũng có thể học tiếp「〜くなります」, dùng để nói「trở nên ～」: <span class='gd-jp'>寒くなりました。</span>（Trời trở lạnh rồi）</div>","n5-9":"<div class='gd-h'>Nắm ý chính trong một câu</div><div class='gd-sec'>「〜ませんか」tương đương với <b>「Bạn có muốn cùng ～ không?」</b> trong tiếng Việt. Nhìn mặt chữ thì giống「Bạn không ～ à?」, nhưng khi rủ rê, người Nhật dùng nó để hỏi một cách khéo léo: 「Bạn có muốn ～ không?」Quyền quyết định được giao cho đối phương nên họ dễ từ chối hơn, vì thế nghe rất lịch sự.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Rủ rê</span>Rủ đối phương cùng đi đâu đó, cùng làm gì đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>今度の日曜日、山登りに行きませんか。</span>（Chủ nhật này bạn có muốn đi leo núi không?）</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に昼ご飯を食べませんか。</span>（Cùng ăn trưa nhé?）</div><div class='gd-sec'><span class='gd-tag'>Mời ăn uống, gợi ý</span>Đưa đồ cho đối phương ăn, uống, hoặc gợi ý họ làm việc gì đó, cũng rất hay dùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、食べませんか。</span>（Bạn ăn bánh này không?）</div><div class='gd-ex-line'>・<span class='gd-jp'>少し休みませんか。</span>（Nghỉ một chút nhé?）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Đổi động từ sang dạng ます trước, rồi đổi「ます」thành「<b>ませんか</b>」là xong.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きませんか</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べませんか</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しませんか</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ませんか</span>（きませんか）</span><br>Thực ra chính là「ません」(không ～) cộng thêm「か」của câu hỏi.</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>〜でも〜ませんか</span>Thêm「でも」sau danh từ, nghĩa là「～ chẳng hạn」, giúp lời mời thoải mái hơn, không tạo áp lực.</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーでも飲みませんか。</span>（Uống tách cà phê hay gì đó nhé?）</div><div class='gd-sec'><span class='gd-tag'>Cách trả lời</span>Đồng ý: <span class='gd-jp'>いいですね。</span>（Hay đấy）、<span class='gd-jp'>ぜひ。</span>（Nhất định rồi）<br>Từ chối: <span class='gd-jp'>すみません、その日はちょっと…。</span>（Xin lỗi, hôm đó hơi bận một chút…）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đừng để trực giác của tiếng Việt đánh lừa: khi rủ rê, <span class='gd-jp'>行きませんか</span> là「Bạn có muốn đi không?」, không phải「Bạn không đi à?」.<br>・Khi từ chối, nói thẳng <span class='gd-jp'>いいえ、行きません。</span>（Không, tôi không đi）nghe rất cứng và dễ làm người ta tự ái. Người Nhật quen nói「<span class='gd-jp'>ちょっと…</span>」, nói lửng câu là đối phương hiểu ngay.<br>・Muốn nói「để <b>tôi</b> giúp bạn ～ nhé」thì không dùng ませんか. <span class='gd-jp'>持ちませんか</span> là bảo đối phương cầm; còn「Để tôi cầm giúp nhé?」phải nói <span class='gd-jp'>持ちましょうか</span>.<br>・Với bạn thân thì không cần khách sáo thế, cứ dùng thể thường và lên giọng cuối câu: <span class='gd-jp'>行かない？</span>（Đi không?）</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng một tình huống, hãy xem đoạn hội thoại rủ đi xem phim:<br><b>ませんか</b>＝chưa quyết định, hỏi ý muốn của đối phương trước: <span class='gd-jp'>一緒に映画を見ませんか。</span>（Cùng đi xem phim nhé?）<br><b>ましょう</b>＝đã thống nhất, hoặc cả hai đều muốn làm, thúc nhẹ một cái: <span class='gd-jp'>いいですね。見ましょう。</span>（Hay đấy, đi xem thôi）<br><b>ましょうか</b>＝chủ động đề nghị giúp「để tôi ～ nhé?」: <span class='gd-jp'>チケット、買いましょうか。</span>（Để tôi mua vé nhé?）</div><div class='gd-sec'>Vì vậy thứ tự thường gặp nhất là: rủ bằng「ませんか」trước, khi đối phương gật đầu thì dùng「ましょう」để cùng chốt. Vừa mở miệng đã nói「ましょう」thì hơi giống như quyết định thay người ta mà chưa hỏi ý kiến.</div><div class='gd-warn'>Mẹo phân biệt: còn đang hỏi đối phương「có muốn không」thì dùng ませんか; đã thống nhất「vậy nhé」thì dùng ましょう; muốn nói「để tôi giúp bạn」thì dùng ましょうか.</div>","n5-10":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜なります」nghĩa là <b>「trở nên ～」「trở thành ～」</b>. Thời tiết từ nóng sang lạnh, căn phòng từ bừa bộn thành sạch sẽ, đứa trẻ lớn lên thành người lớn… Chỉ cần là <b>chuyển từ trạng thái này sang trạng thái khác</b>, tiếng Nhật đều dùng なります.</div><div class='gd-h'>Cách nối: xem trước đó là loại từ nào</div><div class='gd-sec'><b>Tính từ い</b>: đổi 「い」 ở cuối thành 「く」, rồi thêm なります.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → đổi い thành く → <span class='gd-jp'>寒くなります</span></span><br><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きくなります</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安くなります</span></span></div><div class='gd-sec'><b>Tính từ な</b>: thêm 「に」 phía sau, rồi thêm なります.<br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいになります</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気になります</span></span><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きになります</span></span></div><div class='gd-sec'><b>Danh từ</b>: giống tính từ な, thêm 「に」.<br><span class='gd-pair'><span class='gd-jp'>春</span> → <span class='gd-jp'>春になります</span></span><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者になります</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>寒くなりましたね。</span>（Trời lạnh rồi nhỉ）</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋がきれいになりました。</span>（Căn phòng sạch sẽ rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本が好きになりました。</span>（Tôi đã yêu thích Nhật Bản）</div><div class='gd-ex-line'>・<span class='gd-jp'>来月、二十歳になります。</span>（Tháng sau tôi tròn hai mươi tuổi）</div><div class='gd-h'>Chọn なります hay なりました</div><div class='gd-sec'>Chữ 「rồi」 trong câu 「lạnh rồi」 của tiếng Việt tương ứng với <b>なりました</b>: nghĩa là sự thay đổi đã xảy ra, và bây giờ đang ở trạng thái đó.<br>Còn <b>なります</b> là 「sẽ trở nên ～」「sắp ～」, nói về việc chưa xảy ra, hoặc việc lần nào cũng như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>もうすぐ夏になります。</span>（Sắp sang hè rồi）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んで、よくなりました。</span>（Uống thuốc xong, khỏe hơn nhiều rồi）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>いい</span> là trường hợp ngoại lệ: phải nói <span class='gd-jp'>よくなります</span>, không được nói いくなります. Bệnh đỡ hơn, thời tiết khá lên đều nói <span class='gd-jp'>よくなりました</span>.<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>きらい</span>、<span class='gd-jp'>有名</span> tuy kết thúc bằng âm 「い」 nhưng lại là tính từ な: nói <span class='gd-jp'>きれいになります</span>, không phải きれくなります.<br>・Với danh từ và tính từ な, không được bỏ quên 「に」: <span class='gd-jp'>先生になりました</span>, không phải 先生なりました.<br>・Tiếng Việt nói 「trời lạnh rồi」, nên nhiều bạn dịch thẳng thành <span class='gd-jp'>寒いです</span>. Câu này chỉ có nghĩa 「bây giờ đang lạnh」, không có cảm giác 「trở nên」; muốn nhấn mạnh là trời đã chuyển lạnh thì phải nói <span class='gd-jp'>寒くなりました</span>.<br>・Chủ thể thay đổi đứng trước <span class='gd-jp'>が</span> (hoặc <span class='gd-jp'>は</span>), không phải を: <span class='gd-jp'>部屋がきれいになりました</span>.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>Bài sau có 「〜くします・〜にします」 chỉ khác một chữ nhưng nghĩa lại khác. Cùng là chuyện căn phòng sạch sẽ:<br><b>なります</b> = nói <b>sự vật trở nên</b> như thế nào, trọng tâm là kết quả: <span class='gd-jp'>部屋がきれいになりました。</span>（Căn phòng sạch sẽ rồi）<br><b>します</b> = nói <b>ai đó làm cho sự vật thành</b> như thế nào, trọng tâm là người ra tay: <span class='gd-jp'>部屋をきれいにしました。</span>（Tôi đã dọn phòng sạch sẽ rồi）<br>Thêm một cặp nữa: <span class='gd-jp'>音が大きくなりました。</span>（Âm thanh to lên rồi）／<span class='gd-jp'>音を小さくしてください。</span>（Làm ơn vặn nhỏ âm thanh lại）</div><div class='gd-warn'>Mẹo phân biệt: nếu tiếng Việt là 「trở nên ～」 thì dùng <b>が＋なります</b>; nếu là 「làm cho ～ thành ～」 thì dùng <b>を＋します</b>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Động từ không thể nối trực tiếp với なります. Muốn nói 「đã trở nên làm được ～」, phải dùng 「〜ようになります」 của N4: <span class='gd-jp'>日本語が話せるようになりました。</span>（Tôi đã nói được tiếng Nhật rồi）</div>","n5-11":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜くします／〜にします」nghĩa là <b>「làm cho ～ thành ～」</b>. Ví dụ 「vặn nhỏ âm thanh」「dọn phòng cho sạch sẽ」: trọng tâm là <b>có người ra tay</b> thay đổi, chứ không phải đồ vật tự thay đổi.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Tính từ い</b>: bỏ 「い」 ở cuối, đổi thành 「く」, rồi thêm します.<br><span class='gd-pair'><span class='gd-jp'>短い</span> → đổi い thành く → <span class='gd-jp'>短くします</span></span><br><span class='gd-pair'><span class='gd-jp'>小さい</span> → <span class='gd-jp'>小さくします</span></span><span class='gd-pair'><span class='gd-jp'>暖かい</span> → <span class='gd-jp'>暖かくします</span></span></div><div class='gd-sec'><b>Tính từ な</b>: thêm trực tiếp 「にします」.<br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいにします</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かにします</span></span></div><div class='gd-sec'><b>Danh từ</b>: cũng thêm trực tiếp 「にします」.<br><span class='gd-pair'><span class='gd-jp'>子どもの部屋</span> → <span class='gd-jp'>子どもの部屋にします</span></span></div><div class='gd-sec'>Sau thứ bị thay đổi dùng <b>を</b>, vì đó là đối tượng chịu tác động của hành động:</div><div class='gd-ex-line'>・<span class='gd-jp'>音を小さくしてください。</span>（Làm ơn vặn nhỏ âm thanh lại）</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上をきれいにします。</span>（Dọn mặt bàn cho sạch sẽ）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋を子どもの部屋にします。</span>（Sẽ biến căn phòng này thành phòng của con）</div><div class='gd-h'>Dạng hay nghe nhất</div><div class='gd-sec'><span class='gd-tag'>Nhờ người khác thay đổi</span>Thêm 「てください」 phía sau để nhờ đối phương làm cho thứ gì đó thành trạng thái nào đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>静かにしてください。</span>（Xin hãy giữ yên lặng）</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少し安くしてください。</span>（Bớt giá thêm một chút nhé）</div><div class='gd-sec'><span class='gd-tag'>Gọi món・Đưa ra lựa chọn</span>Danh từ＋にします cũng rất hay dùng để nói 「tôi chọn ～」「quyết định ～」, đặc biệt hay nghe khi gọi món ở nhà hàng.</div><div class='gd-ex-line'>・<span class='gd-jp'>私はコーヒーにします。</span>（Tôi chọn cà phê）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行は京都にしました。</span>（Chuyến du lịch này tôi đã quyết định đi Kyoto）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Phải bỏ 「い」 của tính từ い trước: là <span class='gd-jp'>短くします</span>, không phải 「短いくします」, cũng không phải 「短いにします」.<br>・<span class='gd-jp'>きれい</span> tuy kết thúc bằng い nhưng là tính từ な: là <span class='gd-jp'>きれいにします</span>, không phải 「きれくします」.<br>・<span class='gd-jp'>いい</span> phải đổi thành <span class='gd-jp'>よく</span>: <span class='gd-jp'>この町をよくしたいです。</span>（Tôi muốn làm cho thành phố này tốt đẹp hơn）, không phải 「いくします」.<br>・Thứ muốn thay đổi dùng <b>を</b>, đừng viết thành が.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'><b>くなります／になります</b> = sự vật <b>tự trở nên</b> như vậy, dùng <b>が</b>:<br><span class='gd-jp'>部屋が暖かくなりました。</span>（Phòng ấm lên rồi: có thể là do trời nắng）<br><b>くします／にします</b> = <b>có người ra tay</b> làm cho nó thành như vậy, dùng <b>を</b>:<br><span class='gd-jp'>部屋を暖かくしました。</span>（Tôi đã làm cho phòng ấm lên: ví dụ như bật máy sưởi）</div><div class='gd-warn'>Mẹo phân biệt: nếu nói được 「làm cho ～ thành ～」 thì dùng <b>を＋します</b>; nếu chỉ nói được 「～ trở nên ～」 thì dùng <b>が＋なります</b>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Danh từ＋にします có thể diễn tả 「quyết định chọn ～」; còn nếu điều quyết định là làm một việc gì đó, sau này bạn sẽ học động từ＋ことにします: <span class='gd-jp'>日本へ行くことにしました。</span>（Tôi đã quyết định đi Nhật）</div>","n5-12":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ましょう」nghĩa là <b>「cùng ～ nhé / ～ thôi」</b>. Giống như khi bạn rủ bạn học «mình đi thôi», «mình nghỉ một chút nhé», tiếng Nhật sẽ là <span class='gd-jp'>行きましょう</span>、<span class='gd-jp'>休みましょう</span>. Đây là cách nói lịch sự, dùng được với thầy cô, đồng nghiệp và cả người mới quen.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'>Bạn chỉ cần đưa động từ về dạng「〜ます」rồi <b>đổi ます thành ましょう</b>, không cần quan tâm động từ thuộc nhóm nào.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きましょう</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べましょう</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しましょう</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来ましょう</span></span></div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Rủ đối phương cùng làm</span>Khi mọi người cùng làm một việc gì đó, câu này thường đi với <span class='gd-jp'>一緒に</span> (cùng nhau).</div><div class='gd-ex-line'>・<span class='gd-jp'>一緒に帰りましょう。</span>（Mình cùng về nhà nhé）</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと休みましょう。</span>（Mình nghỉ một chút nhé）</div><div class='gd-sec'><span class='gd-tag'>Hô bắt đầu</span>Thầy cô khi vào lớp hay người chủ trì cuộc họp rất hay nói như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>じゃあ、始めましょう。</span>（Vậy chúng ta bắt đầu nhé）</div><div class='gd-h'>Thêm か ở cuối: ましょうか</div><div class='gd-sec'><span class='gd-tag'>Để mình giúp nhé?</span>Chủ động đề nghị giúp đối phương một việc gì đó, nghe rất chu đáo.</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物を持ちましょうか。</span>（Để mình xách hành lý giúp bạn nhé?）</div><div class='gd-sec'><span class='gd-tag'>Cùng bàn bạc</span>Hai bên đã quyết định làm cùng nhau rồi, giờ hỏi thêm chi tiết, phía trước thường có「何」「どこ」「何時」.</div><div class='gd-ex-line'>・<span class='gd-jp'>何時に会いましょうか。</span>（Mình gặp nhau lúc mấy giờ nhỉ?）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・ます phải được <b>thay thế</b>, không phải thêm vào phía sau: đúng là <span class='gd-jp'>行きましょう</span>, không phải「行きますましょう」.<br>・「ましょう」phải đọc kéo dài <b>ましょー</b>, đừng đọc cụt thành「ましょ」.<br>・Ý nghĩa của nó <b>có bao gồm cả bạn</b>, không phải bảo đối phương tự đi làm. Muốn nói «bạn hãy làm ～» thì dùng「〜てください」. Những biển báo ngoài đường như <span class='gd-jp'>ゴミは持ち帰りましょう</span> (hãy mang rác về) là cách dùng đặc biệt, nhẹ nhàng hơn; khi tự nói chuyện thì bạn chưa nên dùng kiểu này.<br>・Lần đầu rủ ai đó mà chưa biết họ có muốn đi không, nói thẳng「行きましょう」nghe hơi như bạn đã quyết định thay họ. Lúc này hỏi bằng「〜ませんか」sẽ lịch sự hơn.</div><div class='gd-h'>Phân biệt với những mẫu giống nhau</div><div class='gd-sec'>Hãy lấy cùng một tình huống «rủ đi xem phim». Ba mẫu này thường xuất hiện nối tiếp nhau:<br><b>ませんか</b>＝hỏi trước xem đối phương có muốn không: <span class='gd-jp'>映画を見ませんか。</span>（Bạn có muốn đi xem phim không?）<br><b>ましょう</b>＝đã đồng ý, cùng tiến hành: <span class='gd-jp'>ええ、見ましょう。</span>（Ừ, đi xem thôi）<br><b>ましょうか</b>＝hỏi ý kiến đối phương: <span class='gd-jp'>何を見ましょうか。</span>（Mình xem phim nào nhỉ?）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: đối phương chưa đồng ý thì dùng「ませんか」; đã thống nhất, cùng làm thì dùng「ましょう」; muốn hỏi ý kiến đối phương, hoặc chủ động đề nghị giúp thì dùng「ましょうか」.</div><div class='gd-h'>Sau khi học xong có thể học tiếp</div><div class='gd-sec'>Với bạn thân thì không cần khách sáo như vậy, bạn có thể đổi sang cách nói thoải mái hơn: <span class='gd-pair'><span class='gd-jp'>行きましょう</span> → <span class='gd-jp'>行こう</span></span>. Phần này sẽ được dạy ở N4 trong bài «thể ý chí».</div>","n5-13":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Cùng một câu, tiếng Nhật có hai cách nói. <b>Thể lịch sự</b> là <b>phiên bản lịch sự</b> có「です・ます」, còn <b>thể thường</b> là <b>phiên bản dành cho bạn bè</b>, bỏ です・ます đi. Ý nghĩa hoàn toàn giống nhau, chỉ khác ở sắc thái. Giống như khi nhắn tin cho sếp, bạn viết «Dạ vâng, ngày mai em sẽ có mặt», còn với bạn bè thì chỉ trả lời «ok, mai tới».</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Thể lịch sự</span>Dùng với thầy cô, cấp trên, nhân viên cửa hàng, khách hàng, người gặp lần đầu và cả người lớn tuổi hơn bạn mà chưa thân. Khi không biết nên dùng thể nào, cứ dùng thể lịch sự thì chắc chắn không bị thất lễ.</div><div class='gd-sec'><span class='gd-tag'>Thể thường</span>Dùng với người nhà, bạn thân, bạn học, người nhỏ tuổi hơn bạn. Viết nhật ký, lẩm bẩm một mình, ghi chú cho bản thân cũng dùng thể thường, vì không có đối tượng nào cần giữ lễ.</div><div class='gd-h'>Cùng một câu, hai cách nói</div><div class='gd-sec'>Muốn hỏi «Ngày mai bạn có đi không?»</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、行きますか。</span>（Ngày mai thầy/cô có đi không ạ?: nói với thầy cô）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、行きます。</span>（Vâng, em sẽ đi）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、行く？</span>（Mai đi không?: nói với bạn bè）</div><div class='gd-ex-line'>・<span class='gd-jp'>うん、行く。</span>（Ừ, đi）</div><div class='gd-sec'>Chú ý câu hỏi kiểu bạn bè: <b>か ở cuối câu biến mất, thay vào đó là lên giọng</b>. Câu trả lời「はい」cũng đổi thành「うん」.</div><div class='gd-h'>Cách đổi: từ bản lịch sự sang bản bạn bè</div><div class='gd-sec'><b>Danh từ, tính từ な</b>: đổi です thành だ.<br><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かだ</span></span><br>Phủ định và quá khứ cũng đổi theo:<br><span class='gd-pair'><span class='gd-jp'>学生じゃありません</span> → <span class='gd-jp'>学生じゃない</span></span><span class='gd-pair'><span class='gd-jp'>学生でした</span> → <span class='gd-jp'>学生だった</span></span></div><div class='gd-sec'><b>Tính từ い</b>: chỉ cần bỏ です đi là xong, <b>không thêm だ</b>.<br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高い</span></span><span class='gd-pair'><span class='gd-jp'>高くないです</span> → <span class='gd-jp'>高くない</span></span><span class='gd-pair'><span class='gd-jp'>高かったです</span> → <span class='gd-jp'>高かった</span></span></div><div class='gd-sec'><b>Động từ</b>: đưa thể ます về thể từ điển, tức là dạng bạn tra thấy trong từ điển.<br>Nhóm 1 (động từ godan): âm đứng trước ます đổi thành âm hàng「う」cùng hàng với nó.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → き đổi thành く → <span class='gd-jp'>行く</span></span><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲む</span></span><br>Nhóm 2 (động từ ichidan): bỏ ます, thêm る.<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べる</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見る</span></span><br>Nhóm 3 (する・来る): cứ học thuộc thôi.<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>する</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来る</span>（くる）</span><br>Một số dạng thường gặp khác: <span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>読んでいます</span> → <span class='gd-jp'>読んでいる</span></span><br>Cách chia chi tiết của phủ định và quá khứ sẽ được dạy từng bước trong các bài «thể từ điển・thể ない» và «thể た».</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tính từ い không thêm だ: chỉ nói <span class='gd-jp'>高い</span> là đủ,「高いだ」là sai.<br>・Khi trò chuyện với bạn bè, nói trống không「<span class='gd-jp'>雨だ。</span>」nghe khá cứng, như đang tự lẩm bẩm hoặc thông báo điều gì đó. Thường thì người ta sẽ thêm よ、ね: <span class='gd-jp'>明日、雨だよ。</span>（Mai trời mưa đó）<br>・Câu hỏi thể thường của danh từ, tính từ な phải bỏ だ đi: <span class='gd-jp'>学生？</span>（Bạn là sinh viên à?）, không nói「学生だ？」.<br>・Thể thường không phải là «bất lịch sự» mà là «rất thân». Dùng thể thường với thầy cô là thất lễ; ngược lại, nếu cứ nói です・ます mãi với bạn thân thì họ sẽ thấy bạn xa cách, như đang giận vậy.<br>・Với cùng một người, người mới học nên chọn cố định một thể, đừng câu này ます, câu kia thể thường, nghe sẽ rất lộn xộn.<br>・<span class='gd-jp'>読んでいる</span> trong văn nói thường được rút gọn thành <span class='gd-jp'>読んでる</span>, khi nghe bạn cần biết đó là cùng một nghĩa.</div><div class='gd-h'>Sau khi học xong có thể học tiếp</div><div class='gd-sec'>Thể thường không chỉ dùng khi trò chuyện. Rất nhiều mẫu ngữ pháp bắt buộc phải đi sau thể thường, dù cả câu vẫn lịch sự: <span class='gd-jp'>明日は雨だと思います。</span>（Tôi nghĩ ngày mai trời sẽ mưa）<br>Bước tiếp theo bạn có thể xem bài «Tổng hợp thể thông thường», nơi tổng hợp một lượt hiện tại, quá khứ, khẳng định, phủ định của từng loại từ.</div>","n5-17":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「の」tương đương với <b>“của”</b> trong tiếng Việt. Nó nối hai danh từ với nhau, danh từ đứng trước bổ nghĩa cho danh từ đứng sau: <span class='gd-jp'>私の本</span>＝sách của tôi. Chú ý: thứ tự <b>ngược</b> với tiếng Việt. Tiếng Nhật nói “của ai / ở đâu” trước, rồi mới đến đồ vật. Còn tiếng Việt nói đồ vật trước rồi mới đến “của ai”.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ A＋の＋danh từ B＝“B của A”. B mới là nhân vật chính, A chỉ bổ sung để cho biết đó là B nào.<br><span class='gd-pair'><span class='gd-jp'>弟</span>＋<span class='gd-jp'>車</span> → <span class='gd-jp'>弟の車</span></span> (xe của em trai)<br><span class='gd-pair'><span class='gd-jp'>数学</span>＋<span class='gd-jp'>教科書</span> → <span class='gd-jp'>数学の教科書</span></span> (sách giáo khoa toán)</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Của ai</span>Nói đồ vật đó là của ai.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の本です。</span> (Đây là sách của tôi.)</div><div class='gd-sec'><span class='gd-tag'>Thuộc về đâu</span>Nói một người thuộc công ty nào, trường nào. Rất hay dùng khi tự giới thiệu hoặc gọi điện thoại.</div><div class='gd-ex-line'>・<span class='gd-jp'>さくら銀行の山田です。</span> (Tôi là Yamada của ngân hàng Sakura.)</div><div class='gd-sec'><span class='gd-tag'>Nội dung gì</span>Nói đồ vật đó nói về cái gì, thuộc lĩnh vực nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>数学の教科書を忘れました。</span> (Tôi quên mang sách giáo khoa toán rồi.)</div><div class='gd-sec'><span class='gd-tag'>Từ đâu / ở đâu</span>Nói đồ vật hoặc người đến từ đâu, ở đâu.</div><div class='gd-ex-line'>・<span class='gd-jp'>台湾のお茶はおいしいです。</span> (Trà của Đài Loan rất ngon.)</div><div class='gd-h'>Danh từ phía sau có thể lược bỏ</div><div class='gd-sec'>Khi ai cũng biết đang nói về thứ gì, bạn có thể bỏ B đi và chỉ nói “A の”. <span class='gd-jp'>私の</span> nghĩa là “của tôi”.</div><div class='gd-ex-line'>・<span class='gd-jp'>「これは誰の傘ですか。」「私のです。」</span> (“Đây là ô của ai vậy?” “Của tôi ạ.”)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Tiếng Việt hay bỏ “của”, tiếng Nhật thì không bỏ được.</b> Tiếng Việt nói “mẹ tôi”, “bạn tôi”, “thầy giáo tiếng Nhật” đều không có “của”. Nhưng tiếng Nhật phải nói <span class='gd-jp'>私の母</span>, <span class='gd-jp'>私の友達</span>, <span class='gd-jp'>日本語の先生</span>. Nói “私母” hay “日本語先生” là sai.<br>・<b>Nhiều の nối liên tiếp vẫn cứ nối bình thường.</b> “Xe của bạn tôi” tiếng Việt chỉ có một chữ “của”, còn tiếng Nhật cần cả hai の: <span class='gd-jp'>私の友達の車</span>.<br>・<b>“Quyển sách này” là <span class='gd-jp'>この本</span>, không phải “これの本”.</b> Bản thân <span class='gd-jp'>この</span> đã có nghĩa là “này”, nên nối thẳng với danh từ, không cần thêm の.</div><div class='gd-h'>Phân biệt với những cấu trúc dễ lẫn</div><div class='gd-sec'>Tiếng Việt thường chỉ đặt từ bổ nghĩa ngay sau danh từ: “xe Nhật”, “xe mới”, “xe đẹp”, không cần thêm gì. Tiếng Nhật thì phải xem từ đứng trước thuộc loại nào:<br><b>Danh từ</b> (người, đồ vật, nơi chốn) thì thêm の: <span class='gd-jp'>日本の車</span> (xe Nhật)<br><b>Tính từ đuôi い</b> (như <span class='gd-jp'>新しい</span>, <span class='gd-jp'>おいしい</span>) thì nối thẳng, không thêm の: <span class='gd-jp'>新しい車</span> (xe mới), không phải “新しいの車”<br><b>Tính từ đuôi な</b> (như <span class='gd-jp'>きれい</span>, <span class='gd-jp'>静か</span>) thì thêm な: <span class='gd-jp'>きれいな車</span> (xe đẹp), không phải “きれいの車”</div><div class='gd-warn'>Mẹo nhỏ: nếu từ đứng trước là danh từ kiểu “ai, đồ vật gì, ở đâu” thì dùng の. Nếu nó là tính từ miêu tả “như thế nào” thì đừng dùng の.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「の」còn có một vai trò khác: đứng sau động từ để biến một hành động thành “việc đó”, ví dụ <span class='gd-jp'>本を読むのが好きです。</span> (Tôi thích đọc sách.) Phần này bạn sẽ học ở bài “の danh từ hình thức”, khác với nghĩa “của” ở đây.</div>","n5-18":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「か」giống như <b>“không?” / “à?”</b> trong tiếng Việt. Chỉ cần thêm か vào cuối câu là câu khẳng định biến thành câu hỏi: <span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生ですか</span></span>, “là sinh viên” thành “là sinh viên không?”.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Thể lịch sự rất đơn giản: cuối câu là <b>です</b> hoặc <b>ます</b>, bạn chỉ cần thêm か vào sau, phần phía trước giữ nguyên.<br><span class='gd-pair'><span class='gd-jp'>日本人です</span> → <span class='gd-jp'>日本人ですか</span></span><br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですか</span></span><br><span class='gd-pair'><span class='gd-jp'>静かです</span> → <span class='gd-jp'>静かですか</span></span><br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますか</span></span><br><span class='gd-pair'><span class='gd-jp'>食べました</span> → <span class='gd-jp'>食べましたか</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Hỏi đúng hay không</span>Câu hỏi mà người kia chỉ cần trả lời「はい」hoặc「いいえ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは日本の本ですか。</span> (Đây là sách của Nhật phải không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメン、おいしいですか。</span> (Tô ramen này có ngon không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、学校へ行きますか。</span> (Ngày mai bạn có đến trường không?)</div><div class='gd-sec'>Khi trả lời, với câu danh từ thường dùng <span class='gd-jp'>はい、そうです。</span> (Vâng, đúng vậy.) hoặc <span class='gd-jp'>いいえ、違います。</span> (Không, không phải.). Với động từ và tính từ thì lặp lại chính từ đó: <span class='gd-jp'>はい、行きます。</span> (Có, tôi sẽ đi.) / <span class='gd-jp'>いいえ、行きません。</span> (Không, tôi không đi.).</div><div class='gd-sec'><span class='gd-tag'>Đi với từ để hỏi</span>Trong câu có những từ như “cái gì, ở đâu, khi nào” thì vẫn phải thêm か.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅はどこですか。</span> (Xin lỗi, nhà ga ở đâu vậy ạ?)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、何を食べましたか。</span> (Hôm qua bạn đã ăn gì?)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Có từ để hỏi vẫn phải thêm か</b>: tiếng Việt hỏi “Đó là cái gì?” chứ không nói “Đó là cái gì không?”, nên nhiều bạn hay quên か. Nhưng thể lịch sự trong tiếng Nhật vẫn cần か, phải nói <span class='gd-jp'>何ですか</span>, không thể chỉ nói “何です”.<br>・<b>Lên giọng ở cuối câu</b>: か trong「ですか」phải lên giọng. Ví dụ <span class='gd-jp'>そうですか</span>: lên giọng nghĩa là “vậy à?”, còn xuống giọng thành “ồ, ra vậy”, cho thấy bạn đã hiểu, nghĩa hoàn toàn khác.<br>・<b>Nói với bạn bè thường không thêm か</b>: dùng thể không có です、ます và lên giọng cuối câu là thành câu hỏi: <span class='gd-jp'>明日、行く？</span> (Mai đi không?), <span class='gd-jp'>これ、おいしい？</span> (Cái này ngon không?). Thể thường mà thêm か trực tiếp (như「行くか」) nghe rất cộc, thô, người mới học chưa nên dùng.<br>・Với câu hỏi danh từ nói với bạn bè thì dùng <span class='gd-jp'>学生？</span>, đừng nói thành 「学生だか」, vì đó không phải câu hỏi.<br>・<b>Dấu câu</b>: trong sách giáo khoa và văn bản trang trọng, sau か thường đặt dấu 「。」 vì か đã cho biết đây là câu hỏi. Còn trong tin nhắn LINE hay truyện tranh thì hay thấy 「？」, bạn sẽ gặp cả hai cách.</div><div class='gd-h'>Phân biệt với những cấu trúc dễ lẫn</div><div class='gd-sec'><b>ますか</b>＝chỉ đơn thuần hỏi đối phương có làm hay không:<br><div class='gd-ex-line'>・<span class='gd-jp'>明日、パーティーに行きますか。</span> (Ngày mai bạn có đi dự tiệc không?)</div><b>ませんか</b>＝<b>rủ đối phương</b> cùng làm:<br><div class='gd-ex-line'>・<span class='gd-jp'>明日、一緒にパーティーに行きませんか。</span> (Ngày mai cùng đi dự tiệc nhé?)</div>Hai câu chỉ khác nhau chút xíu, nhưng câu đầu là hỏi thăm kế hoạch của người ta, còn câu sau là đang rủ rê.</div><div class='gd-warn'>Mẹo nhỏ: chỉ muốn biết đối phương có làm hay không thì dùng「ますか」; muốn rủ đối phương cùng làm thì dùng「ませんか」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Học thêm các từ để hỏi như「何、どこ、いつ、だれ」là bạn có thể hỏi đủ loại câu. Sau đó học thêm「〜ませんか」là có thể mở lời rủ người khác rồi.</div>","n5-19":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「に」đặt sau từ chỉ thời gian, nghĩa giống như「<b>lúc</b> 7 giờ」「<b>vào</b> tháng 3」trong tiếng Việt, dùng để \"đóng đinh\" sự việc vào một thời điểm cụ thể. Tiếng Việt hay bỏ \"lúc/vào\" và nói thẳng \"7 giờ tôi dậy\", nhưng tiếng Nhật thì hễ là <b>thời gian có con số</b> là nhất định phải thêm に: <span class='gd-jp'>7時に起きます。</span>(Tôi thức dậy lúc 7 giờ)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Chỉ cần thêm に ngay sau từ chỉ thời gian.<br><span class='gd-pair'><span class='gd-jp'>7時</span> → <span class='gd-jp'>7時に</span></span><span class='gd-pair'><span class='gd-jp'>3月</span> → <span class='gd-jp'>3月に</span></span><span class='gd-pair'><span class='gd-jp'>2025年</span> → <span class='gd-jp'>2025年に</span></span></div><div class='gd-h'>Khi nào thêm, khi nào không thêm</div><div class='gd-sec'>Đây mới là chỗ bạn thật sự cần nhớ. Từ chỉ thời gian chia làm ba loại:</div><div class='gd-sec'><span class='gd-tag'>Bắt buộc thêm</span>Thời gian có con số: mấy giờ, mấy phút, tháng mấy, năm nào, ngày mấy.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝6時に散歩します。</span>(6 giờ sáng tôi đi dạo)</div><div class='gd-ex-line'>・<span class='gd-jp'>3月に日本へ行きます。</span>(Tháng 3 tôi sẽ đi Nhật)</div><div class='gd-sec'>Những ngày đặc biệt, rõ ràng dù không có con số cũng phải thêm, ví dụ <span class='gd-jp'>誕生日</span>, <span class='gd-jp'>クリスマス</span>, <span class='gd-jp'>夏休み</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日にケーキを食べます。</span>(Vào ngày sinh nhật tôi ăn bánh kem)</div><div class='gd-sec'><span class='gd-tag'>Thêm hay không đều được</span>Thứ trong tuần. Thêm vào thì rõ ràng hơn, người mới học <b>cứ thêm vào là an toàn nhất</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>金曜日に歓迎会があります。</span>(Thứ Sáu có tiệc chào mừng)</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日に休みます。</span>(Chủ nhật tôi nghỉ)</div><div class='gd-sec'><span class='gd-tag'>Không được thêm</span>① Thời gian lấy \"bây giờ\" làm mốc: <span class='gd-jp'>今日</span>, <span class='gd-jp'>明日</span>, <span class='gd-jp'>昨日</span>, <span class='gd-jp'>今週</span>, <span class='gd-jp'>来年</span>, <span class='gd-jp'>今</span>.<br>Cách nhận biết: những từ này nói hôm nay hay tuần sau thì ngày được chỉ đến sẽ khác nhau, tức là chúng \"chạy theo\" thời điểm hiện tại, nên không thêm に.<br>② Thời gian mang nghĩa \"mỗi ~\": <span class='gd-jp'>毎日</span>, <span class='gd-jp'>毎朝</span>, <span class='gd-jp'>毎週</span>. Những từ này nói về việc lặp lại cố định, tần suất bao lâu một lần, không phải một thời điểm nhất định, nên cũng không thêm に.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、映画を見ます。</span>(Ngày mai tôi sẽ xem phim)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝コーヒーを飲みます。</span>(Sáng nào tôi cũng uống cà phê)</div><div class='gd-sec'>Hai loại thời gian đặt chung trong một câu cũng rất hay gặp:</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝7時に起きます。</span>(Mỗi sáng tôi thức dậy lúc 7 giờ)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日の3時に会いましょう。</span>(Ngày mai gặp nhau lúc 3 giờ nhé)</div><div class='gd-warn'>Khi một câu có cả hai loại thời gian, cứ áp dụng quy tắc cho từng loại: thời gian lấy hiện tại làm mốc (<span class='gd-jp'>明日</span>…) và thời gian \"mỗi ~\" (<span class='gd-jp'>毎朝</span>…) thì không thêm; thời gian có con số (<span class='gd-jp'>7時</span>, <span class='gd-jp'>3時</span>…) thì phải thêm.</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Bỏ sót に theo thói quen tiếng Việt: nói「7時起きます」là sai, phải nói <span class='gd-jp'>7時に起きます</span>.<br>・Ngược lại, thêm thừa: 「明日に行きます」「毎日に勉強します」đều sai, sau <span class='gd-jp'>明日</span>, <span class='gd-jp'>毎日</span> cứ nói tiếp luôn.<br>・Khi hỏi giờ, <span class='gd-jp'>何時</span> cần có に, còn <span class='gd-jp'>いつ</span> thì không: <span class='gd-jp'>何時に起きますか。</span>(Bạn dậy lúc mấy giờ?), <span class='gd-jp'>いつ日本へ行きますか。</span>(Khi nào bạn đi Nhật?)<br>・「時」và「時間」khác nhau: <span class='gd-jp'>2時に勉強します</span> là \"học lúc 2 giờ\"; <span class='gd-jp'>2時間勉強します</span> là \"học trong 2 tiếng\". Khoảng thời gian nói về <b>bao lâu</b> thì không thêm に.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng là \"7 giờ\", trợ từ đi sau khác thì nghĩa khác:<br><b>に</b>＝đúng vào thời điểm đó: <span class='gd-jp'>7時に起きます。</span>(Dậy lúc 7 giờ)<br><b>から</b>＝bắt đầu từ thời điểm đó và kéo dài tiếp: <span class='gd-jp'>7時から勉強します。</span>(Học từ 7 giờ)<br><b>まで</b>＝kéo dài cho đến thời điểm đó thì dừng: <span class='gd-jp'>7時まで寝ます。</span>(Ngủ đến 7 giờ)</div><div class='gd-warn'>Mẹo nhỏ: \"lúc mấy giờ\" dùng に, \"từ mấy giờ\" dùng から, \"đến mấy giờ\" dùng まで.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>に không chỉ đánh dấu thời gian mà còn đánh dấu nơi có vật gì đó (n5-33 vị trí tồn tại): <span class='gd-jp'>部屋に猫がいます。</span>(Trong phòng có con mèo). Cùng một に, bạn chỉ cần nhìn phía trước là thời gian hay địa điểm để phân biệt.</div>","n5-20":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「へ」nghĩa là <b>「hướng về ~」「đến ~」</b>. Đặt sau địa điểm để cho người nghe biết bạn đang di chuyển về đâu: <span class='gd-jp'>日本へ行きます</span> là \"đi hướng về Nhật Bản\", tức là \"đi Nhật\". Dù viết là へ, nhưng khi làm trợ từ thì <b>đọc là \"e\"</b>, không đọc là \"he\".</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Địa điểm＋へ＋động từ di chuyển (như <span class='gd-jp'>行きます</span>, <span class='gd-jp'>来ます</span>, <span class='gd-jp'>帰ります</span>).<br><span class='gd-pair'><span class='gd-jp'>学校</span> → <span class='gd-jp'>学校へ行きます</span></span>(đi đến trường)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、京都へ行きます。</span>(Ngày mai tôi đi Kyoto)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは去年日本へ来ました。</span>(Anh Tanaka năm ngoái đã đến Nhật)</div><div class='gd-ex-line'>・<span class='gd-jp'>6時にうちへ帰ります。</span>(6 giờ tôi về nhà)</div><div class='gd-sec'>Muốn hỏi người khác đi đâu, chỉ cần thay địa điểm bằng <span class='gd-jp'>どこ</span>:</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、どこへ行きますか。</span>(Cuối tuần bạn đi đâu?)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Cách đọc: へ làm trợ từ đọc là \"e\", giống trường hợp <span class='gd-jp'>は</span> làm trợ từ đọc là \"wa\". Nhưng <b>khi viết thì nhất định viết へ</b>, không được viết thành え.<br>・Phía sau phải là động từ \"di chuyển\". Tiếng Việt nói \"đến thư viện học bài\" rất xuôi, nhưng địa điểm diễn ra hành động \"học ở thư viện\" phải dùng <span class='gd-jp'>で</span>: <span class='gd-jp'>図書館で勉強します</span>, không thể nói <span class='gd-jp'>図書館へ勉強します</span>.<br>・Thời gian không dùng へ. Muốn nói \"ngày mai đi\" thì nói <span class='gd-jp'>明日、行きます</span>, không phải 明日へ.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><span class='gd-tag'>へ và に</span>Khi nói \"đi, đến, về\" một nơi nào đó, hai trợ từ này phần lớn có thể thay cho nhau, nghĩa như nhau.</div><div class='gd-ex-line'>・<span class='gd-jp'>東京へ行きます。</span>(Đi Tokyo)</div><div class='gd-ex-line'>・<span class='gd-jp'>東京に行きます。</span>(Đi Tokyo)</div><div class='gd-sec'>Nếu cứ muốn tách bạch: <b>へ</b> mang cảm giác \"hướng về phía đó\", còn <b>に</b> mang cảm giác \"đến đúng điểm đó\". Trong hội thoại hằng ngày に được dùng nhiều hơn. Nếu trọng tâm là \"đến nơi\", ví dụ <span class='gd-jp'>着きます</span> (đến), thì thường dùng に:</div><div class='gd-ex-line'>・<span class='gd-jp'>駅に着きました。</span>(Đã đến ga rồi)</div><div class='gd-sec'><span class='gd-tag'>へ và で</span>へ là \"đi về đâu\", で là \"làm việc gì ở đâu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館へ行きます。</span>(Đi đến thư viện)</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館で勉強します。</span>(Học ở thư viện)</div><div class='gd-warn'>Mẹo nhỏ: phía sau là động từ di chuyển như「行く、来る、帰る」thì dùng へ hoặc に đều được; \"làm việc gì ở đâu\" thì dùng で. Thời gian không dùng へ: mốc thời gian cụ thể như 7時, 月曜日 phải thêm に, còn các từ như 明日, 来週 thì không thêm trợ từ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Kết hợp với <span class='gd-jp'>から</span> (từ) và <span class='gd-jp'>まで</span> (đến), bạn có thể nói đầy đủ điểm xuất phát và điểm đến của việc di chuyển; học thêm「で (phương tiện)」là bạn nói được <span class='gd-jp'>電車で会社へ行きます</span> (đi tàu điện đến công ty).</div>","n5-14":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể phủ định lịch sự có hai cách nói: <span class='gd-jp'>食べません</span> và <span class='gd-jp'>食べないです</span>. Cả hai đều có nghĩa là \"không ăn\". Khác biệt hơi giống mặc vest và mặc sơ mi: <b>ません trang trọng hơn</b>, <b>ないです thoải mái hơn</b>. Cả hai đều lịch sự, nói với thầy cô hay nhân viên cửa hàng đều không bị thất lễ.</div><div class='gd-h'>Cách chia: xem động từ thuộc nhóm nào trước</div><div class='gd-sec'>Kiểu <span class='gd-jp'>ません</span> rất đơn giản, chỉ cần đổi ます thành ません: <span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みません</span></span><br>Kiểu <span class='gd-jp'>ないです</span> là lấy 「thể ない」 (dạng phủ định thân mật của động từ) rồi thêm <span class='gd-jp'>です</span> phía sau:</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối sang âm hàng 「あ」 cùng hàng, thêm ない, rồi thêm です.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → đổi む thành ま → <span class='gd-jp'>飲まないです</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かないです</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らないです</span></span><br>Nếu âm cuối là 「う」 thì đổi thành 「わ」: <span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わないです</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ 「る」 rồi thêm ないです.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないです</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ないです</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しないです</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないです</span>（こないです）</span></div><div class='gd-h'>Tính từ và danh từ cũng có hai kiểu</div><div class='gd-sec'><b>Tính từ đuôi い</b>: đổi 「い」 ở cuối thành 「く」, rồi thêm ないです hoặc ありません.<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒くないです</span></span>＝<span class='gd-jp'>寒くありません</span><br><b>Tính từ đuôi な và danh từ</b>: thêm trực tiếp じゃないです hoặc じゃありません.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かじゃないです</span></span>＝<span class='gd-jp'>静かじゃありません</span><br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生じゃないです</span></span>＝<span class='gd-jp'>学生じゃありません</span><br>Muốn trang trọng hơn nữa thì đổi じゃ thành では: <span class='gd-jp'>学生ではありません</span>.</div><div class='gd-sec'>Phủ định ở quá khứ (\"đã không ～\") cũng có hai kiểu: <span class='gd-jp'>食べませんでした</span>＝<span class='gd-jp'>食べなかったです</span>, <span class='gd-jp'>寒くありませんでした</span>＝<span class='gd-jp'>寒くなかったです</span>.</div><div class='gd-h'>Khi nào dùng kiểu nào</div><div class='gd-sec'><span class='gd-tag'>Hoàn cảnh trang trọng</span>Khi viết email, đi làm, phỏng vấn, nói với người lớn tuổi, dùng ません sẽ chắc ăn hơn.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は会社に行きません。</span>（Ngày mai tôi không đến công ty）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は学生ではありません。</span>（Tôi không phải là học sinh/sinh viên）</div><div class='gd-sec'><span class='gd-tag'>Hội thoại hằng ngày</span>Khi nói chuyện với nhân viên cửa hàng, hàng xóm, bạn học chưa thân lắm, bạn sẽ nghe ないです rất thường xuyên. Với tính từ, <span class='gd-jp'>くないです</span> và <span class='gd-jp'>じゃないです</span> thậm chí còn được dùng nhiều hơn ありません trong lúc nói chuyện.</div><div class='gd-ex-line'>・<span class='gd-jp'>肉はあまり食べないです。</span>（Tôi không ăn thịt mấy）</div><div class='gd-ex-line'>・<span class='gd-jp'>この店、高くないですよ。</span>（Quán này không đắt đâu nhé）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はそんなに寒くないですね。</span>（Hôm nay không lạnh đến vậy nhỉ）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Hai kiểu không được trộn lẫn: không có <span class='gd-jp'>食べないません</span>, cũng không có <span class='gd-jp'>食べませんです</span>.<br>・Phủ định của <span class='gd-jp'>ある</span> rất đặc biệt, đổi thẳng thành <span class='gd-jp'>ない</span>, không có kiểu あらない: <span class='gd-jp'>時間がありません</span>＝<span class='gd-jp'>時間がないです</span> (không có thời gian).<br>・<span class='gd-jp'>いい</span> phải đổi thành <span class='gd-jp'>よくないです</span>, không phải いくないです.<br>・<span class='gd-jp'>買う</span> là <span class='gd-jp'>買わない</span>, không phải 買あない.<br>・<span class='gd-jp'>来ない</span> đọc là <b>こない</b>, không phải きない.<br>・Không phải chỗ nào cũng thay thế được cho nhau: <span class='gd-jp'>すみません</span> là cách xin lỗi cố định, không nói thành すまないです; còn câu rủ ai đó <span class='gd-jp'>一緒に行きませんか</span> (Đi cùng nhau không?) thì dùng ません là tự nhiên và lịch sự nhất.</div><div class='gd-h'>Phân biệt với những dạng dễ lẫn</div><div class='gd-sec'>Nhiều bạn học ないです xong thì nói một hồi là quên mất <span class='gd-jp'>です</span>. Cùng là \"hôm nay tôi không đi\":<br>Với thầy cô: <span class='gd-jp'>今日は行きません。</span>／<span class='gd-jp'>今日は行かないです。</span> (cả hai đều được)<br>Với bạn bè: <span class='gd-jp'>今日は行かない。</span> (kiểu thân mật, nói với thầy cô thì quá suồng sã)</div><div class='gd-warn'>Mẹo nhận biết: cuối câu có <span class='gd-jp'>ます</span> (ません) hoặc <span class='gd-jp'>です</span> là dạng lịch sự, không có cái nào thì là dạng thân mật.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Nếu bạn muốn biết khi nào có thể bỏ です để nói thẳng <span class='gd-jp'>行かない</span>, hãy xem tiếp bài 「Thể lịch sự và thể thường」 và 「Thể từ điển・thể ない」.</div>","n5-16":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「も」 chính là <b>\"cũng\"</b>. Có điều vị trí khác với tiếng Việt: trong tiếng Việt, \"cũng\" đứng trước động từ (tôi <b>cũng</b> uống), còn 「も」 trong tiếng Nhật phải <b>dán ngay sau thứ được \"cũng\"</b> (<span class='gd-jp'>私も</span>＝tôi cũng).</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><span class='gd-tag'>は・が・を</span>Ba trợ từ này phải <b>bỏ đi và thay bằng も</b>.<br><span class='gd-pair'><span class='gd-jp'>私は</span> → <span class='gd-jp'>私も</span></span><span class='gd-pair'><span class='gd-jp'>猫が</span> → <span class='gd-jp'>猫も</span></span><span class='gd-pair'><span class='gd-jp'>コーヒーを</span> → <span class='gd-jp'>コーヒーも</span></span></div><div class='gd-sec'><span class='gd-tag'>に・で・へ・と</span>Những trợ từ này phải <b>giữ lại</b>, rồi thêm も ở phía sau.<br><span class='gd-pair'><span class='gd-jp'>大阪に</span> → <span class='gd-jp'>大阪にも</span></span><span class='gd-pair'><span class='gd-jp'>家で</span> → <span class='gd-jp'>家でも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>大阪にも行きました。</span>（Tôi cũng đã đến Osaka）</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Cũng</span>Trước đó đã nói một việc, giờ bổ sung thêm một việc giống như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：私は学生です。B：私も学生です。</span>（A: Tôi là học sinh. B: Tôi cũng là học sinh）</div><div class='gd-ex-line'>・<span class='gd-jp'>A：コーヒーが好きです。B：私も。</span>（A: Tôi thích cà phê. B: Tôi cũng vậy）</div><div class='gd-sec'><span class='gd-tag'>AもBも</span>Cả hai đều giống nhau, nghĩa là \"cả A lẫn B đều ～\". Nếu phía sau là phủ định thì là \"cả hai đều không\".</div><div class='gd-ex-line'>・<span class='gd-jp'>パンもケーキも好きです。</span>（Tôi thích cả bánh mì lẫn bánh ngọt）</div><div class='gd-ex-line'>・<span class='gd-jp'>肉も魚も食べません。</span>（Tôi không ăn cả thịt lẫn cá）</div><div class='gd-sec'><span class='gd-tag'>Từ nghi vấn＋も＋phủ định</span>Nghĩa là \"không ... gì cả\", \"không ai cả\", \"không ở đâu cả\". Phía sau nhất định phải là phủ định.</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は何も食べませんでした。</span>（Sáng nay tôi không ăn gì cả）</div><div class='gd-ex-line'>・<span class='gd-jp'>教室には誰もいません。</span>（Trong lớp học không có ai cả）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末はどこにも行きませんでした。</span>（Cuối tuần tôi không đi đâu cả）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Không có cách nói <span class='gd-jp'>はも</span>, <span class='gd-jp'>がも</span>, <span class='gd-jp'>をも</span>. は・が・を phải được thay thẳng bằng も.<br>・も dán vào sau từ nào thì \"cũng\" là nói về từ đó, nghĩa sẽ khác nhau nhiều:<br><span class='gd-jp'>私もコーヒーを飲みます。</span>（Người khác uống cà phê, <b>tôi cũng</b> uống）<br><span class='gd-jp'>私はコーヒーも飲みます。</span>（Tôi uống trà, <b>cà phê cũng</b> uống）<br>Tiếng Việt thường chỉ nói gọn \"Tôi cũng uống cà phê\" cho cả hai trường hợp, nhưng tiếng Nhật phải nghĩ rõ \"cũng\" là về người hay về cà phê.<br>・<span class='gd-jp'>何も</span>, <span class='gd-jp'>誰も</span> phải đi với phủ định. Muốn nói \"cái gì cũng thích\" thì không được nói 何も好きです, mà phải dùng cách khác (như <span class='gd-jp'>何でも好きです</span>, sẽ học sau).<br>・\"Không đi đâu cả\" phải nói <span class='gd-jp'>どこにも</span>, đừng bỏ sót に.</div><div class='gd-h'>Phân biệt với những dạng dễ lẫn</div><div class='gd-sec'><b>AとB</b>＝chỉ đơn thuần liệt kê hai thứ: <span class='gd-jp'>パンとケーキが好きです。</span> (Tôi thích bánh mì và bánh ngọt)<br><b>AもBも</b>＝nhấn mạnh \"cả hai đều\": <span class='gd-jp'>パンもケーキも好きです。</span> (Bánh mì cũng thích, bánh ngọt cũng thích, thích cả hai)<br>Cách đặt cũng khác nhau: と chỉ đặt một lần ở giữa, còn も thì <b>phải đặt sau từng thứ</b>.</div><div class='gd-warn'>Mẹo nhận biết: chỉ liệt kê thì dùng と, muốn nhấn mạnh \"cả hai đều ～\" thì dùng 〜も〜も.</div>","n5-27":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「と」này chính là <b>「và」「với」</b> trong tiếng Việt, dùng để liệt kê từng thứ một. Nó còn mang thêm một ý: <b>những thứ mình liệt kê là tất cả, không còn gì khác</b>. Ví dụ bạn nói với bạn bè 「Mình mua bánh mì và sữa」 thì nghĩa là chỉ mua đúng hai thứ đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>パンと牛乳を買いました。</span>（Mình đã mua bánh mì và sữa）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋と＋danh từ, <b>hai bên đều phải là danh từ</b>. Liệt kê xong thì ở cuối mới gắn trợ từ mà câu cần (を、が、は…).<br><span class='gd-pair'><span class='gd-jp'>鍵</span>＋<span class='gd-jp'>財布</span> → <span class='gd-jp'>鍵と財布を持ってきました</span></span>（Mình đã mang chìa khóa và ví đến）<br>Từ ba thứ trở lên thì đặt と giữa mỗi thứ:</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日と水曜日と金曜日に授業があります。</span>（Thứ Hai, thứ Tư và thứ Sáu có tiết học）</div><div class='gd-ex-line'>・<span class='gd-jp'>父と母は台北に住んでいます。</span>（Bố mẹ mình sống ở Đài Bắc）</div><div class='gd-sec'>Khi gọi món cũng dùng rất nhiều:</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒーとケーキをお願いします。</span>（Cho mình cà phê và bánh ngọt nhé）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Trợ từ chỉ đặt sau danh từ cuối cùng</b>. Phải nói <span class='gd-jp'>鍵と財布を持ってきました</span>, đừng nói thành 「鍵を財布を持ってきました」 hay 「鍵をと財布を持ってきました」.<br>・と <b>chỉ nối danh từ</b>. Từ “và” trong tiếng Việt dùng rất rộng, “rẻ và ngon”, “ăn cơm và xem TV” đều nói được. Nhưng tiếng Nhật không dùng と để nối tính từ hay động từ, phải dùng thể て mà bạn sẽ học sau.<br>・と mang nghĩa “chỉ có những thứ này”. Nếu còn thứ khác chưa kể hết thì phải đổi sang や.</div><div class='gd-h'>Phân biệt với những cái nhìn giống nhau</div><div class='gd-sec'><span class='gd-tag'>と vs や</span>Cùng nói về đồ mang trong túi:<br><span class='gd-jp'>鍵と財布を持ってきました。</span>（Mang chìa khóa và ví: chỉ có hai thứ này）<br><span class='gd-jp'>鍵や財布を持ってきました。</span>（Mang chìa khóa, ví… chẳng hạn: còn có thứ khác）</div><div class='gd-sec'><span class='gd-tag'>“và” vs “cùng”</span>と còn có một cách dùng khác, là “làm gì đó cùng với ai”.<br><b>と liệt kê</b>: gộp A và B thành một nhóm, phía sau còn gắn は、が、を… và cả nhóm là một thành phần của câu.<br><span class='gd-jp'>友達と私は映画を見ました。</span>（Bạn và mình đã xem phim: 「友達と私」 là một nhóm, phía sau gắn は）<br><b>と “cùng”</b>: 「người＋と」 cho biết bạn làm hành động phía sau cùng với ai. Dù phía sau có danh từ, danh từ đó là một thành phần khác, không bị gộp với người đứng trước と.<br><span class='gd-jp'>友達と映画を見ました。</span>（Mình đã xem phim với bạn: 「友達と」 cho biết xem cùng ai, 「映画を」 là thứ được xem, không phải “bạn và phim”）<br>Khi muốn nhấn mạnh “cùng nhau”, người ta hay nói <span class='gd-jp'>友達と一緒に映画を見ました</span>.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: thử đặt riêng danh từ đứng trước と vào câu. <span class='gd-jp'>鍵を持ってきました</span> và <span class='gd-jp'>財布を持ってきました</span> đều nói được, vậy là “A và B”. Còn 「友達と映画を見ました」 đổi thành 「友達を見ました」 thì nghĩa sai hẳn, nên と đó là “cùng với ai”.</div>","n5-28":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「や」giống như <b>“nào là A, nào là B (v.v.)”</b> hay <b>“như A, B chẳng hạn”</b> trong tiếng Việt. Có rất nhiều thứ nhưng bạn chỉ chọn vài thứ tiêu biểu để nói, đồng thời cho người nghe biết <b>còn có cái khác, chưa liệt kê hết</b>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Danh từ＋<b>や</b>＋danh từ, cuối câu thường thêm 「<b>など</b>」 (vân vân). Trợ từ cần đi sau (を、が、に…) vẫn gắn ở cuối cùng.<br><span class='gd-pair'><span class='gd-jp'>牛乳</span>＋<span class='gd-jp'>卵</span> → <span class='gd-jp'>牛乳や卵</span></span><br><span class='gd-pair'><span class='gd-jp'>牛乳や卵</span> → <span class='gd-jp'>牛乳や卵など</span></span>（thêm など thì cảm giác “còn nữa” rõ hơn）</div><div class='gd-ex-line'>・<span class='gd-jp'>冷蔵庫に牛乳や卵があります。</span>（Trong tủ lạnh có sữa, trứng… chẳng hạn）</div><div class='gd-ex-line'>・<span class='gd-jp'>週末は掃除や洗濯をします。</span>（Cuối tuần mình dọn dẹp, giặt đồ… chẳng hạn）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本で寿司やラーメンなどを食べました。</span>（Ở Nhật mình đã ăn sushi, ramen v.v.）</div><div class='gd-sec'>Muốn nêu ba thứ cũng được, đặt や giữa mỗi thứ:</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上にペンやノートや辞書などがあります。</span>（Trên bàn có bút, vở, từ điển v.v.）</div><div class='gd-h'>Phân biệt với những cái nhìn giống nhau</div><div class='gd-sec'>「と」cũng nối danh từ, nhưng nghĩa khác nhiều. Cùng nói về đồ trong túi:<br><b>と</b>＝<b>chỉ có chừng đó</b>: <span class='gd-jp'>かばんに財布と鍵があります。</span>（Trong túi có ví và chìa khóa, chỉ hai thứ này）<br><b>や</b>＝<b>nêu ví dụ, còn có thứ khác</b>: <span class='gd-jp'>かばんに財布や鍵があります。</span>（Trong túi có ví, chìa khóa… chẳng hạn, còn có đồ khác nữa）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: nói được “chỉ có chừng này” thì dùng と. Chỉ nêu vài ví dụ và trong đầu còn ý “…v.v.” thì dùng や.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・や <b>chỉ nối danh từ</b>. Muốn nêu ví dụ cho hành động thì không nói được 「食べるや飲む」, phải dùng 「〜たり〜たりします」: <span class='gd-jp'>食べたり飲んだりします</span> (lúc ăn lúc uống chẳng hạn).<br>・Sau danh từ cuối cùng <b>đừng đặt thêm や</b>. Không kết thúc câu bằng 「ペンやノートや」, muốn diễn tả “v.v.” thì thêm など: <span class='gd-jp'>ペンやノートなど</span>.<br>・Từ “với” trong tiếng Việt vừa có nghĩa “và” vừa có nghĩa “cùng ai”, nhưng や thì không có nghĩa “cùng ai”. “Mình đi với bạn” là <span class='gd-jp'>友達と行きます</span>, không thể nói 友達や行きます.<br>・Không cần có thật nhiều thứ mới dùng や, chỉ nêu hai thứ cũng hoàn toàn được, quan trọng là cảm giác “chưa liệt kê hết”.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cách nêu ví dụ cho hành động là 「〜たり〜たりします」: <span class='gd-jp'>休みの日は映画を見たり、買い物をしたりします。</span>（Ngày nghỉ mình lúc xem phim, lúc đi mua sắm chẳng hạn）</div>","n5-23":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「を」là một chiếc nhãn nhỏ dán sau danh từ, nghĩa là <b>“thứ này chính là đối tượng mà hành động tác động đến”</b>. Tiếng Việt nói “ăn bánh mì” thì nhìn thứ tự là biết ăn cái gì. Còn trong tiếng Nhật, động từ đứng cuối câu, nên cần「を」để đánh dấu <b>ăn cái gì, xem cái gì</b>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Danh từ＋を＋động từ. Trật tự tiếng Nhật là “nói thứ đó trước, hành động để cuối”:<br><span class='gd-pair'><span class='gd-jp'>パン</span> → <span class='gd-jp'>パンを食べます</span></span>（ăn bánh mì）</div><div class='gd-ex-line'>・<span class='gd-jp'>水を飲みます。</span>（uống nước）</div><div class='gd-ex-line'>・<span class='gd-jp'>映画を見ます。</span>（xem phim）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日日本語を勉強します。</span>（Mình học tiếng Nhật mỗi ngày）</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đối tượng của hành động</span>Đây là cách dùng chính và phổ biến nhất: ăn gì, uống gì, mua gì, làm gì. Người mới học hãy luyện thật quen cách này trước.</div><div class='gd-ex-line'>・<span class='gd-jp'>コンビニで傘を買いました。</span>（Mình đã mua cái ô ở cửa hàng tiện lợi）</div><div class='gd-sec'><span class='gd-tag'>Nơi đi qua</span>Đi cùng các động từ di chuyển như “đi, đi dạo, qua (cầu, đường)”, biểu thị <b>đi ngang qua, băng qua nơi đó</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>公園を散歩します。</span>（đi dạo trong công viên）</div><div class='gd-ex-line'>・<span class='gd-jp'>橋を渡ります。</span>（qua cầu）</div><div class='gd-sec'><span class='gd-tag'>Nơi rời đi</span>Đi cùng các động từ như “ra, xuống (xe)”, biểu thị <b>rời khỏi nơi đó</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>8時に家を出ます。</span>（8 giờ ra khỏi nhà）</div><div class='gd-ex-line'>・<span class='gd-jp'>次の駅で電車を降ります。</span>（xuống tàu điện ở ga tiếp theo）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「を」đọc là <b>o</b>, giống「お」, đừng đọc thành wo. Có điều khi gõ trên máy tính, điện thoại thì phải gõ <b>wo</b> mới ra được.<br>・Dù đọc giống nhau, khi viết vẫn phải viết「を」, không được viết thành「お」.<br>・“Thích, hiểu, muốn” không dùng を: cách nói chuẩn trong sách giáo khoa là <span class='gd-jp'>猫が好きです</span>、<span class='gd-jp'>英語がわかります</span>, đừng nói thành 猫を好きです.<br>・Tiếng Việt nói “gặp bạn”, “đi tàu điện”, không có từ nào đứng giữa, nên dễ nghĩ là dùng を. Nhưng tiếng Nhật phải dùng に: <span class='gd-jp'>友達に会います</span>、<span class='gd-jp'>電車に乗ります</span>. Còn “xuống tàu” là <span class='gd-jp'>電車を降ります</span>. Lên tàu dùng に, xuống tàu dùng を, nhớ tách riêng ra nhé.<br>・<b>Một động từ không mang hai を</b>: <span class='gd-jp'>日本語を勉強をします</span> nghe không tự nhiên (勉強します chỉ có một を), hãy nói <span class='gd-jp'>日本語を勉強します</span> hoặc <span class='gd-jp'>日本語の勉強をします</span>. Còn mỗi động từ khác nhau mang một を thì không sao, ví dụ <span class='gd-jp'>本を読んで、ご飯を食べます。</span>（đọc sách, sau đó ăn cơm）<br>・Khi nói chuyện với bạn bè, người ta hay lược bỏ を: <span class='gd-jp'>ご飯、食べた？</span>（ăn cơm chưa?）. Đó là văn nói, khi tự viết câu thì bạn vẫn nên đặt を vào cho đủ.</div><div class='gd-h'>Phân biệt với các trợ từ trông giống nhau</div><div class='gd-sec'><b>を vs が</b>: cùng nói về tiếng Nhật, hành động dùng を, cảm xúc và khả năng dùng が.<br><span class='gd-jp'>日本語を勉強します。</span>（học tiếng Nhật: hành động）<br><span class='gd-jp'>日本語が好きです。</span>（thích tiếng Nhật: cảm xúc）<br><span class='gd-jp'>日本語がわかります。</span>（hiểu tiếng Nhật: khả năng）</div><div class='gd-sec'><b>を vs で</b>: cùng ở chỗ cây cầu, “qua cầu” dùng を, còn “làm việc khác trên cầu” dùng で.<br><span class='gd-jp'>橋を渡ります。</span>（qua cầu: đi từ đầu này sang đầu kia）<br><span class='gd-jp'>橋で写真を撮ります。</span>（chụp ảnh trên cầu: cây cầu chỉ là địa điểm làm việc, thứ được chụp là「写真」mới dùng を）</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: tự hỏi “hành động có tác động trực tiếp lên thứ này không?”. Có thì dùng を. “Thích, hiểu, muốn” dùng が. Chỉ nói “làm việc ở đâu” thì dùng で.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Có những động từ đi thành cặp, một cái dùng を, một cái dùng が: <span class='gd-jp'>ドアを開けます</span>（tôi mở cửa）、<span class='gd-jp'>ドアが開きます</span>（cửa mở ra）. Đây chính là “tự động từ・tha động từ”. Học xong を rồi học tiếp phần này sẽ rất thuận.</div>","n5-24":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「で」chính là <b>“ở (đâu) làm (gì)”</b> trong tiếng Việt. Hãy tưởng tượng địa điểm là một sân khấu,「で」cho người nghe biết: hành động này diễn ra trên sân khấu đó.<br><span class='gd-jp'>カフェで仕事をします。</span>（làm việc ở quán cà phê）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Thêm thẳng「で」sau địa điểm, rồi nối với hành động bạn làm.<br><span class='gd-pair'><span class='gd-jp'>図書館</span> → <span class='gd-jp'>図書館で勉強します</span></span>（học bài ở thư viện）<br><span class='gd-pair'><span class='gd-jp'>家</span> → <span class='gd-jp'>家で晩ご飯を食べます</span></span>（ăn tối ở nhà）<br>Địa điểm lớn hay nhỏ đều được: quốc gia, thành phố, cửa hàng, căn phòng, thậm chí là “chỗ này”.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Làm việc gì đó ở một nơi</span>Ăn, uống, mua, xem, học, làm việc, chơi, đợi người... Chỉ cần là hành động “làm”, thì sau địa điểm dùng で.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で友達を待ちます。</span>（đợi bạn ở nhà ga）</div><div class='gd-ex-line'>・<span class='gd-jp'>デパートで靴を買いました。</span>（đã mua giày ở trung tâm thương mại）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ってもいいですか。</span>（Tôi chụp ảnh ở đây được không?）</div><div class='gd-sec'><span class='gd-tag'>Hỏi làm ở đâu</span>Dùng「どこで」để hỏi.</div><div class='gd-ex-line'>・<span class='gd-jp'>そのかばん、どこで買いましたか。</span>（Cái túi đó bạn mua ở đâu vậy?）</div><div class='gd-ex-line'>・<span class='gd-jp'>どこで昼ご飯を食べますか。</span>（Bạn sẽ ăn trưa ở đâu?）</div><div class='gd-h'>Phân biệt với các trợ từ trông giống nhau</div><div class='gd-sec'><b>「で」và「に」: cùng một địa điểm, phải nhìn động từ phía sau</b><br>Tiếng Việt đều nói “ở thư viện”, nhưng tiếng Nhật phải xem bạn đang “ở lại đó” hay “làm việc ở đó”.<br><span class='gd-jp'>図書館にいます。</span>（Tôi ở thư viện: người đang ở đó, dùng に）<br><span class='gd-jp'>図書館で勉強します。</span>（Tôi học ở thư viện: làm việc ở đó, dùng で）<br>Nếu phía sau là những từ chỉ “sự tồn tại” như <b>いる、ある</b>（có, ở）thì dùng に. Nếu phía sau là <b>một hành động nào đó</b> thì dùng で.</div><div class='gd-sec'><b>「で」và「へ」: đang đi đến đó, hay đã ở đó rồi</b><br><span class='gd-jp'>図書館へ行きます。</span>（đi đến thư viện: di chuyển về phía đó, dùng へ）<br><span class='gd-jp'>図書館で本を読みます。</span>（đọc sách ở thư viện: đến nơi rồi làm việc, dùng で）</div><div class='gd-sec'><b>Một「で」khác: phương tiện, dụng cụ</b><br>「で」còn có công việc khác, phía trước là đồ vật chứ không phải địa điểm.<br><span class='gd-jp'>バスで行きます。</span>（đi bằng xe buýt: phương tiện）<br><span class='gd-jp'>公園で遊びます。</span>（chơi ở công viên: địa điểm）<br>Chỉ cần nhìn từ phía trước là “nơi chốn” hay “dụng cụ” là phân biệt được.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: <b>người hoặc vật “ở” đó → に; “đi” đến đó → へ; “làm” việc ở đó → で.</b></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Chữ “ở” trong tiếng Việt không thể lúc nào cũng dịch thành で. “Tôi ở nhà” là <span class='gd-jp'>家にいます</span>, không phải 家でいます.<br>・“Sống ở Tokyo” phải dùng に: <span class='gd-jp'>東京に住んでいます</span>, không phải 東京で住んでいます. “Sống” là ở lại nơi đó chứ không phải làm một việc ở đó. Đây là lỗi người Việt rất hay mắc, vì “ở” trong tiếng Việt dùng cho cả hai trường hợp.<br>・“Làm việc” dùng で thì không sao: <span class='gd-jp'>銀行で働いています</span>（làm việc ở ngân hàng）. Đừng vì 住む dùng に mà đổi luôn 働く sang に.<br>・Với các động từ “di chuyển” như 行く、来る、帰る, điểm đến không dùng で: phải nói <span class='gd-jp'>日本へ行きます</span>, không được nói 日本で行きます.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Đặt「で」và「を」cạnh nhau là bạn có thể nói được một câu hoàn chỉnh: <b>địa điểm＋で＋đồ vật＋を＋hành động</b>.<br><span class='gd-jp'>コンビニでお茶を買いました。</span>（đã mua trà ở cửa hàng tiện lợi）<br>Sau đó hãy xem tiếp「に」（vị trí tồn tại）, so sánh hai trợ từ này với nhau thì bạn sẽ không còn nhầm giữa に và で nữa.</div>","n5-32":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt nói 「Tôi thích chó」「Tôi hiểu tiếng Hàn」, chó và tiếng Hàn là thứ được thích, được hiểu, nên bạn dễ nghĩ ngay đến <span class='gd-jp'>を</span>. Nhưng trong tiếng Nhật, trước các từ <b>thích, ghét, giỏi, không giỏi, hiểu, biết (làm được), muốn có</b> thì phải dùng <b>が</b>. Cứ nhớ đây là cách kết hợp cố định là đúng.</div><div class='gd-h'>Những từ nào đi với が</div><div class='gd-sec'><span class='gd-tag'>Thích・Ghét</span><span class='gd-jp'>好き</span>（thích）、<span class='gd-jp'>嫌い</span>（ghét）</div><div class='gd-ex-line'>・<span class='gd-jp'>チョコレートが好きです。</span>（Tôi thích sô-cô-la）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は野菜が嫌いです。</span>（Tôi ghét rau）</div><div class='gd-sec'><span class='gd-tag'>Giỏi・Kém</span><span class='gd-jp'>上手</span>（giỏi, khéo）、<span class='gd-jp'>下手</span>（kém, không giỏi）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは歌が上手です。</span>（Anh Tanaka hát giỏi）</div><div class='gd-sec'><span class='gd-tag'>Hiểu・Biết làm</span><span class='gd-jp'>わかります</span>（hiểu）、<span class='gd-jp'>できます</span>（biết, làm được）</div><div class='gd-ex-line'>・<span class='gd-jp'>韓国語がわかります。</span>（Tôi hiểu tiếng Hàn）</div><div class='gd-ex-line'>・<span class='gd-jp'>テニスができます。</span>（Tôi biết chơi tennis）</div><div class='gd-sec'><span class='gd-tag'>Muốn có</span><span class='gd-jp'>ほしい</span>（muốn có）</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいかばんがほしいです。</span>（Tôi muốn có một chiếc cặp mới）</div><div class='gd-h'>Cách ghép câu</div><div class='gd-sec'>Sự vật (danh từ) ＋ が ＋ các từ ở trên.<br>Muốn nói «ai» thích, bạn đặt「người ＋ は」lên đầu câu: <span class='gd-jp'>私は犬が好きです。</span>（Tôi thích chó）<br>Trong câu này, <span class='gd-jp'>は</span> nghĩa là «chủ đề đang nói là tôi», còn <span class='gd-jp'>が</span> nghĩa là «thứ tôi thích là chó». Mỗi trợ từ lo một việc riêng.<br>Muốn hỏi người khác thích gì, chỉ cần thay sự vật bằng <span class='gd-jp'>何</span>: <span class='gd-jp'>何が好きですか。</span>（Bạn thích gì?）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Đừng dựa vào trực giác tiếng Việt mà dùng を: phải nói <span class='gd-jp'>韓国語がわかります</span>, không phải 韓国語をわかります. “Thích” cũng vậy, cứ nhớ <span class='gd-jp'>犬が好きです</span> là đúng.<br>・<span class='gd-jp'>好き</span>、<span class='gd-jp'>嫌い</span>、<span class='gd-jp'>上手</span>、<span class='gd-jp'>下手</span> không phải động từ, phía sau đi với <span class='gd-jp'>です</span>, không thêm ます.<br>・Khi nói «không thích», người Nhật rất hay đổi が thành は: <span class='gd-jp'>魚は好きじゃありません。</span>（Còn cá thì tôi không thích）. Câu này mang cảm giác «những thứ khác thì được, riêng cái này thì không», nghe rất tự nhiên.<br>・<span class='gd-jp'>上手</span> dùng để khen người khác. Tự nói «tôi giỏi ～» nghe như đang khoe, nên khi nói về mình người Nhật thường không dùng như vậy.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>Dễ nhầm nhất là với <b>を</b> (tân ngữ). Hãy xem cùng một thứ nhưng đặt trước các từ khác nhau:<br><span class='gd-jp'>日本語を勉強します。</span>（Tôi học tiếng Nhật）: «học» là hành động bạn làm, dùng を.<br><span class='gd-jp'>日本語がわかります。</span>（Tôi hiểu tiếng Nhật）: «hiểu» là năng lực của bản thân bạn, dùng が.<br><span class='gd-jp'>料理を作ります。</span>（Tôi nấu ăn）: hành động, dùng を.<br><span class='gd-jp'>料理が上手です。</span>（Nấu ăn giỏi）: tài năng, dùng が.</div><div class='gd-warn'>Mẹo phân biệt: nếu là hành động «đi làm» (ăn, đọc, làm, mua) thì dùng を; nếu là cảm giác trong lòng hoặc khả năng của bản thân (thích, ghét, giỏi, hiểu, biết làm, muốn có) thì dùng が.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Về cách dùng của <span class='gd-jp'>ほしい</span>, bạn có thể xem tiếp「<span class='gd-jp'>〜が欲しいです・〜たいです</span>」để học cách nói «muốn có ～, muốn làm ～».</div>","n5-33":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Chữ「に」này giống như <b>「ở / trong」</b> của tiếng Việt, dùng để cho đối phương biết người hay vật <b>ở đâu</b>. Tiếng Việt nói 「Trong tủ lạnh có sữa」, tiếng Nhật thì thêm に sau 「trong tủ lạnh」, rồi kết câu bằng あります hoặc います.</div><div class='gd-h'>Cách ghép câu</div><div class='gd-sec'>Mẫu câu: <b>Địa điểm＋に＋người／vật＋が＋あります／います</b></div><div class='gd-ex-line'>・<span class='gd-jp'>冷蔵庫に牛乳があります。</span>（Trong tủ lạnh có sữa）</div><div class='gd-ex-line'>・<span class='gd-jp'>教室に先生がいます。</span>（Trong lớp có thầy giáo）</div><div class='gd-sec'><b>Dùng あります hay います?</b> Hãy xem thứ đó có tự di chuyển được không: người và động vật dùng <span class='gd-jp'>います</span>; đồ vật và thực vật dùng <span class='gd-jp'>あります</span>.</div><div class='gd-h'>Cách nói vị trí</div><div class='gd-sec'>Tiếng Việt nói «trên bàn», «trong hộp», «trước nhà ga», còn tiếng Nhật quen dùng「の」để nối vị trí vào, phía sau mới thêm に:<br><span class='gd-jp'>机の上に</span>（trên bàn）、<span class='gd-jp'>箱の中に</span>（trong hộp）、<span class='gd-jp'>駅の前に</span>（trước nhà ga）、<span class='gd-jp'>机の下に</span>（dưới bàn）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の前にコンビニがあります。</span>（Trước nhà ga có cửa hàng tiện lợi）</div><div class='gd-h'>Hai dạng câu hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Ở đó có gì</span>Địa điểm đặt trước, thứ muốn nói đến dùng が.</div><div class='gd-ex-line'>・<span class='gd-jp'>公園に子供がいます。</span>（Trong công viên có trẻ em）</div><div class='gd-sec'><span class='gd-tag'>Nó ở đâu</span>Muốn nói «một thứ nào đó ở đâu», đặt thứ đó lên trước với は, に vẫn đi theo địa điểm.</div><div class='gd-ex-line'>・<span class='gd-jp'>猫は机の下にいます。</span>（Con mèo ở dưới bàn）</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこにありますか。</span>（Nhà vệ sinh ở đâu?）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・あります／います ở đây chỉ việc người hay vật «tồn tại» ở đó. Nếu あります nói về hoạt động, sự kiện «được tổ chức» (ví dụ: <span class='gd-jp'>パーティーがあります</span>) thì địa điểm phải dùng で: <span class='gd-jp'>明日、学校で試験があります。</span>（Ngày mai trường có kỳ thi）<br>・Tiếng Việt đều dùng «ở», nhưng «chơi ở công viên» là một hành động, phải dùng で: <span class='gd-jp'>公園で遊びます</span>, không phải 公園に遊びます.<br>・Người và động vật không dùng あります: phải nói <span class='gd-jp'>先生がいます</span>, không phải 先生があります.<br>・Địa điểm của «sống ở đâu» cũng dùng に: <span class='gd-jp'>姉は大阪に住んでいます。</span>（Chị tôi sống ở Osaka）</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>Dễ nhầm nhất là <b>で (nơi diễn ra hành động)</b>. Cùng là công viên, hãy xem câu đang nói về điều gì:<br><span class='gd-jp'>公園に子供がいます。</span>（Trong công viên có trẻ em: chỉ nói trẻ em đang ở đó）<br><span class='gd-jp'>公園で子供が遊んでいます。</span>（Trẻ em đang chơi ở công viên: làm một hành động ở đó）<br><span class='gd-jp'>公園でお祭りがあります。</span>（Công viên có lễ hội: sự kiện được tổ chức ở đó）</div><div class='gd-warn'>Mẹo phân biệt: nhìn vào cuối câu trước. Nếu あります／います diễn tả người hay vật «ở đó» (kể cả 住んでいます) thì dùng に; còn hành động như ăn, chơi, mua, làm việc, hoặc あります chỉ sự kiện «được tổ chức» (ví dụ: <span class='gd-jp'>ホテルでパーティーがあります</span>) thì dùng で.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bài「Cách diễn đạt sự tồn tại」sẽ dạy cách nói «không có gì cả», «không có ai cả»: <span class='gd-jp'>部屋に誰もいません。</span>（Trong phòng không có ai cả）</div>","n5-25":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「から」chính là <b>「từ」</b> trong tiếng Việt. Từ mấy giờ, từ đâu, từ ai, đều dùng nó. 「から」hay đi cùng 「まで」(đến), <span class='gd-jp'>AからBまで</span> nghĩa là \"từ A đến B\".</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Rất đơn giản: <b>thêm から ngay sau danh từ</b>, không cần biến đổi gì.<br><span class='gd-pair'><span class='gd-jp'>9時</span> → <span class='gd-jp'>9時から</span></span>（từ 9 giờ）<span class='gd-pair'><span class='gd-jp'>駅</span> → <span class='gd-jp'>駅から</span></span>（từ nhà ga）<span class='gd-pair'><span class='gd-jp'>友達</span> → <span class='gd-jp'>友達から</span></span>（từ bạn bè）</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Mốc thời gian bắt đầu</span>Bắt đầu từ một thời điểm nào đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は9時からです。</span>（Công việc bắt đầu từ 9 giờ）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日から夏休みです。</span>（Từ ngày mai là nghỉ hè）</div><div class='gd-sec'><span class='gd-tag'>Điểm xuất phát</span>Xuất phát từ một nơi nào đó, đến từ đâu.</div><div class='gd-ex-line'>・<span class='gd-jp'>どこから来ましたか。</span>（Bạn đến từ đâu vậy?）</div><div class='gd-ex-line'>・<span class='gd-jp'>台湾から来ました。</span>（Mình đến từ Đài Loan）</div><div class='gd-sec'><span class='gd-tag'>Từ ai</span>Đồ vật, tin tức do ai đưa cho.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達から電話がありました。</span>（Bạn bè đã gọi điện đến）</div><div class='gd-h'>Dạng nghe nhiều nhất: AからBまで</div><div class='gd-sec'>Khi nói về một khoảng, 「から」và 「まで」thường đi chung, dùng được cho cả thời gian lẫn địa điểm.</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日から金曜日まで働きます。</span>（Làm việc từ thứ Hai đến thứ Sáu）</div><div class='gd-ex-line'>・<span class='gd-jp'>家から駅まで歩きます。</span>（Đi bộ từ nhà đến nhà ga）</div><div class='gd-ex-line'>・<span class='gd-jp'>何時から何時までですか。</span>（Từ mấy giờ đến mấy giờ vậy?）</div><div class='gd-sec'>Câu cuối rất tiện khi hỏi giờ mở cửa của cửa hàng hay giờ diễn ra sự kiện, sang Nhật chắc chắn sẽ dùng đến. Khi không cần nói cả khoảng, dùng 「から」một mình cũng hoàn toàn ổn.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Vị trí ngược với tiếng Việt</b>: tiếng Việt đặt \"từ\" ở phía trước, còn tiếng Nhật đặt 「から」<b>sau</b> danh từ. \"Từ nhà ga\" là <span class='gd-jp'>駅から</span>, không phải から駅.<br>・Tiếng Việt hay nói \"từ ngày mai <b>bắt đầu</b> nghỉ\", còn tiếng Nhật chỉ cần <span class='gd-jp'>明日から夏休みです</span> là đủ. Bản thân 「から」đã mang nghĩa \"bắt đầu từ ～\", nên đừng cố dịch thêm chữ \"bắt đầu\".<br>・Khi nói \"làm việc gì lúc mấy giờ\" phải dùng 「に」, không phải 「から」, phần dưới sẽ nói kỹ hơn.</div><div class='gd-h'>Phân biệt với những mẫu dễ lẫn</div><div class='gd-sec'><b>① から chỉ điểm bắt đầu vs に chỉ mốc thời gian</b><br><span class='gd-jp'>9時に起きます。</span>（Thức dậy lúc 9 giờ: chỉ đúng một thời điểm đó）<br><span class='gd-jp'>9時から勉強します。</span>（Học từ 9 giờ: sau đó kéo dài một lúc）<br>「Thức dậy」là hành động xong ngay lập tức, nên nói 9時から起きます sẽ nghe rất lạ.</div><div class='gd-warn'>Mẹo nhỏ: chỉ nói \"làm vào lúc mấy giờ\" thì dùng に; muốn nói \"từ lúc đó trở đi, việc đó cứ tiếp diễn\" thì dùng から.</div><div class='gd-sec'><b>② から chỉ điểm bắt đầu vs から chỉ lý do</b><br>Ở N5 bạn còn học một 「から」khác, nghĩa là \"vì, bởi vì\". Hai cái giống hệt nhau, cần nhìn <b>phía trước nó là gì</b>.<br>Điểm bắt đầu: <b>danh từ + から trực tiếp</b>, ví dụ <span class='gd-jp'>駅から</span> (từ nhà ga).<br>Lý do: phía trước là <b>cả một câu</b>. Danh từ phải thêm だ hoặc です trước (<span class='gd-jp'>雨だから</span>、<span class='gd-jp'>雨ですから</span>), hoặc là thể thường hay thể lịch sự của động từ, tính từ い (<span class='gd-jp'>行くから</span>、<span class='gd-jp'>行きますから</span>、<span class='gd-jp'>高いから</span>、<span class='gd-jp'>高いですから</span>).<br>Cùng là \"ngày mai thi\", so sánh thử nhé:<br><span class='gd-jp'>明日からテストです。</span>（Từ ngày mai bắt đầu thi）<br><span class='gd-jp'>明日テストだから、勉強します。</span>（Vì mai có bài thi nên mình sẽ học）</div><div class='gd-warn'>Mẹo nhỏ: nếu trước から chỉ có danh từ như thời gian, địa điểm, người thì là \"từ\"; nếu phía trước là だ／です, hoặc thể thường, thể lịch sự của động từ, tính từ (<span class='gd-jp'>行くから</span>、<span class='gd-jp'>行きますから</span>、<span class='gd-jp'>高いから</span>) thì là \"vì\". (「Động từ thể て + から」là một mẫu ngữ pháp khác, nghĩa là \"sau khi làm xong ～\", đừng lẫn vào nhé.)</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bạn có thể học cùng cặp đôi 「まで」(đến). Sau này bạn còn gặp 「Động từ thể て + から」＝ sau khi làm xong ～ thì mới ～: <span class='gd-jp'>ご飯を食べてから、出かけます。</span>（Ăn cơm xong rồi mới ra ngoài）</div>","n5-26":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「まで」nghĩa là <b>「đến ～」「cho đến ～」</b>, đánh dấu <b>điểm kết thúc</b>. Có thể là điểm kết thúc về thời gian (đến 5 giờ) hoặc về địa điểm (đến nhà ga). Nó rất hay đi thành cặp với 「から」(từ ～): <span class='gd-jp'>から</span> là điểm bắt đầu, <span class='gd-jp'>まで</span> là điểm kết thúc.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Thời gian</span>Một việc cứ tiếp diễn, đến mốc thời gian đó mới dừng.</div><div class='gd-ex-line'>・<span class='gd-jp'>5時まで待ちます。</span>（Mình sẽ đợi đến 5 giờ）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は11時まで寝ました。</span>（Hôm qua mình ngủ đến 11 giờ）</div><div class='gd-sec'><span class='gd-tag'>Địa điểm</span>Di chuyển đến đâu thì dừng.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩きます。</span>（Mình đi bộ đến nhà ga）</div><div class='gd-ex-line'>・<span class='gd-jp'>空港までバスで行きます。</span>（Mình đi xe buýt đến sân bay）</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Rất đơn giản, thêm まで ngay sau danh từ, không cần biến đổi.<br><span class='gd-pair'><span class='gd-jp'>6時</span> → <span class='gd-jp'>6時まで</span></span><span class='gd-pair'><span class='gd-jp'>金曜日</span> → <span class='gd-jp'>金曜日まで</span></span><span class='gd-pair'><span class='gd-jp'>東京</span> → <span class='gd-jp'>東京まで</span></span></div><div class='gd-h'>Dạng nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>から～まで</span>Từ đâu đến đâu, từ mấy giờ đến mấy giờ, nói rõ cả khoảng trong một lần.</div><div class='gd-ex-line'>・<span class='gd-jp'>9時から5時まで働きます。</span>（Mình làm việc từ 9 giờ đến 5 giờ）</div><div class='gd-ex-line'>・<span class='gd-jp'>東京から大阪まで新幹線で行きます。</span>（Đi tàu Shinkansen từ Tokyo đến Osaka）</div><div class='gd-sec'><span class='gd-tag'>～までです</span>Theo sau là です luôn, rất hay dùng khi nói giờ mở cửa, giờ học.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は夜10時までです。</span>（Cửa hàng này mở đến 10 giờ tối）</div><div class='gd-sec'><span class='gd-tag'>いつまで・どこまで</span>Hỏi \"đến bao giờ\", \"đến đâu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>いつまで日本にいますか。</span>（Bạn sẽ ở Nhật đến khi nào?）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Ý của まで là hành động <b>liên tục</b> cho đến mốc đó. Tiếng Việt \"đến\" vừa có nghĩa \"tới nơi\" vừa có nghĩa \"cho đến khi\", nhưng まで chỉ mang nghĩa sau. Vì vậy không thể dịch thẳng \"hãy đến lúc 5 giờ\" thành 「5時まで来てください」, nghe sẽ rất kỳ. Muốn nói \"hãy đến lúc 5 giờ\" thì dùng <span class='gd-jp'>5時に来てください</span>.<br>・「金曜日まで休みです」thường <b>bao gồm</b> cả thứ Sáu, tức thứ Sáu cũng nghỉ.<br>・まで chỉ đánh dấu điểm kết thúc, tự nó không mang nghĩa \"đi\", phía sau vẫn cần động từ, như <span class='gd-jp'>駅まで歩きます</span>、<span class='gd-jp'>駅まで行きます</span>.</div><div class='gd-h'>Phân biệt với những mẫu dễ lẫn</div><div class='gd-sec'><b>に (mốc thời gian)</b> ＝ việc <b>xảy ra một lần</b> vào thời điểm đó: <span class='gd-jp'>11時に寝ました。</span>（Mình đi ngủ lúc 11 giờ）<br><b>まで</b> ＝ <b>làm liên tục cho đến</b> thời điểm đó: <span class='gd-jp'>11時まで寝ました。</span>（Mình ngủ một mạch đến 11 giờ）<br>Chỉ khác một chữ thôi, nhưng một câu là 11 giờ đi ngủ, một câu là 11 giờ mới dậy.</div><div class='gd-sec'><b>までに</b> ＝ <b>hoàn thành trước</b> thời điểm đó (hạn chót): <span class='gd-jp'>5時までに帰ります。</span>（Mình sẽ về trước 5 giờ）<br><b>まで</b> ＝ tiếp diễn liên tục đến thời điểm đó: <span class='gd-jp'>5時まで待ちます。</span>（Mình sẽ đợi đến 5 giờ）</div><div class='gd-warn'>Mẹo nhỏ: \"liên tục đến mấy giờ\" dùng まで; \"phải làm xong trước mấy giờ\" dùng までに; \"làm việc đó vào lúc mấy giờ\" dùng に.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm に sau まで sẽ thành <span class='gd-jp'>までに</span>, dùng để nói hạn chót: <span class='gd-jp'>金曜日までに出してください。</span>（Hãy nộp trước thứ Sáu nhé）</div>","n5-29":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「で」này chính là <b>「bằng ～」</b> trong tiếng Việt. Ăn bằng đũa, nói bằng tiếng Nhật, liên lạc bằng điện thoại: tiếng Nhật đều thêm 「で」 ngay sau thứ được dùng: <span class='gd-jp'>はしで食べます</span> (ăn bằng đũa).</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Công cụ</span>Thứ cầm trong tay để làm việc.</div><div class='gd-ex-line'>・<span class='gd-jp'>はしで食べます。</span>(Ăn bằng đũa)</div><div class='gd-ex-line'>・<span class='gd-jp'>ボールペンで書いてください。</span>(Hãy viết bằng bút bi)</div><div class='gd-sec'><span class='gd-tag'>Ngôn ngữ</span>Nói hay viết bằng thứ tiếng nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語で話しましょう。</span>(Mình nói chuyện bằng tiếng Nhật nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>これは英語で何と言いますか。</span>(Cái này nói bằng tiếng Anh là gì?)</div><div class='gd-sec'><span class='gd-tag'>Phương thức</span>Làm được việc đó thông qua cách nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>母と電話で話しました。</span>(Mình đã nói chuyện với mẹ qua điện thoại)</div><div class='gd-ex-line'>・<span class='gd-jp'>ネットでチケットを買いました。</span>(Mình đã mua vé trên mạng)</div><div class='gd-sec'><span class='gd-tag'>Nguyên liệu</span>Làm ra từ cái gì, và làm xong vẫn nhìn ra nguyên liệu ban đầu.</div><div class='gd-ex-line'>・<span class='gd-jp'>紙で花を作りました。</span>(Mình đã làm hoa bằng giấy)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Rất đơn giản: <b>thêm 「で」 ngay sau danh từ</b>, không cần biến đổi gì.<br><span class='gd-pair'><span class='gd-jp'>スプーン</span> → <span class='gd-jp'>スプーンで</span></span><span class='gd-pair'><span class='gd-jp'>英語</span> → <span class='gd-jp'>英語で</span></span><br>Việc muốn làm vẫn dùng 「を」 đặt trước động từ như bình thường: <span class='gd-jp'>スプーンでスープを飲みます。</span>(Uống súp bằng thìa)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tiếng Việt nói “ăn <b>bằng</b> đũa”, công cụ đứng sau động từ. Tiếng Nhật thì 「はしで」 đứng <b>trước</b> động từ, và 「で」 nằm <b>sau</b> danh từ. Thứ tự vừa ngược vừa khác vị trí, bạn nhớ nhé.<br>・Người mới học hay coi công cụ là tân ngữ và nói thành 「はしを食べます」, nghĩa sẽ thành “ăn đũa”. Sau công cụ phải dùng <b>で</b>.<br>・Muốn hỏi “bằng gì” thì nói <span class='gd-jp'>何で</span>, đọc là <b>なにで</b>: <span class='gd-jp'>何で書きますか。</span>(Viết bằng gì vậy?) Nếu đọc thành なんで, trong văn nói rất dễ bị nghe thành “tại sao”.</div><div class='gd-h'>Phân biệt với những mẫu trông giống</div><div class='gd-sec'><b>で (địa điểm)</b>: làm ở đâu: <span class='gd-jp'>教室で書きます。</span>(Viết ở lớp học)<br><b>で (công cụ)</b>: làm bằng gì: <span class='gd-jp'>ペンで書きます。</span>(Viết bằng bút)<br>Hai cái này có thể đứng chung một câu: <span class='gd-jp'>教室でペンで書きます。</span>(Viết bằng bút ở lớp học)<br>Ngoài ra, 「で」 trong <span class='gd-jp'>バスで行きます</span> (đi bằng xe buýt) thật ra cũng mang nghĩa “bằng phương tiện nào”, cùng một ý với thẻ này.</div><div class='gd-warn'>Mẹo phán đoán: phía trước là “một địa điểm” thì nghĩa là “ở ～”; phía trước là “đồ dùng, ngôn ngữ, phương pháp” thì nghĩa là “bằng ～”.</div><div class='gd-sec'><b>日本語を話します</b>: biết nói tiếng Nhật, tiếng Nhật là thứ bạn có khả năng.<br><b>日本語で話します</b>: nói bằng tiếng Nhật, tiếng Nhật là công cụ giao tiếp.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は日本語を話します。</span>(Tôi nói được tiếng Nhật)</div><div class='gd-ex-line'>・<span class='gd-jp'>店員と日本語で話しました。</span>(Mình đã nói chuyện với nhân viên cửa hàng bằng tiếng Nhật)</div><div class='gd-warn'>Mẹo phán đoán: muốn nói “tôi nói được thứ tiếng nào” thì dùng を; muốn nói “lần này giao tiếp bằng thứ tiếng nào” thì dùng で.</div>","n5-30":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「に」 đứng sau <b>người</b>, cho biết hành động này được làm <b>với ai, cho ai</b>. Tiếng Việt nói “gọi điện <b>cho</b> bạn”, “<b>hỏi</b> thầy cô”, “nói <b>với</b> mẹ”, mỗi lần dùng một từ khác nhau. Tiếng Nhật đơn giản hơn nhiều: cứ thêm một chữ 「に」 sau người đó là xong.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Thứ tự cơ bản là: <b>người＋に</b>　<b>vật＋を</b>　<b>động từ</b>.<br>Nói trước là với ai, rồi đến cái gì, cuối cùng mới đến hành động:<br><span class='gd-jp'>母に</span> (cho mẹ) ＋ <span class='gd-jp'>花を</span> (hoa) ＋ <span class='gd-jp'>あげます</span> (tặng) → <span class='gd-jp'>母に花をあげます。</span><br>Nếu hành động không có “vật”, chỉ cần “người＋に＋động từ”: <span class='gd-jp'>友達に電話します。</span>(Gọi điện cho bạn)</div><div class='gd-h'>Những dạng hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>Đưa đồ cho ai đó</span>Tặng, cho mượn, cho xem.</div><div class='gd-ex-line'>・<span class='gd-jp'>母に花をあげます。</span>(Tặng hoa cho mẹ)</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を貸しました。</span>(Mình đã cho em gái mượn sách)</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に写真を見せます。</span>(Cho bạn xem ảnh)</div><div class='gd-sec'><span class='gd-tag'>Nói với ai, liên lạc</span>Gọi điện, viết thư, hỏi câu hỏi.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達に電話します。</span>(Gọi điện cho bạn)</div><div class='gd-ex-line'>・<span class='gd-jp'>先生に聞きます。</span>(Hỏi thầy cô)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんに手紙を書きました。</span>(Mình đã viết thư cho anh Tanaka)</div><div class='gd-sec'><span class='gd-tag'>Dạy ai đó</span></div><div class='gd-ex-line'>・<span class='gd-jp'>弟に英語を教えます。</span>(Dạy tiếng Anh cho em trai)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tiếng Việt nói “hỏi thầy”, “gặp bạn”, người đứng thẳng sau động từ, nên nhiều bạn tiện tay dùng を. <span class='gd-jp'>先生を聞きます</span> là sai, phải nói <span class='gd-jp'>先生に聞きます</span>; <span class='gd-jp'>友達を会います</span> cũng sai, phải nói <span class='gd-jp'>友達に会います</span>. Có điều cũng có động từ dùng を với người, ví dụ <span class='gd-jp'>友達を待ちます</span> (đợi bạn), nên hãy nhớ từng động từ cùng với câu ví dụ, đừng chỉ đoán theo tiếng Việt.<br>・Người đứng sau に <b>không nhất định là người nhận đồ</b>. Với các hành động như “mượn (về mình)” hay “học”, người đi với に lại là nguồn của thứ đó: <span class='gd-jp'>友達に本を借りました。</span>(Mình đã mượn sách của bạn), <span class='gd-jp'>先生に日本語を習います。</span>(Học tiếng Nhật với thầy cô).<br>・「に」 còn có cách dùng khác, như thời gian (<span class='gd-jp'>7時に</span>), địa điểm (<span class='gd-jp'>東京に</span>). Hãy nhìn phía trước nó là gì: nếu là <b>người</b> thì thường chính là cách dùng của thẻ này.</div><div class='gd-h'>Phân biệt với những mẫu trông giống</div><div class='gd-sec'>Chữ “với” trong tiếng Việt rất dễ khiến bạn lẫn giữa <b>に</b> và <b>と</b>:<br><span class='gd-jp'>友達に話します。</span>(Nói cho bạn biết một chuyện: mình nói, bạn nghe, là <b>một chiều</b>)<br><span class='gd-jp'>友達と話します。</span>(Nói chuyện với bạn: hai người trao đổi qua lại, là làm <b>cùng nhau</b>)<br>Cùng là “nói chuyện với bạn”, dùng に là mình nói với bạn, dùng と là hai người cùng trò chuyện.</div><div class='gd-warn'>Mẹo phán đoán: nếu “với” trong tiếng Việt thay được bằng “cùng ～”, thì dùng と; nếu chỉ thay được bằng “cho”, “đối với”, “hỏi”, thì dùng に.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cách nói “ai cho ai cái gì”, ví dụ <span class='gd-jp'>あげます</span>, <span class='gd-jp'>もらいます</span>, <span class='gd-jp'>くれます</span>, đều dùng đến 「に」 này mãi, nên bạn có thể học tiếp động từ cho nhận nhé.</div>","n5-35":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Đặt 「が」 ở cuối một câu thì nó mang nghĩa <b>“……, nhưng……”</b> trong tiếng Việt. Bạn nói một việc trước, rồi nối với một việc khác với dự đoán. Ví dụ “Quán này đắt, nhưng ngon” thì tiếng Nhật là <span class='gd-jp'>この店は高いですが、おいしいです。</span></div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Vế trước phải là <b>một câu nói trọn vẹn</b>. Ở N5, câu thường kết thúc bằng 「です」 hoặc 「ます」. Nói xong thì thêm が, đặt dấu phẩy rồi nối sang vế sau.<br><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>雨です</span> → <span class='gd-jp'>雨ですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>行きたいです</span> → <span class='gd-jp'>行きたいですが、</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強しました</span> → <span class='gd-jp'>勉強しましたが、</span></span><br>Vế đầu dùng 「です・ます」 thì vế sau cũng dùng 「です・ます」. Mức độ lịch sự của cả câu phải thống nhất.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đối lập</span>Hai việc trước và sau có hướng ngược nhau, hoặc kết quả khác với điều bạn mong đợi.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は難しいですが、おもしろいです。</span>(Tiếng Nhật khó, nhưng thú vị)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は雨でしたが、出かけました。</span>(Hôm qua trời mưa, nhưng mình vẫn đi ra ngoài)</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲みましたが、まだ頭が痛いです。</span>(Mình uống thuốc rồi, nhưng vẫn còn đau đầu)</div><div class='gd-sec'><span class='gd-tag'>Mở lời</span>Trước khi nhờ ai giúp hoặc hỏi điều gì, bạn nói 「すみませんが」 hoặc 「失礼ですが」 để dạo đầu. Lúc này が không có nghĩa “nhưng”, chỉ làm giọng điệu lịch sự hơn, giống như “Xin lỗi, cho mình hỏi……” trong tiếng Việt.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみませんが、駅はどこですか。</span>(Xin lỗi, cho mình hỏi ga tàu ở đâu ạ?)</div><div class='gd-ex-line'>・<span class='gd-jp'>失礼ですが、お名前は？</span>(Xin lỗi, cho hỏi tên của bạn là gì ạ?)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Trong tiếng Việt, “tuy” hoặc “mặc dù” đứng <b>ở đầu</b> câu, còn “nhưng” đứng đầu vế sau. Còn が của tiếng Nhật nằm <b>ở cuối vế đầu</b>. Đừng cố tìm một từ ở đầu câu để đối ứng với “tuy/mặc dù”.<br>・Trong cùng một câu có thể xuất hiện hai chữ が: <span class='gd-jp'>雨が降っていますが、行きます。</span>(Tuy trời đang mưa, nhưng mình vẫn đi). Chữ が đầu nối sau danh từ 「雨」, là が đánh dấu chủ ngữ. Chữ が thứ hai nối sau cả câu 「降っています」, đó mới là “nhưng”. Cách phân biệt rất đơn giản: xem trước が là <b>một danh từ</b> hay <b>một câu đã nói xong</b>.<br>・Đã dùng が thì không cần thêm でも nữa, chỉ cần nói <span class='gd-jp'>高いですが、おいしいです。</span> là đủ.<br>・Khi trò chuyện với bạn bè mà nói 「高いが、おいしい」, tức là không có です・ます mà nối thẳng が, nghe sẽ rất cứng, giống văn viết. Giữa bạn bè thì dùng けど tự nhiên hơn.</div><div class='gd-h'>Phân biệt với các cách nói giống nhau</div><div class='gd-sec'>Cùng là “đắt nhưng ngon”, có ba cách nói thường gặp:<br><b>が</b>: <span class='gd-jp'>高いですが、おいしいです。</span> Khá trang trọng, hợp khi nói với khách, người lớn tuổi hoặc khi viết thư.<br><b>けど</b>: <span class='gd-jp'>高いけど、おいしい。</span> Đây là cách nói khẩu ngữ, nghe nhiều nhất trong trò chuyện hằng ngày. Thêm です cũng được: <span class='gd-jp'>高いですけど、おいしいです。</span><br><b>でも</b>: <span class='gd-jp'>高いです。でも、おいしいです。</span> Câu trước kết thúc bằng dấu chấm, sang câu sau mới mở đầu bằng でも.</div><div class='gd-warn'>Mẹo nhỏ để chọn: nối ở cuối câu và muốn nói trang trọng một chút thì dùng が. Trò chuyện với bạn bè thì dùng けど. Câu trước đã nói xong và bạn muốn chuyển ý ở đầu câu mới thì dùng でも.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hãy xem tiếp 「けど」. Nghĩa của nó giống が nhưng khẩu ngữ hơn, khi nói chuyện với bạn bè hầu như ai cũng dùng nó.</div>","n5-36":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「けど」 gần giống “…, nhưng mà…” trong tiếng Việt. Nó có hai cách dùng: một là <b>hai vế có ý ngược nhau</b>, như “tuy nhỏ nhưng dễ dùng”; hai là <b>dạo đầu</b> để dẫn vào chủ đề, giống như “Xin lỗi, mình muốn hỏi một chút……”. Người Nhật dùng nó liên tục khi nói chuyện hằng ngày.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Hai vế ngược nhau</span>Vế trước nói một việc, vế sau nói việc ngược lại hoặc ngoài dự đoán.</div><div class='gd-ex-line'>・<span class='gd-jp'>小さいけど、使いやすいです。</span>(Tuy nhỏ nhưng rất dễ dùng)</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いけど、おいしいです。</span>(Quán này rẻ mà vẫn ngon)</div><div class='gd-sec'><span class='gd-tag'>Dạo đầu</span>Nói trước bối cảnh rồi mới đưa ra câu hỏi, lời mời hoặc lời nhờ vả. Lúc này けど <b>không có nghĩa “nhưng”</b>, mà giống “Thế này nè……” hơn. Vế sau cũng hay bị bỏ lửng, để đối phương tự tiếp lời.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日映画を見に行くけど、一緒に行かない？</span>(Mai mình đi xem phim, bạn có muốn đi cùng không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、駅に行きたいんですけど…</span>(Xin lỗi, mình muốn đến ga tàu……)</div><div class='gd-ex-line'>・<span class='gd-jp'>もしもし、田中ですけど…</span>(A lô, mình là Tanaka đây……)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>けど dính vào <b>cuối câu trước</b>, nên phía trước phải là một câu hoàn chỉnh.<br><b>Nói với bạn bè (không dùng です・ます)</b>:<br>Động từ và tính từ い thì thêm trực tiếp: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くけど</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いけど</span></span><br>Danh từ và tính từ な phải thêm 「だ」 trước: <span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生だけど</span></span><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいだけど</span></span></div><div class='gd-sec'><b>Cách nói lịch sự</b>: phía trước dùng です・ます rồi thêm けど.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行きますけど</span></span><span class='gd-pair'><span class='gd-jp'>高いです</span> → <span class='gd-jp'>高いですけど</span></span><span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生ですけど</span></span><br>Hãy học thuộc cả mẫu 「<span class='gd-jp'>〜たいんですけど…</span>」 như một cụm cố định, khi hỏi đường, nhờ vả hay đến quầy hỏi việc đều dùng được.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Quên thêm だ sau danh từ và tính từ な: <span class='gd-jp'>学生けど</span>× phải nói <span class='gd-jp'>学生だけど</span>; <span class='gd-jp'>静かけど</span>× phải nói <span class='gd-jp'>静かだけど</span>. Ngược lại, tính từ い thì <b>không</b> thêm だ: <span class='gd-jp'>高いだけど</span>×, nói thẳng <span class='gd-jp'>高いけど</span>.<br>・Trong tiếng Việt, “nhưng” đứng ở đầu vế sau, còn けど của tiếng Nhật dính vào <b>đuôi câu trước</b>. Nếu muốn mở đầu câu thứ hai bằng “nhưng”, phải dùng <span class='gd-jp'>でも</span> (sẽ so sánh ở dưới).<br>・Câu dừng ở 「〜けど…」 không phải là nói dở, mà là cách nói <b>lịch sự, không nói chắc nịch</b> của người Nhật. Khi dịch sang tiếng Việt đừng cứng nhắc dịch thành “nhưng”.<br>・けど dùng khi nói chuyện, trò chuyện hay nói với nhân viên cửa hàng đều rất tự nhiên. Khi viết báo cáo hoặc ở nơi trang trọng thì đổi sang 「が」 sẽ an toàn hơn.<br>・<span class='gd-jp'>けれど</span> và <span class='gd-jp'>けれども</span> có nghĩa giống nhau, càng dài càng trang trọng.</div><div class='gd-h'>Phân biệt với các cách nói giống nhau</div><div class='gd-sec'>Cùng một việc: quần áo đắt nhưng vẫn mua.<br><b>けど</b> = giọng nói thường ngày: <span class='gd-jp'>高いけど、買いました。</span><br><b>が</b> = trang trọng hơn, dùng trong văn viết hoặc nơi trang trọng: <span class='gd-jp'>高いですが、買いました。</span><br><b>でも</b> = nói xong câu đầu rồi, đến đầu câu thứ hai mới nói “nhưng mà”: <span class='gd-jp'>高いです。でも、買いました。</span></div><div class='gd-sec'>Cách dùng dạo đầu cũng vậy, với cấp trên hay người lớn tuổi, nếu muốn lịch sự hơn thì đổi けど thành が: <span class='gd-jp'>ちょっと聞きたいんですが…</span>(Mình muốn hỏi một chút……)</div><div class='gd-warn'>Mẹo nhỏ để chọn: nói chuyện thường ngày thì dùng けど. Trang trọng hoặc viết văn thì dùng が. Muốn tách thành hai câu, mở đầu câu thứ hai bằng “nhưng mà” thì dùng でも.</div>","n5-37":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「に」này dùng để nói <b>bạn đi / đến / về là để làm gì</b>. Tiếng Việt nói \"đi mua đồ\", \"đến chơi\", còn tiếng Nhật đặt việc định làm lên trước, rồi mới thêm 「に行きます」「に来ます」: <span class='gd-jp'>買いに行きます</span> (đi mua), <span class='gd-jp'>遊びに来ます</span> (đến chơi).</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Động từ</span>Đầu tiên chia động từ sang dạng ます, bỏ 「ます」 đi, rồi thêm 「に」.<br><span class='gd-pair'><span class='gd-jp'>買います</span> → bỏ ます → <span class='gd-jp'>買いに行きます</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べに行きます</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見に行きます</span></span><span class='gd-pair'><span class='gd-jp'>会います</span> → <span class='gd-jp'>会いに行きます</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>お土産を買いに行きます。</span> (Đi mua quà)</div><div class='gd-ex-line'>・<span class='gd-jp'>週末、友達に会いに行きます。</span> (Cuối tuần mình đi gặp bạn)</div><div class='gd-ex-line'>・<span class='gd-jp'>昼ごはんを食べに家へ帰ります。</span> (Về nhà ăn trưa)</div><div class='gd-ex-line'>・<span class='gd-jp'>書類を届けに来ました。</span> (Tôi đến để đưa tài liệu)</div><div class='gd-sec'><span class='gd-tag'>Danh từ</span>Những danh từ tự thân đã mang nghĩa \"một hành động\" như <span class='gd-jp'>買い物</span>, <span class='gd-jp'>散歩</span>, <span class='gd-jp'>旅行</span>, <span class='gd-jp'>食事</span> thì có thể thêm 「に」 trực tiếp.</div><div class='gd-ex-line'>・<span class='gd-jp'>デパートへ買い物に行きます。</span> (Đi trung tâm thương mại mua sắm)</div><div class='gd-ex-line'>・<span class='gd-jp'>公園へ散歩に行きませんか。</span> (Bạn có muốn đi dạo công viên không?)</div><div class='gd-h'>Khi một câu có cả địa điểm lẫn mục đích</div><div class='gd-sec'>Thứ tự thường là: <b>địa điểm＋へ　→　mục đích＋に　→　行きます</b>.<br><span class='gd-jp'>図書館へ本を借りに行きます。</span> (Đi thư viện mượn sách)<br>Sau địa điểm dùng 「へ」 thì câu sẽ không bị hai chữ に đứng sát nhau, nghe rõ ràng hơn.</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Phía trước phải dùng <b>dạng ます bỏ ます</b>, không được đặt thẳng dạng từ điển: đúng là <span class='gd-jp'>買いに行きます</span>, không phải 「買うに行きます」.<br>・Phía sau chỉ đi với <b>động từ chỉ sự di chuyển</b>, thường gặp nhất là <span class='gd-jp'>行きます</span>, <span class='gd-jp'>来ます</span>, <span class='gd-jp'>帰ります</span>. Những câu không liên quan đến di chuyển, ví dụ \"đọc sách để học tiếng Nhật\", thì không dùng được に này.<br>・Tiếng Việt nói \"đi + mua\", còn tiếng Nhật là 「買い＋に行く」, nên <b>thứ tự ngược với tiếng Việt</b>, đừng nói thành 「行きに買います」.<br>・「を」 đứng trước động từ ban đầu vẫn giữ nguyên: <span class='gd-jp'>お土産を買いに行きます</span>.<br>・<span class='gd-jp'>遊びに来てください。</span> (Hãy đến chơi nhé) là lời mời rất hay được người Nhật dùng, bạn có thể học thuộc cả câu.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>Cùng là 「に行きます」, <b>thứ đứng trước に</b> quyết định ý nghĩa:<br><b>Địa điểm＋に</b> = đi <b>đâu</b>: <span class='gd-jp'>デパートに行きます。</span> (Đi trung tâm thương mại)<br><b>Hành động＋に</b> = đi <b>để làm gì</b>: <span class='gd-jp'>買い物に行きます。</span> (Đi mua sắm)<br>Ghép cả hai: <span class='gd-jp'>デパートへ買い物に行きます。</span> (Đi trung tâm thương mại mua sắm)</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: nếu trước に là \"nơi chốn\" thì đó là đi đâu; nếu trước に là \"động từ đã bỏ ます\" hoặc một hành động như 買い物, 散歩 thì đó là đi để làm gì.</div>","n5-39":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「ね」giống \"<b>nhỉ</b>\" hoặc \"<b>đúng không</b>\" trong tiếng Việt: dùng khi nói về điều <b>đối phương cũng biết, cũng cảm nhận được</b>, để cùng đồng cảm hoặc xác nhận lại với họ.<br>「よ」giống \"<b>đấy</b>\" hoặc \"<b>nhé</b>\": dùng khi nói về điều <b>đối phương chưa biết</b>, bạn muốn báo cho họ hoặc nhắc họ.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>ね: cùng đồng cảm</span>Hai người cùng thấy, cùng ăn, cùng cảm nhận một điều, và bạn nói ra để tìm sự đồng cảm.</div><div class='gd-ex-line'>・<span class='gd-jp'>いい天気ですね。</span> (Thời tiết đẹp nhỉ)</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしいですね。</span> (Cái bánh này ngon nhỉ)</div><div class='gd-sec'><span class='gd-tag'>ね: xác nhận lại</span>Bạn đại khái biết rồi, nhưng muốn hỏi lại cho chắc là mình không nhớ nhầm. Nhân viên quán xác nhận món bạn gọi cũng dùng như vậy.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は休みですね。</span> (Ngày mai nghỉ, đúng không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>コーヒー二つですね。</span> (Hai ly cà phê, đúng không ạ?)</div><div class='gd-sec'><span class='gd-tag'>よ: báo cho đối phương biết</span>Bạn biết, đối phương không biết, ví dụ như giới thiệu hay chia sẻ tin tức.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店、安いですよ。</span> (Quán này rẻ đấy)</div><div class='gd-ex-line'>・<span class='gd-jp'>この番組、面白いですよ。</span> (Chương trình này hay đấy)</div><div class='gd-sec'><span class='gd-tag'>よ: nhắc nhở</span>Điều đối phương chưa để ý, bạn nhắc họ chú ý.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう始まりますよ。</span> (Sắp bắt đầu rồi đấy)</div><div class='gd-ex-line'>・<span class='gd-jp'>電車が来ましたよ。</span> (Tàu đến rồi đấy)</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Rất đơn giản, nói xong câu thì <b>đặt thẳng vào cuối câu</b> là được.<br>Cách nói lịch sự: <span class='gd-pair'><span class='gd-jp'>おいしいです</span> → <span class='gd-jp'>おいしいですね</span></span><span class='gd-pair'><span class='gd-jp'>始まります</span> → <span class='gd-jp'>始まりますよ</span></span><br>Cách nói với bạn bè cũng vậy, thêm thẳng vào: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>いいね</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くよ</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨だね</span></span></div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・<b>Điều đối phương không thể biết thì đừng thêm ね</b>. Khi tự giới thiệu mà nói 「私は台湾人ですね」, nghe như bạn đang hỏi người kia \"tôi là người Đài Loan đúng không nhỉ?\", rất lạ. Cứ nói <span class='gd-jp'>私は台湾人です。</span> là được.<br>・<b>Sắc thái của よ mạnh hơn</b>. Khi sửa lỗi cho thầy cô, cấp trên mà thêm よ, ví dụ 「それは違いますよ」, nghe hơi giống đang dạy đời họ. Với người lớn tuổi hơn, nên dùng よ ít thôi cho an toàn.<br>・Ngữ điệu của ね: <b>lên giọng ở cuối</b> là đang xác nhận \"đúng không?\"; <b>giọng đều hoặc xuống</b> là đang cảm thán \"thật là ... nhỉ\".<br>・Người Việt nói chuyện cũng hay thêm \"nhỉ\", \"nhé\", \"nha\", nhưng tiếng Nhật không cần câu nào cũng thêm. Khi chỉ mô tả sự việc bình thường, không thêm gì vẫn rất tự nhiên; câu nào cũng ね, よ thì nghe lại rất ồn.</div><div class='gd-h'>Phân biệt với mẫu trông giống nhau</div><div class='gd-sec'>Cùng là \"bên ngoài đang mưa\", hãy chọn theo việc đối phương có biết hay không:<br><b>ね</b> = đối phương cũng thấy rồi, cùng cảm thán: <span class='gd-jp'>雨ですね。</span> (Mưa rồi nhỉ)<br><b>よ</b> = đối phương ở trong nhà chưa biết, bạn báo cho họ: <span class='gd-jp'>雨ですよ。</span> (Bên ngoài đang mưa đấy)<br><b>か</b> = bạn hoàn toàn không biết, đang hỏi người khác: <span class='gd-jp'>雨ですか。</span> (Đang mưa à?)</div><div class='gd-sec'>「ね」và「か」đều có thể làm câu hỏi, khác nhau ở chỗ trong lòng bạn đã có đáp án hay chưa:<br><span class='gd-jp'>明日は休みですか。</span> (Ngày mai nghỉ à?: không biết, hỏi thử)<br><span class='gd-jp'>明日は休みですね。</span> (Ngày mai nghỉ, đúng không?: đại khái biết, xác nhận lại)</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: đối phương cũng biết → ね; đối phương không biết, bạn muốn báo cho họ → よ; chính bạn không biết → か.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hai chữ này có thể ghép lại thành 「よね」, thứ tự cố định là よ đứng trước, không được nói 「ねよ」. Nghĩa là \"mình nhớ là như vậy, đúng không nhỉ?\": <span class='gd-jp'>テストは明日ですよね。</span> (Bài kiểm tra là ngày mai, đúng không nhỉ?)</div>","n5-40":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Trợ từ tiếng Nhật cũng giống chữ “ở”, “với” trong tiếng Việt: <b>một từ thường có nhiều nghĩa</b>. Trước đây bạn đã học cách dùng cơ bản của を、に、で、は、か. Bài này gom lại <b>những cách dùng thường gặp khác</b> của chúng. Khi gặp trợ từ, đừng chỉ nhớ một nghĩa, hãy nhìn từ đứng trước và sau để phán đoán.</div><div class='gd-h'>を：rời khỏi, đi qua</div><div class='gd-sec'><span class='gd-tag'>Nơi rời khỏi</span>Đi ra khỏi một nơi nào đó, xuống xe, tốt nghiệp thì nơi đó dùng を. Thường đi cùng <span class='gd-jp'>出る</span>、<span class='gd-jp'>降りる</span>、<span class='gd-jp'>卒業する</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>7時に家を出ます。</span>（Tôi ra khỏi nhà lúc 7 giờ）</div><div class='gd-ex-line'>・<span class='gd-jp'>次の駅で電車を降ります。</span>（Tôi xuống tàu ở ga tiếp theo）</div><div class='gd-sec'><span class='gd-tag'>Nơi đi qua</span>Với những hành động có di chuyển như đi bộ, chạy, đi dạo, qua cầu, thì tuyến đường hay khu vực đi qua dùng を.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝、公園を散歩します。</span>（Sáng nào tôi cũng đi dạo trong công viên）</div><div class='gd-ex-line'>・<span class='gd-jp'>この橋を渡ってください。</span>（Hãy đi qua cây cầu này）</div><div class='gd-h'>に：tần suất, rơi vào đâu, trở thành</div><div class='gd-sec'><span class='gd-tag'>Tần suất</span>Khoảng thời gian＋に＋số lần＝bao lâu thì mấy lần.</div><div class='gd-ex-line'>・<span class='gd-jp'>1日に3回、薬を飲みます。</span>（Một ngày uống thuốc ba lần）</div><div class='gd-ex-line'>・<span class='gd-jp'>週に1回、プールへ行きます。</span>（Một tuần tôi đi bơi một lần）</div><div class='gd-sec'><span class='gd-tag'>Đồ vật rơi vào đâu</span>Viết lên, ngồi lên, bỏ vào: nơi mà đồ vật cuối cùng “chạm tới, nằm lại” thì dùng に.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>（Hãy viết tên vào đây）</div><div class='gd-ex-line'>・<span class='gd-jp'>椅子に座ります。</span>（Ngồi xuống ghế）</div><div class='gd-sec'><span class='gd-tag'>Trở thành</span>Danh từ＋になる＝trở thành ～.</div><div class='gd-ex-line'>・<span class='gd-jp'>将来、先生になりたいです。</span>（Sau này tôi muốn làm giáo viên）</div><div class='gd-h'>で：phạm vi, tổng cộng</div><div class='gd-sec'><span class='gd-tag'>Phạm vi</span>“Trong ～ thì ～ nhất”, phạm vi đó dùng で.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄はクラスでいちばん背が高いです。</span>（Anh trai tôi cao nhất lớp）</div><div class='gd-sec'><span class='gd-tag'>Tổng cộng</span>Số lượng＋で＝cộng lại, tổng cộng. Đi mua sắm rất hay dùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>全部でいくらですか。</span>（Tất cả hết bao nhiêu tiền?）</div><div class='gd-ex-line'>・<span class='gd-jp'>りんごは3つで500円です。</span>（Táo ba quả 500 yên）</div><div class='gd-h'>は：dùng để đối chiếu</div><div class='gd-sec'><span class='gd-tag'>Đối chiếu</span>Đặt hai việc cạnh nhau để so sánh, mỗi việc dùng một は, nghĩa là “A thì thế này, còn B thì không phải vậy”.</div><div class='gd-ex-line'>・<span class='gd-jp'>寿司は好きですが、刺身は苦手です。</span>（Tôi thích sushi, nhưng sashimi thì không ổn lắm）</div><div class='gd-sec'>Chỉ nói một vế thôi cũng mang sắc thái “còn những cái khác thì chưa chắc”:</div><div class='gd-ex-line'>・<span class='gd-jp'>お酒は飲みません。</span>（Rượu thì tôi không uống）</div><div class='gd-h'>か：chọn một trong hai</div><div class='gd-sec'><span class='gd-tag'>Lựa chọn</span>AかB＝A hoặc B, chọn một trong số đó.</div><div class='gd-ex-line'>・<span class='gd-jp'>月曜日か火曜日に来てください。</span>（Hãy đến vào thứ Hai hoặc thứ Ba）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Lên xe dùng に, xuống xe dùng を：<span class='gd-jp'>電車に乗ります</span>、<span class='gd-jp'>電車を降ります</span>. Nhiều bạn dùng cùng một trợ từ cho cả hai.<br>・Nghĩa “đi qua” của を phải đi với động từ có di chuyển. Những việc làm tại chỗ như chơi trong công viên, ăn cơm hộp thì phải dùng で：<span class='gd-jp'>公園で遊びます</span>.<br>・Tiếng Việt nói “viết ở đây”, nên bạn dễ nghĩ ngay đến で. Nhưng viết lên giấy, ngồi lên ghế thì đồ vật “rơi xuống” chỗ đó, phải dùng に：<span class='gd-jp'>ここに書いてください</span>.<br>・は đối chiếu vẫn đọc là wa, không đọc là ha.</div><div class='gd-h'>Phân biệt với những từ trông giống nhau</div><div class='gd-sec'>か、と、や đều nối được hai món đồ, nhưng nghĩa khác nhau nhiều. Cùng là mua đồ uống:<br><span class='gd-jp'>コーヒーと紅茶を買いました。</span>（Đã mua cà phê và trà đen: mua cả hai）<br><span class='gd-jp'>コーヒーや紅茶を買いました。</span>（Đã mua cà phê, trà đen các thứ: còn có món khác）<br><span class='gd-jp'>コーヒーか紅茶を買います。</span>（Sẽ mua cà phê hoặc trà đen: chỉ chọn một）</div><div class='gd-warn'>Mẹo nhỏ: có tất cả thì dùng と, nêu vài ví dụ thì dùng や, chỉ chọn một thì dùng か.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>で chỉ phạm vi có thể dùng để hỏi “cái nào ～ nhất”：<span class='gd-jp'>果物の中で何がいちばん好きですか。</span>（Trong các loại trái cây, bạn thích gì nhất?）</div>","n5-41":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「ます形」chính là động từ khoác lên <b>chiếc áo lịch sự</b>. Trong từ điển bạn tra ra <span class='gd-jp'>飲む</span>, nhưng khi nói với thầy cô, nhân viên cửa hàng, người mới quen thì phải nói <span class='gd-jp'>飲みます</span>. Bài này chỉ luyện một việc: <b>cho bất kỳ động từ nào, bạn đều biết chuyển thành 〜ます</b>.</div><div class='gd-h'>Cách chuyển: trước tiên xem động từ thuộc nhóm nào</div><div class='gd-sec'><span class='gd-tag'>Bước 1</span><b>Tách nhóm 3 (する・来る) ra trước</b>, chỉ có hai từ, cứ học thuộc luôn:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ます</span>（きます）</span><br>「Danh từ＋する」cũng thuộc nhóm này:<span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強します</span></span></div><div class='gd-sec'><span class='gd-tag'>Bước 2</span><b>Những từ còn lại, xác định là nhóm 1 hay nhóm 2</b>:<br>・Chữ cuối <b>không phải る</b> (như <span class='gd-jp'>書く</span>、<span class='gd-jp'>飲む</span>、<span class='gd-jp'>会う</span>、<span class='gd-jp'>待つ</span>): chắc chắn là nhóm 1.<br>・Chữ cuối là る, và <b>âm đứng trước る kết thúc bằng a, u, o</b> (như chữ か của <span class='gd-jp'>分かる</span>, chữ く của <span class='gd-jp'>作る</span>, chữ の của <span class='gd-jp'>乗る</span>): chắc chắn là nhóm 1 (する、来る đã được tách ở bước 1 nên không tính ở đây).<br>・Chữ cuối là る, và <b>âm đứng trước る kết thúc bằng i, e</b> (như chữ み của <span class='gd-jp'>見る</span>, chữ べ của <span class='gd-jp'>食べる</span>, chữ き của <span class='gd-jp'>起きる</span>): phần lớn là nhóm 2. Nhưng có vài ngoại lệ thật ra thuộc nhóm 1, cần học thuộc: <span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>切る</span>.</div><div class='gd-sec'><b>Nhóm 1 (五段動詞)</b>: đổi âm cuối sang âm hàng「い」cùng hàng, rồi thêm ます.<br>Nhìn bảng 50 âm, từ cột う lùi một ô sang cột い là đúng (bảng dọc thì lên một ô, bảng ngang thì sang trái một ô): う→い、く→き、ぐ→ぎ、す→し、つ→ち、ぬ→に、ぶ→び、む→み、る→り.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành き → <span class='gd-jp'>書きます</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲みます</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会います</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待ちます</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話します</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳ぎます</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊びます</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰ります</span></span></div><div class='gd-sec'><b>Nhóm 2 (一段動詞)</b>: bỏ「る」ở cuối, thêm ます.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ます</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きます</span></span><span class='gd-pair'><span class='gd-jp'>着る</span> → <span class='gd-jp'>着ます</span></span></div><div class='gd-h'>Dạng bạn hay nghe nhất</div><div class='gd-sec'>Thói quen hằng ngày hay việc sẽ làm ngày mai đều dùng cùng một ます形.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝パンを食べます。</span>（Sáng nào tôi cũng ăn bánh mì）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日、日本語を勉強します。</span>（Ngày nào tôi cũng học tiếng Nhật）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、友達が家に来ます。</span>（Ngày mai bạn tôi sẽ đến nhà tôi）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Không được thêm ます thẳng vào dạng từ điển: <span class='gd-jp'>飲むます</span>、<span class='gd-jp'>行くます</span> đều sai, phải đổi âm cuối trước.<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>切る</span> trông giống nhóm 2 nhưng thật ra là nhóm 1: phải là <span class='gd-jp'>帰ります</span>, không phải 帰ます.<br>・<span class='gd-jp'>来ます</span> đọc là <b>きます</b>, không phải くます, cũng không phải 来ります; <span class='gd-jp'>する</span> cũng không biến thành すります.<br>・Chữ「す」trong「ます」thường đọc rất nhẹ, nghe giống “mas”. Đó là cách phát âm bình thường, bạn không nghe nhầm đâu.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Phần còn lại sau khi bỏ ます (<span class='gd-jp'>飲み</span>、<span class='gd-jp'>食べ</span>、<span class='gd-jp'>し</span>) sẽ được dùng mãi về sau, chỉ cần đổi đuôi là thành mẫu câu mới:<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みました</span></span>（đã uống）<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みましょう</span></span>（cùng uống nào）<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みたいです</span></span>（tôi muốn uống）</div>","n5-42":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể て là <b>「đầu nối」</b> của động từ, giống cái chốt nhô lên trên mảnh Lego để gắn thêm mảnh khác vào. Tiếng Việt nói \"dậy, <b>rồi</b> rửa mặt\", còn tiếng Nhật thì đổi 「起きる」 thành thể て rồi nối tiếp hành động sau. Nhiều mẫu câu quan trọng cũng phải chuyển động từ sang thể て mới nối được, ví dụ 「xin hãy ～」 và 「đang ～」, nên thể này được gọi là <b>biến đổi quan trọng nhất</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nối hành động</span>Nối nhiều hành động lại với nhau theo thứ tự.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝起きて、顔を洗います。</span>(Buổi sáng thức dậy, rồi rửa mặt)</div><div class='gd-sec'><span class='gd-tag'>Nối vào mẫu câu</span>Nối thêm từ khác phía sau để tạo nghĩa mới.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>(Xin hãy viết tên vào đây)</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べています。</span>(Bây giờ tôi đang ăn cơm)</div><div class='gd-sec'><span class='gd-tag'>Nhờ vả bạn bè</span>Khi nói chuyện với bạn bè, chỉ cần nói thể て là thành lời nhờ thân mật kiểu 「～ giúp mình một chút nhé」.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと待って。</span>(Đợi một chút)</div><div class='gd-h'>Cách chia: trước tiên xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Nhóm 2 (động từ một đoạn)</b>: đơn giản nhất, bỏ 「る」 rồi thêm 「て」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見て</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きて</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span>（きて）</span><br>Dạng 「danh từ + する」 như <span class='gd-jp'>勉強する</span> cũng chia giống vậy: <span class='gd-pair'><span class='gd-jp'>勉強する</span> → <span class='gd-jp'>勉強して</span></span></div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: xem <b>chữ cuối cùng</b> là gì, chia thành năm nhóm.<br><b>う・つ・る → って</b><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買って</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰って</span></span><br><b>む・ぶ・ぬ → んで</b> (chú ý là で có hai dấu chấm)<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んで</span></span><span class='gd-pair'><span class='gd-jp'>死ぬ</span> → <span class='gd-jp'>死んで</span></span><br><b>く → いて</b><br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span></span><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いて</span></span><br><b>ぐ → いで</b><br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いで</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いで</span></span><br><b>す → して</b><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話して</span></span><span class='gd-pair'><span class='gd-jp'>貸す</span> → <span class='gd-jp'>貸して</span></span><br><b>Ngoại lệ duy nhất</b>: <span class='gd-jp'>行く</span> theo quy tắc lẽ ra là 「行いて」, nhưng thực tế là <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span>.</div><div class='gd-sec'>Câu vần nhỏ, đọc nhiều cho thuộc: <b>うつる って、むぶぬ んで、く いて、ぐ いで、す して, 行く là 行って</b>.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>知る</span> trông giống nhóm 2 nhưng thật ra là nhóm 1: phải là <span class='gd-jp'>帰って</span>, không phải 帰て.<br>・<span class='gd-jp'>行って</span> là ngoại lệ, nhưng các từ kết thúc bằng く như <span class='gd-jp'>書いて</span>, <span class='gd-jp'>聞いて</span> vẫn theo quy tắc, đừng đổi hết thành って.<br>・ぐ phải đổi thành <b>いで</b>, む・ぶ・ぬ phải đổi thành <b>んで</b>. Nhiều bạn hay viết sai thành 泳いて, 飲んて, đừng quên dấu đục (hai dấu chấm).<br>・「っ」 nhỏ phải ngắt một nhịp: <span class='gd-jp'>来て</span> (きて, đến) và <span class='gd-jp'>切って</span> (きって, cắt) chỉ khác nhau đúng một nhịp này nhưng nghĩa hoàn toàn khác.<br>・<span class='gd-jp'>来て</span> đọc là <b>きて</b>, không phải こて hay くて.<br>・Bản thân thể て không có thì quá khứ hay hiện tại, phải nhìn <b>động từ cuối cùng</b> để quyết định: <span class='gd-jp'>シャワーを浴びて、寝ました。</span> (Tắm xong rồi đi ngủ)</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Quen thể て rồi thì <b>thể た (cách nói quá khứ thông thường) gần như được tặng kèm</b>: quy tắc hoàn toàn giống, chỉ cần đổi て thành た, で thành だ.<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><br>Sau đó bạn có thể học 「～てください」 (xin hãy ～), 「～ています」 (đang ～), 「～てから」 (sau khi ～). Tất cả đều dựa vào cách chia trong thẻ này.</div>","n5-43":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể từ điển là <b>phiên bản thân mật</b> của 「〜ます」, cũng là dạng bạn tra thấy trong từ điển; thể ない là <b>phiên bản thân mật</b> của 「〜ません」. Với thầy cô bạn nói <span class='gd-jp'>行きます</span>／<span class='gd-jp'>行きません</span>, với bạn bè thì nói <span class='gd-jp'>行く</span>／<span class='gd-jp'>行かない</span>. Nghĩa giống nhau, chỉ là suồng sã hơn.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Trò chuyện với bạn bè, người nhà</span>Giống thể ます, dùng cho thói quen hiện tại và việc chưa xảy ra. Khi hỏi, chỉ cần lên giọng ở cuối câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、何時に起きる？</span>(Ngày mai bạn dậy mấy giờ?)</div><div class='gd-ex-line'>・<span class='gd-jp'>7時に起きる。</span>(Mình dậy lúc 7 giờ)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は学校に行かない。</span>(Hôm nay mình không đến trường)</div><div class='gd-ex-line'>・<span class='gd-jp'>私はお酒を飲まない。</span>(Tôi không uống rượu)</div><div class='gd-h'>Cách chia: trước tiên xem động từ thuộc nhóm nào</div><div class='gd-sec'><b>Trước hết, từ thể ます đổi về thể từ điển</b><br><b>Nhóm 1 (động từ ngũ đoạn)</b>: âm đứng trước ます được đổi thành âm cùng hàng nhưng ở cột 「う」.<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → đổi み thành む → <span class='gd-jp'>飲む</span></span><span class='gd-pair'><span class='gd-jp'>書きます</span> → <span class='gd-jp'>書く</span></span><span class='gd-pair'><span class='gd-jp'>歌います</span> → <span class='gd-jp'>歌う</span></span><span class='gd-pair'><span class='gd-jp'>帰ります</span> → <span class='gd-jp'>帰る</span></span><br><b>Nhóm 2 (động từ một đoạn)</b>: đổi ます thành る.<br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べる</span></span><span class='gd-pair'><span class='gd-jp'>起きます</span> → <span class='gd-jp'>起きる</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見る</span></span><br><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>する</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来る</span>（くる）</span></div><div class='gd-sec'><b>Tiếp theo, từ thể từ điển đổi sang thể ない</b><br><b>Nhóm 1 (động từ ngũ đoạn)</b>: đổi âm cuối thành âm cùng hàng nhưng ở cột 「あ」, rồi thêm ない.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → đổi く thành か → <span class='gd-jp'>書かない</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たない</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らない</span></span><br>Nếu âm cuối là 「う」 thì <b>đổi thành 「わ」</b>, không phải 「あ」:<br><span class='gd-pair'><span class='gd-jp'>買う</span> → đổi う thành わ → <span class='gd-jp'>買わない</span></span><span class='gd-pair'><span class='gd-jp'>歌う</span> → <span class='gd-jp'>歌わない</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span><br><b>Nhóm 2 (động từ một đoạn)</b>: bỏ る rồi thêm ない.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きない</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ない</span></span><br><b>Nhóm 3 (học thuộc luôn)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない）</span><br>Dạng 「danh từ + する」 cũng chia giống vậy: <span class='gd-pair'><span class='gd-jp'>電話する</span> → <span class='gd-jp'>電話しない</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Động từ kết thúc bằng 「う」 không được chia thành 「あない」: phải là <span class='gd-jp'>買わない</span>, không phải 買あない.<br>・<span class='gd-jp'>帰る</span>, <span class='gd-jp'>入る</span>, <span class='gd-jp'>走る</span>, <span class='gd-jp'>知る</span> trông giống nhóm 2 nhưng thật ra là nhóm 1: phải là <span class='gd-jp'>帰らない</span>, không phải 帰ない.<br>・来る có ba cách đọc cần phân biệt rõ: <span class='gd-jp'>来る</span> đọc là くる, <span class='gd-jp'>来ます</span> đọc là きます, <span class='gd-jp'>来ない</span> đọc là こない.<br>・Phủ định của <span class='gd-jp'>ある</span> (có, ở) là <span class='gd-jp'>ない</span>, không phải あらない: <span class='gd-jp'>お金がない。</span> (Không có tiền)<br>・Thể ない nghĩa là \"không (làm)\", không phải \"không thể\": <span class='gd-jp'>食べない</span> là \"tôi không ăn\", không phải \"tôi không ăn được\".</div><div class='gd-h'>Phân biệt với những dạng dễ lẫn</div><div class='gd-sec'>Cùng một câu \"ngày mai tôi không đến\", cách nói tùy vào bạn đang nói với ai:<br>Với thầy cô, cấp trên: <span class='gd-jp'>明日は来ません。</span><br>Với bạn bè, người nhà: <span class='gd-jp'>明日は来ない。</span><br>Nghĩa hoàn toàn giống nhau, khác ở mức độ lịch sự. Dùng <span class='gd-jp'>来ない</span> với bề trên sẽ bị coi là thiếu tôn trọng; còn cứ dùng <span class='gd-jp'>来ません</span> với bạn thân thì nghe rất xa cách. Giống như tiếng Việt thêm \"ạ\" hay nói trống không vậy.</div><div class='gd-warn'>Mẹo nhỏ để chọn: <span class='gd-jp'>ます</span> đi với thể từ điển, <span class='gd-jp'>ません</span> đi với thể ない. Hãy nghĩ xem đối phương là ai trước, rồi mới chọn nhóm dạng nào.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Sau thể từ điển và thể ない còn nối được nhiều mẫu ngữ pháp, ví dụ nhờ người khác đừng làm gì: <span class='gd-jp'>ここで写真を撮らないでください。</span> (Xin đừng chụp ảnh ở đây). Bước tiếp theo bạn có thể học cách nói quá khứ: <span class='gd-jp'>行った</span>／<span class='gd-jp'>行かなかった</span>.</div>","n5-44":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể た là <b>phiên bản thân mật</b> của「〜ました」, còn thể なかった là <b>phiên bản thân mật</b> của「〜ませんでした」. Nói với thầy cô thì dùng「<span class='gd-jp'>昨日、映画を見ました</span>」, nói với bạn bè thì dùng「<span class='gd-jp'>昨日、映画を見た</span>」. Cả hai đều có nghĩa là「Hôm qua mình đã xem phim」, chỉ là câu sau nhẹ nhàng, thoải mái hơn.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nói chuyện quá khứ với người quen</span>Dùng giữa bạn bè, người nhà khi kể chuyện đã xảy ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、渋谷で友達に会った。</span>（Hôm qua mình gặp bạn ở Shibuya）</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は何も食べなかった。</span>（Sáng nay mình không ăn gì cả）</div><div class='gd-sec'><span class='gd-tag'>Tự nói với mình, viết nhật ký</span>Dùng khi không có ai cần phải giữ lịch sự.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、傘を忘れた。</span>（A, mình quên mang ô rồi）</div><div class='gd-sec'><span class='gd-tag'>Nối với mẫu ngữ pháp khác</span>Rất nhiều mẫu ngữ pháp phía sau phải chia sang thể た rồi mới nối được, nên bạn nhất định phải nắm chắc phần này.</div><div class='gd-h'>Cách chia thể た: xem động từ thuộc nhóm nào trước</div><div class='gd-sec'><b>Nếu đã biết thể て thì dễ nhất</b>: đổi「て」của thể て thành「た」, đổi「で」thành「だ」là xong.<br><span class='gd-pair'><span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べた</span></span></div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b>: nhìn âm cuối rồi chia theo bảng dưới đây.<br>Kết thúc bằng う・つ・る → った：<span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待った</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰った</span></span><br>Kết thúc bằng ぬ・む・ぶ → んだ：<span class='gd-pair'><span class='gd-jp'>死ぬ</span> → <span class='gd-jp'>死んだ</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>遊ぶ</span> → <span class='gd-jp'>遊んだ</span></span><br>Kết thúc bằng く → いた：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><br>Kết thúc bằng ぐ → いだ：<span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いだ</span></span><br>Kết thúc bằng す → した：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話した</span></span><br>Ngoại lệ duy nhất：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span>（tuy kết thúc bằng く nhưng không phải 行いた）</div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: bỏ「る」ở cuối rồi thêm「た」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きた</span></span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span></div><div class='gd-h'>Cách chia thể なかった</div><div class='gd-sec'>Chia sang thể ない trước, rồi đổi「ない」thành「なかった」. Cả ba nhóm đều dùng chung một cách.<br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まない</span> → <span class='gd-jp'>飲まなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span> → <span class='gd-jp'>会わなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span> → <span class='gd-jp'>しなかった</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない） → <span class='gd-jp'>来なかった</span>（こなかった）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はどこにも行かなかった。</span>（Hôm qua mình không đi đâu cả）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Thể た của <span class='gd-jp'>行く</span> là <span class='gd-jp'>行った</span>, không phải 行いた.<br>・<span class='gd-jp'>帰る</span>、<span class='gd-jp'>走る</span>、<span class='gd-jp'>入る</span>、<span class='gd-jp'>知る</span> trông giống nhóm 2 nhưng thực ra là nhóm 1: phải là <span class='gd-jp'>帰った</span>、<span class='gd-jp'>走った</span>, không phải 帰た、走た.<br>・<span class='gd-jp'>来た</span> đọc là <b>きた</b>, còn <span class='gd-jp'>来なかった</span> đọc là <b>こなかった</b>, cùng một chữ nhưng cách đọc khác nhau.<br>・Phủ định của <span class='gd-jp'>ある</span> là <span class='gd-jp'>ない</span> luôn (không có「あらない」), quá khứ là <span class='gd-jp'>なかった</span>：<span class='gd-jp'>時間がなかった。</span>（Lúc đó không có thời gian）<br>・「Chưa ăn」trong tiếng Việt không phải là <span class='gd-jp'>食べなかった</span>. なかった nói về「lúc đó đã không làm」, chuyện đã qua rồi; còn「đến giờ vẫn chưa làm」thì phải nói <span class='gd-jp'>まだ食べていない</span>.<br>・Thể た và thể なかった là cách nói giữa bạn bè. Khi kể chuyện quá khứ với người lớn tuổi, cuối câu luôn dùng「〜ました」hoặc「〜ませんでした」.</div><div class='gd-h'>Phân biệt với những mẫu dễ lẫn</div><div class='gd-sec'><b>Thể た vs ました</b>: nghĩa hoàn toàn giống nhau, khác ở chỗ bạn nói với ai.<br><span class='gd-jp'>昨日、映画を見ました。</span>（Nói với thầy cô: hôm qua em đã xem phim）<br><span class='gd-jp'>昨日、映画を見た。</span>（Nói với bạn bè: hôm qua mình đã xem phim）<br>Phủ định cũng vậy: <span class='gd-jp'>行きませんでした</span> và <span class='gd-jp'>行かなかった</span> đều là「đã không đi」, câu đầu lịch sự, câu sau thoải mái hơn.</div><div class='gd-sec'><b>た vs て</b>: chỉ khác một âm nhưng chức năng hoàn toàn khác. 「た」là kết thúc câu, cho biết việc đã làm xong; 「て」là câu còn tiếp, phía sau còn nối thêm, hoặc dùng để nhờ vả.<br><span class='gd-jp'>ご飯を食べた。</span>（Mình ăn cơm rồi）<br><span class='gd-jp'>ご飯を食べて、すぐ寝た。</span>（Ăn cơm xong là đi ngủ ngay）</div><div class='gd-warn'>Mẹo nhỏ để chọn: câu kết thúc ở đây và việc đã xảy ra → た; phía sau còn nói tiếp → て; nói với người lớn tuổi, khách → đổi lại thành ました、ませんでした.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm「り」sau thể た sẽ thành「〜たり〜たりします」(lúc làm việc này, lúc làm việc kia)：<span class='gd-jp'>週末は映画を見たり、買い物をしたりします。</span>（Cuối tuần mình lúc thì xem phim, lúc thì đi mua sắm）<br>Thể た thêm「あとで」＝ sau khi làm xong ～：<span class='gd-jp'>ご飯を食べたあとで、散歩します。</span>（Sau khi ăn cơm xong, mình đi dạo）</div>","n5-45":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thể thông thường chính là <b>cách nói thân mật</b> khi bỏ「です・ます」đi, cũng là dạng cơ bản mà rất nhiều mẫu câu đứng sau yêu cầu. Mỗi từ có bốn dạng, giống như tiếng Việt「đi / không đi / đã đi / đã không đi」: <b>khẳng định hiện tại, phủ định hiện tại, khẳng định quá khứ, phủ định quá khứ</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Nói chuyện với người quen</span>Giữa người nhà, bạn bè không dùng ます mà nói thẳng thể thông thường.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日、映画を見た。</span>（Hôm qua mình đã xem phim）</div><div class='gd-sec'><span class='gd-tag'>Nối với mẫu câu</span>Dù cả câu rất lịch sự, phần giữa câu vẫn thường phải đổi sang thể thông thường rồi mới nối với mẫu câu phía sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は雨が降ると思います。</span>（Tôi nghĩ ngày mai trời sẽ mưa）</div><div class='gd-h'>Cách chia: xem động từ thuộc nhóm nào trước</div><div class='gd-sec'><b>Nhóm 1 (động từ ngũ đoạn)</b><br>Phủ định: đổi âm cuối sang âm hàng「あ」cùng hàng, rồi thêm ない。<span class='gd-pair'><span class='gd-jp'>行く</span> → đổi く thành か → <span class='gd-jp'>行かない</span></span><br>Quá khứ: chia giống thể て, chỉ là đổi て thành た。<span class='gd-pair'><span class='gd-jp'>行って</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>飲んで</span> → <span class='gd-jp'>飲んだ</span></span><br>Phủ định quá khứ: đổi「い」của ない thành「かった」。<span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなかった</span></span><br>Xem trọn bộ một lần：<span class='gd-jp'>買う／買わない／買った／買わなかった</span></div><div class='gd-sec'><b>Nhóm 2 (động từ nhất đoạn)</b>: đơn giản nhất, bỏ「る」rồi thêm ない、た、なかった.<br><span class='gd-jp'>食べる／食べない／食べた／食べなかった</span><br><span class='gd-jp'>見る／見ない／見た／見なかった</span></div><div class='gd-sec'><b>Nhóm 3 (chỉ có hai từ, học thuộc luôn)</b><br><span class='gd-jp'>する／しない／した／しなかった</span><br><span class='gd-jp'>来る／来ない／来た／来なかった</span>（くる／こない／きた／こなかった）<br>Những từ dạng「danh từ＋する」như <span class='gd-jp'>勉強する</span> thì chia theo する：<span class='gd-jp'>勉強しない</span>、<span class='gd-jp'>勉強した</span>、<span class='gd-jp'>勉強しなかった</span>。</div><div class='gd-h'>Tính từ và danh từ chia thế nào</div><div class='gd-sec'><b>Tính từ đuôi い</b>: phủ định thì đổi い cuối thành くない, quá khứ thì đổi い thành かった.<br><span class='gd-jp'>高い／高くない／高かった／高くなかった</span></div><div class='gd-sec'><b>Tính từ đuôi な</b>: phía sau thêm だ、じゃない、だった、じゃなかった.<br><span class='gd-jp'>静かだ／静かじゃない／静かだった／静かじゃなかった</span></div><div class='gd-sec'><b>Danh từ</b>: chia giống hệt tính từ đuôi な.<br><span class='gd-jp'>学生だ／学生じゃない／学生だった／学生じゃなかった</span></div><div class='gd-warn'>Phát hiện nhỏ: dù là động từ, tính từ hay danh từ, phủ định cuối cùng đều là「ない」, và đều dùng cùng một cách để chuyển sang quá khứ：<span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なかった</span></span>. Nhớ mẹo này thì dạng thứ tư (phủ định quá khứ) gần như không cần học riêng.</div><div class='gd-h'>Đối chiếu với ます・です để nhớ</div><div class='gd-sec'><span class='gd-pair'><span class='gd-jp'>行きます</span> → <span class='gd-jp'>行く</span></span><span class='gd-pair'><span class='gd-jp'>行きません</span> → <span class='gd-jp'>行かない</span></span><br><span class='gd-pair'><span class='gd-jp'>行きました</span> → <span class='gd-jp'>行った</span></span><span class='gd-pair'><span class='gd-jp'>行きませんでした</span> → <span class='gd-jp'>行かなかった</span></span><br>Tính từ đuôi い là dễ nhất, chỉ cần bỏ です：<span class='gd-pair'><span class='gd-jp'>高かったです</span> → <span class='gd-jp'>高かった</span></span><br>Tính từ đuôi な và danh từ thì đổi です thành だ：<span class='gd-pair'><span class='gd-jp'>学生です</span> → <span class='gd-jp'>学生だ</span></span></div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Động từ nhóm 1 kết thúc bằng う thì phủ định phải đổi thành「わ」：<span class='gd-jp'>買わない</span>, không phải 買あない.<br>・Phủ định của <span class='gd-jp'>ある</span> là <span class='gd-jp'>ない</span>, không phải あらない.<br>・Quá khứ của <span class='gd-jp'>行く</span> là <span class='gd-jp'>行った</span>, không phải 行いた.<br>・<span class='gd-jp'>いい</span> hễ biến đổi là phải chuyển sang dạng bắt đầu bằng よ：<span class='gd-jp'>よくない</span>、<span class='gd-jp'>よかった</span>、<span class='gd-jp'>よくなかった</span>。<br>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span> trông giống tính từ đuôi い nhưng thực ra là tính từ đuôi な: phải nói <span class='gd-jp'>きれいじゃない</span>, không phải きれくない.<br>・Sau tính từ đuôi い không thêm だ được: chỉ cần nói <span class='gd-jp'>高い</span>, đừng nói 高いだ.<br>・Danh từ, tính từ đuôi な kết thúc thẳng bằng「だ」nghe hơi cứng. Khi nói chuyện với bạn bè, người ta hay bỏ だ hoặc thêm よ ở sau, ví dụ <span class='gd-jp'>学生だよ</span>.<br>・Khi hỏi bạn bè bằng thể thông thường, thường không thêm か, chỉ cần lên giọng ở cuối câu：<span class='gd-jp'>明日、来る？</span>（Mai bạn có đến không?）</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Khi nối thể thông thường với mẫu câu, bạn cần đặc biệt chú ý「だ」của danh từ và tính từ đuôi な: lúc thì giữ lại, lúc thì bỏ đi, lúc thì đổi thành な.<br><span class='gd-jp'>静かだと思う。</span>（Mình thấy nó yên tĩnh: giữ だ）<br><span class='gd-jp'>静かでしょう。</span>（Chắc là yên tĩnh nhỉ: bỏ だ）<br><span class='gd-jp'>学生なの？</span>（Bạn là sinh viên à?: đổi だ thành な）<br>Những điểm này sẽ được giải thích từng cái một trong các bài về「～でしょう」và danh từ hình thức「の」.</div>","n5-46":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt nói \"núi cao\", \"hoa đẹp\": tính từ đứng <b>sau</b> danh từ. Tiếng Nhật thì ngược lại, tính từ đứng <b>trước</b> danh từ. Có hai cách nối: <b>い形容詞 gắn thẳng vào trước danh từ</b>, còn <b>な形容詞 phải chèn thêm「な」ở giữa</b>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>い形容詞</b> (loại kết thúc bằng い): không cần đổi gì, đặt thẳng trước danh từ.<br><span class='gd-pair'><span class='gd-jp'>高い</span>＋<span class='gd-jp'>山</span> → <span class='gd-jp'>高い山</span></span>(ngọn núi cao)<br><span class='gd-pair'><span class='gd-jp'>新しい</span>＋<span class='gd-jp'>靴</span> → <span class='gd-jp'>新しい靴</span></span>(đôi giày mới)</div><div class='gd-sec'><b>な形容詞</b>: thêm「な」phía sau trước, rồi mới nối với danh từ.<br><span class='gd-pair'><span class='gd-jp'>きれい</span>＋な＋<span class='gd-jp'>花</span> → <span class='gd-jp'>きれいな花</span></span>(bông hoa đẹp)<br><span class='gd-pair'><span class='gd-jp'>静か</span>＋な＋<span class='gd-jp'>部屋</span> → <span class='gd-jp'>静かな部屋</span></span>(căn phòng yên tĩnh)</div><div class='gd-h'>Dạng hay gặp nhất</div><div class='gd-ex-line'>・<span class='gd-jp'>新しい靴を買いました。</span>(Mình đã mua một đôi giày mới.)</div><div class='gd-ex-line'>・<span class='gd-jp'>これはおいしいケーキですね。</span>(Đây là chiếc bánh ngon quá nhỉ.)</div><div class='gd-ex-line'>・<span class='gd-jp'>静かな部屋がいいです。</span>(Mình muốn một căn phòng yên tĩnh.)</div><div class='gd-ex-line'>・<span class='gd-jp'>好きな食べ物は何ですか。</span>(Món ăn bạn thích là gì?)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>きらい</span> tuy đuôi là い nhưng thật ra là <b>な形容詞</b>. Phải nói <span class='gd-jp'>きれいな花</span>、<span class='gd-jp'>きらいな食べ物</span>, không được nói きれい花.<br>・Vì thấy giữa hai từ cần một từ nối nào đó, nhiều bạn hay nhét「の」vào giữa: 「高いの山」「静かの部屋」đều sai. い形容詞 không thêm gì, な形容詞 thêm「な」.<br>・\"Nhiều người\" không thể nói thẳng là「多い人」mà phải nói <span class='gd-jp'>たくさんの人</span>.<br>・Bạn có thể gặp <span class='gd-jp'>大きな家</span>、<span class='gd-jp'>小さな店</span>. Đây không phải viết sai, mà là cách nói riêng của <span class='gd-jp'>大きい</span>、<span class='gd-jp'>小さい</span>, chỉ dùng được trước danh từ. <span class='gd-jp'>大きい家</span> và <span class='gd-jp'>大きな家</span> đều đúng.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><span class='gd-tag'>Cuối câu vs trước danh từ</span>「な」của な形容詞 <b>chỉ xuất hiện khi phía sau là danh từ</b>. Đặt ở cuối câu thì nối thẳng với です.<br><span class='gd-jp'>この部屋は静かです。</span>(Căn phòng này rất yên tĩnh.)<br><span class='gd-jp'>静かな部屋です。</span>(Là một căn phòng yên tĩnh.)<br>Không thể nói「この部屋は静かなです」.</div><div class='gd-sec'><span class='gd-tag'>Danh từ＋の</span>Nếu từ đứng trước là <b>danh từ</b> thì ở giữa dùng「の」, không phải「な」.<br><span class='gd-jp'>日本の車</span>(xe của Nhật: danh từ＋の)<br><span class='gd-jp'>新しい車</span>(xe mới: い形容詞 nối thẳng)<br><span class='gd-jp'>きれいな車</span>(xe đẹp: な形容詞＋な)</div><div class='gd-warn'>Mẹo nhỏ: tự hỏi từ đứng trước là loại gì. い形容詞 thì gắn thẳng, な形容詞 thì chèn な, danh từ thì chèn の.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tính từ cũng có thể bổ nghĩa cho động từ, ví dụ <span class='gd-jp'>早く起きます</span> (dậy sớm). Đây là \"cách dùng trạng từ của tính từ\".</div>","n5-47":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt muốn nói một hành động được làm \"như thế nào\" thì đặt tính từ sau động từ: \"dậy sớm\", \"dọn sạch sẽ\". Tiếng Nhật thì chỉ cần <b>đổi phần đuôi</b> của tính từ rồi đặt <b>trước</b> động từ, để cho biết hành động đó được làm như thế nào.</div><div class='gd-h'>Cách biến đổi: xem tính từ thuộc loại nào</div><div class='gd-sec'><b>い形容詞 (tính từ kết thúc bằng「い」)</b>: đổi「い」cuối thành「く」.<br><span class='gd-pair'><span class='gd-jp'>早い</span> → đổi い thành く → <span class='gd-jp'>早く</span></span><br><span class='gd-pair'><span class='gd-jp'>大きい</span> → <span class='gd-jp'>大きく</span></span><span class='gd-pair'><span class='gd-jp'>楽しい</span> → <span class='gd-jp'>楽しく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>明日は早く起きます。</span>(Ngày mai mình sẽ dậy sớm.)</div><div class='gd-ex-line'>・<span class='gd-jp'>名前を大きく書いてください。</span>(Hãy viết tên to lên một chút.)</div><div class='gd-sec'><b>な形容詞 (tính từ phải thêm「な」khi nối với danh từ)</b>: thêm「に」trực tiếp.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → thêm に → <span class='gd-jp'>静かに</span></span><br><span class='gd-pair'><span class='gd-jp'>きれい</span> → <span class='gd-jp'>きれいに</span></span><span class='gd-pair'><span class='gd-jp'>上手</span> → <span class='gd-jp'>上手に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>部屋をきれいに掃除しました。</span>(Mình đã dọn phòng sạch sẽ.)</div><div class='gd-ex-line'>・<span class='gd-jp'>図書館では静かに話してください。</span>(Ở thư viện hãy nói nhỏ thôi.)</div><div class='gd-sec'><b>Ngoại lệ phải nhớ</b>: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よく</span></span>, không phải いく. Những từ kết thúc bằng いい cũng vậy, ví dụ <span class='gd-pair'><span class='gd-jp'>かっこいい</span> → <span class='gd-jp'>かっこよく</span></span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はよく寝ました。</span>(Hôm qua mình ngủ rất ngon.)</div><div class='gd-ex-line'>・<span class='gd-jp'>かっこよく踊りたいです。</span>(Mình muốn nhảy thật ngầu.)</div><div class='gd-h'>Thứ tự ngược với tiếng Việt</div><div class='gd-sec'>Tiếng Việt hay nói \"nhảy giỏi\", \"viết đẹp\": phần miêu tả đứng <b>sau</b> động từ. Tiếng Nhật thì ngược lại, <b>nói trước là làm như thế nào, rồi mới đến hành động</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは上手に踊ります。</span>(Anh Tanaka nhảy rất giỏi.)</div><div class='gd-ex-line'>・<span class='gd-jp'>字をきれいに書きます。</span>(Viết chữ thật đẹp.)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>きれい</span>、<span class='gd-jp'>有名</span> tuy kết thúc có い nhưng thật ra là な形容詞: phải nói <span class='gd-jp'>きれいに</span>, không phải きれく.<br>・Không được đặt nguyên dạng của tính từ trước động từ: không nói 早い起きます mà phải nói <span class='gd-jp'>早く起きます</span>; không nói 静かな話します mà phải nói <span class='gd-jp'>静かに話します</span>.<br>・<span class='gd-jp'>よく</span> ngoài nghĩa \"một cách tốt, kỹ\" còn rất hay dùng với nghĩa \"thường xuyên\": <span class='gd-jp'>よく行きます</span> là \"hay đi\". Cần dựa vào ngữ cảnh để phân biệt.<br>・<span class='gd-jp'>早く</span> và <span class='gd-jp'>速く</span> đều đọc là はやく, nhưng「早く」là sớm về thời gian, còn「速く」là nhanh về tốc độ: <span class='gd-jp'>早く起きます</span> (dậy sớm), <span class='gd-jp'>速く走ります</span> (chạy nhanh).</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>Tính từ bổ nghĩa cho danh từ</b> ở bài trước rất dễ lẫn với bài này. Chỉ cần xem <b>phía sau là gì</b>:<br>Sau là danh từ (người, vật): い形容詞 giữ nguyên, な形容詞 thêm「な」.<br>Sau là động từ (hành động): い形容詞 đổi thành「く」, な形容詞 thêm「に」.</div><div class='gd-ex-line'>・<span class='gd-jp'>静かな人です。</span>(Là một người trầm lặng.)</div><div class='gd-ex-line'>・<span class='gd-jp'>静かに話します。</span>(Nói nhỏ nhẹ.)</div><div class='gd-ex-line'>・<span class='gd-jp'>早い電車に乗ります。</span>(Đi chuyến tàu sớm hơn.)</div><div class='gd-ex-line'>・<span class='gd-jp'>早く来てください。</span>(Hãy đến sớm nhé.)</div><div class='gd-warn'>Mẹo nhỏ: phía sau là \"vật\" thì dùng「〜い／〜な」, phía sau là \"hành động\" thì dùng「〜く／〜に」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Cũng là く／に đó, nếu phía sau là <span class='gd-jp'>なります</span> thì nghĩa là \"trở nên ～\", còn <span class='gd-jp'>します</span> là \"làm cho nó thành ～\": <span class='gd-jp'>寒くなりました。</span> (Trời lạnh rồi.), <span class='gd-jp'>静かにしてください。</span> (Hãy giữ yên lặng.)</div>","n5-48":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt nói「quyển sách <b>mượn tuần trước</b>」「ngôi trường <b>em trai đang học</b>」, tức là đặt cả một đoạn <b>sau</b> danh từ để chỉ rõ là cái nào. Tiếng Nhật thì đặt đoạn đó <b>trước danh từ</b>, nên thứ tự ngược với tiếng Việt, và ở giữa cũng <b>không cần từ nối</b> như「mà」「đang」. <br><span class='gd-jp'>先週借りた本</span>（quyển sách mượn tuần trước）</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Đoạn bổ nghĩa cho danh từ phải dùng <b>thể thường</b>, tức là kiểu nói giữa bạn bè, không có ます và です, rồi gắn thẳng vào trước danh từ.<br><span class='gd-pair'><span class='gd-jp'>本を借りました</span> → <span class='gd-jp'>借りた</span></span> → <span class='gd-jp'>先週借りた本</span></div><div class='gd-sec'><span class='gd-tag'>Động từ</span>Dùng dạng nào thì nghĩa đổi theo dạng đó:<br><span class='gd-jp'>見る映画</span>（bộ phim sắp xem）<br><span class='gd-jp'>見ない映画</span>（bộ phim không xem）<br><span class='gd-jp'>見た映画</span>（bộ phim đã xem）<br><span class='gd-jp'>見なかった映画</span>（bộ phim đã không xem）<br><span class='gd-jp'>見ている映画</span>（bộ phim đang xem）</div><div class='gd-sec'><span class='gd-tag'>Kết thúc bằng tính từ い</span>Nối thẳng.<br><span class='gd-jp'>髪が長い人</span>（người tóc dài）</div><div class='gd-sec'><span class='gd-tag'>Kết thúc bằng tính từ な</span>Ở thể khẳng định hiện tại, だ phải đổi thành <b>な</b>.<br><span class='gd-pair'><span class='gd-jp'>交通が便利だ</span> → <span class='gd-jp'>交通が便利な町</span></span>（thị trấn giao thông thuận tiện）<br>Không phải「便利だ町」.</div><div class='gd-sec'><span class='gd-tag'>Kết thúc bằng danh từ</span>Ở thể khẳng định hiện tại, だ phải đổi thành <b>の</b>, không phải な.<br><span class='gd-pair'><span class='gd-jp'>母が日本人だ</span> → <span class='gd-jp'>母が日本人の友達</span></span>（người bạn có mẹ là người Nhật）<br>Không phải「日本人だ友達」, cũng không phải「日本人な友達」.</div><div class='gd-sec'>Khi ở quá khứ hoặc phủ định thì không cần đổi, cứ nối thẳng:<br><span class='gd-jp'>静かじゃない部屋</span>（căn phòng không yên tĩnh）<br><span class='gd-jp'>昔、先生だった人</span>（người trước đây từng là giáo viên）</div><div class='gd-h'>Dạng bạn hay gặp nhất</div><div class='gd-sec'>Cả cụm「danh từ + phần bổ nghĩa」có thể coi là một danh từ lớn để đặt vào câu. Muốn nói lịch sự, <b>chỉ cần cuối câu dùng です・ます</b>, phần phía trước cứ để thể thường.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは母が作ったケーキです。</span>（Đây là chiếc bánh mẹ tôi làm）</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日見た映画はおもしろかったです。</span>（Bộ phim xem hôm qua rất hay）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本で行きたい所はどこですか。</span>（Ở Nhật bạn muốn đi nơi nào?）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の近くにある店で会いましょう。</span>（Mình gặp nhau ở quán gần ga nhé）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Vì tiếng Việt có từ nối như「mà」「của」nên bạn dễ muốn chèn の vào:「借りたの本」là sai, phải nói <span class='gd-jp'>借りた本</span>.<br>・Bên trong đoạn bổ nghĩa đừng dùng ます:「買いました本」là sai, phải nói <span class='gd-jp'>買った本</span>. Phần lịch sự cứ giao cho です・ます ở cuối câu.<br>・Trong đoạn đó, người thực hiện hành động phải dùng <b>が</b>, không dùng は:「私は作った料理」là sai, phải nói <span class='gd-jp'>私が作った料理</span>（món tôi nấu）. Bạn cũng có thể gặp <span class='gd-jp'>私の作った料理</span>, が đổi thành の, nghĩa vẫn y như vậy.<br>・Tính từ な đổi thành <b>な</b>（<span class='gd-jp'>静かな部屋</span>）, danh từ đổi thành <b>の</b>（<span class='gd-jp'>医者の父</span>, bố là bác sĩ）, đừng trộn lẫn hai cái.<br>・<span class='gd-jp'>見た映画</span> là「đã xem」, còn <span class='gd-jp'>見る映画</span> là「sẽ xem, thường xem」, nên chọn đúng thời điểm.</div><div class='gd-h'>Phân biệt với dạng trông rất giống</div><div class='gd-sec'>Cùng nói về quyển sách, từ đứng trước sẽ quyết định có thêm の hay không:<br><span class='gd-jp'>私の本</span>（sách của tôi）: phía trước là danh từ, phải thêm の<br><span class='gd-jp'>私が買った本</span>（sách tôi mua）: phía trước là động từ, nối thẳng<br><span class='gd-jp'>新しい本</span>（quyển sách mới）: phía trước là tính từ い, nối thẳng</div><div class='gd-warn'>Mẹo nhỏ: nhìn từ đứng sát ngay trước danh từ. Nếu là danh từ thì thêm の; nếu là động từ hoặc tính từ い thì nối thẳng, đừng bận tâm đến「mà」「của」trong tiếng Việt.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>「〜とき」（～lúc, khi ～）dùng đúng cùng cách nối này: <span class='gd-jp'>日本へ行くとき</span>（khi đi Nhật）、<span class='gd-jp'>子どものとき</span>（hồi nhỏ）.</div>","n5-49":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「の」có thể <b>gói một hành động thành「một việc」</b>, giống như tiếng Việt nói「<b>việc</b> chụp ảnh」. Tiếng Việt có thể nói thẳng「Tôi thích bơi」, dùng động từ luôn; tiếng Nhật thì không được, sau động từ phải thêm「の」trước, thành「việc bơi」, rồi mới nối được với <span class='gd-jp'>は</span>、<span class='gd-jp'>が</span>、<span class='gd-jp'>を</span>.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Động từ dùng <b>thể thường</b> (tức dạng từ điển, ví dụ <span class='gd-jp'>泳ぐ</span>、<span class='gd-jp'>撮る</span>; không phải dạng bỏ ます như <span class='gd-jp'>泳ぎ</span>、<span class='gd-jp'>撮り</span>), rồi thêm thẳng「の」.<br><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳ぐの</span></span>（việc bơi）<br><span class='gd-pair'><span class='gd-jp'>写真を撮る</span> → <span class='gd-jp'>写真を撮るの</span></span>（việc chụp ảnh）<br>Muốn nói「việc không làm gì đó」thì dùng thể ない rồi thêm の:<span class='gd-pair'><span class='gd-jp'>食べない</span> → <span class='gd-jp'>食べないの</span></span>（việc không ăn）</div><div class='gd-h'>Dạng bạn hay gặp nhất</div><div class='gd-sec'><span class='gd-tag'>のが好き・上手</span>Nói thích hay không thích, giỏi hay không giỏi làm việc gì đó. Khi phía sau là <span class='gd-jp'>好き</span>、<span class='gd-jp'>嫌い</span>、<span class='gd-jp'>上手</span>、<span class='gd-jp'>下手</span> thì dùng「が」.</div><div class='gd-ex-line'>・<span class='gd-jp'>小説を読むのが好きです。</span>（Tôi thích đọc tiểu thuyết）</div><div class='gd-ex-line'>・<span class='gd-jp'>母は料理を作るのが上手です。</span>（Mẹ tôi nấu ăn rất giỏi）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は歌うのが下手です。</span>（Tôi hát rất dở）</div><div class='gd-sec'><span class='gd-tag'>のは＋cảm nhận</span>Nói một việc trước, rồi nói bạn thấy việc đó thế nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>写真を撮るのは楽しいです。</span>（Chụp ảnh rất vui）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を話すのは難しいです。</span>（Nói tiếng Nhật rất khó）</div><div class='gd-ex-line'>・<span class='gd-jp'>朝ご飯を食べないのは体によくないです。</span>（Không ăn sáng không tốt cho cơ thể）</div><div class='gd-sec'><span class='gd-tag'>のを＋hành động</span>Coi「việc đó」là đối tượng của hành động.</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を出すのを忘れました。</span>（Tôi quên nộp bài tập）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんが来るのを待っています。</span>（Tôi đang đợi anh Tanaka đến）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Theo thói quen tiếng Việt mà đặt thẳng động từ vào:<span class='gd-jp'>泳ぐが好きです</span> là sai, phải nói <span class='gd-jp'>泳ぐのが好きです</span>.<br>・Trước の không được dùng thể ます: không thể nói「泳ぎますのが好きです」, phần lịch sự chỉ cần để ở <span class='gd-jp'>です</span> cuối câu.<br>・Từ vốn đã là danh từ thì không cần thêm の nữa: <span class='gd-jp'>音楽が好きです</span>（Tôi thích âm nhạc）, đừng nói thành「音楽のが好きです」.<br>・Trước <span class='gd-jp'>好き</span>、<span class='gd-jp'>上手</span> dùng「が」, đừng thấy tiếng Việt nói「thích <b>làm</b> ~」mà dùng thành「を」.<br>・Khác với「の」trong <span class='gd-jp'>私の本</span>（sách của tôi）: ở đó phía trước là danh từ, の mang nghĩa「của」; còn ở đây phía trước là động từ, の mang nghĩa「việc」.</div><div class='gd-h'>Phân biệt với dạng trông rất giống</div><div class='gd-sec'>「こと」cũng có thể biến hành động thành「một việc」, nhiều khi dùng cái nào cũng được:<br><span class='gd-jp'>本を読むのが好きです。</span>／<span class='gd-jp'>本を読むことが好きです。</span>（đều là「Tôi thích đọc sách」, こと nghe trang trọng hơn một chút）<br><br>Nhưng có chỗ chỉ dùng được một trong hai:<br><b>Cảnh tượng nhìn thấy, nghe thấy thì chỉ dùng の</b>:<span class='gd-jp'>田中さんが走っているのを見ました。</span>（Tôi thấy anh Tanaka đang chạy）<br><b>Cuối câu dạng「A là ~」thì dùng こと</b>:<span class='gd-jp'>私の趣味は写真を撮ることです。</span>（Sở thích của tôi là chụp ảnh）, không nói「撮るのです」.</div><div class='gd-warn'>Mẹo nhỏ: tận mắt thấy, tận tai nghe thì dùng の;「~ là làm việc gì đó」ở cuối câu thì dùng こと; khi nói thích hay nói vui hay không thì dùng cái nào cũng được, nhưng trong hội thoại hằng ngày の nghe tự nhiên nhất.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Khi đã quen với「こと」, bước tiếp theo là học <span class='gd-jp'>〜ことができる</span> = biết làm ~, có thể làm ~: <span class='gd-jp'>私は泳ぐことができます。</span>（Tôi biết bơi）</div>","n5-50":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt chỉ cần nói \"có\" cho mọi trường hợp: trên bàn có sách, trong phòng có mèo. Tiếng Nhật thì phải chia thêm một bước: <b>đồ vật, thực vật</b> dùng <span class='gd-jp'>あります</span>, còn <b>người và động vật</b> dùng <span class='gd-jp'>います</span>. Bạn chỉ cần xem vật đó có sống không, có tự di chuyển được không là biết dùng từ nào.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Địa điểm＋<span class='gd-jp'>に</span>＋đồ vật hoặc người＋<span class='gd-jp'>が</span>＋<span class='gd-jp'>あります</span>／<span class='gd-jp'>います</span><br><span class='gd-jp'>に</span> giống \"ở, tại\" trong tiếng Việt, dùng để chỉ địa điểm; <span class='gd-jp'>が</span> chỉ ra \"cái có là cái gì\".</div><div class='gd-ex-line'>・<span class='gd-jp'>引き出しにハサミがあります。</span>(Trong ngăn kéo có cái kéo)</div><div class='gd-ex-line'>・<span class='gd-jp'>教室に生徒がいます。</span>(Trong lớp có học sinh)</div><div class='gd-h'>あります hay います</div><div class='gd-sec'><span class='gd-tag'>あります</span>Đồ vật, thực vật, công trình kiến trúc. Cây tuy là vật sống nhưng không tự đi lại được, nên vẫn dùng <span class='gd-jp'>あります</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>机の上に本があります。</span>(Trên bàn có quyển sách)</div><div class='gd-ex-line'>・<span class='gd-jp'>庭に大きい木があります。</span>(Trong vườn có một cái cây lớn)</div><div class='gd-sec'><span class='gd-tag'>います</span>Người và động vật, cả cá và côn trùng cũng tính vào đây.</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋に猫がいます。</span>(Trong phòng có con mèo)</div><div class='gd-ex-line'>・<span class='gd-jp'>川に魚がいます。</span>(Dưới sông có cá)</div><div class='gd-h'>Dạng bạn sẽ nghe nhiều nhất</div><div class='gd-sec'><span class='gd-tag'>～ ở đâu</span>Muốn nói một vật \"ở\" đâu, bạn đưa vật đó lên trước và dùng <span class='gd-jp'>は</span>, địa điểm vẫn dùng <span class='gd-jp'>に</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ハサミは引き出しにあります。</span>(Cái kéo ở trong ngăn kéo)</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこにありますか。</span>(Nhà vệ sinh ở đâu vậy?)</div><div class='gd-sec'><span class='gd-tag'>Không có</span>Đổi ます thành ません: <span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>ありません</span></span><span class='gd-pair'><span class='gd-jp'>います</span> → <span class='gd-jp'>いません</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>教室に誰もいません。</span>(Trong lớp không có ai cả)</div><div class='gd-sec'><span class='gd-tag'>Tôi có ～</span>Với những kiểu \"có\" như người nhà hay thời gian, tiếng Nhật cũng thường dùng hai từ này.</div><div class='gd-ex-line'>・<span class='gd-jp'>姉が一人います。</span>(Tôi có một chị gái)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、時間がありますか。</span>(Ngày mai bạn có rảnh không?)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Người thì luôn dùng <span class='gd-jp'>います</span>: nói \"có thầy/cô giáo\" là <span class='gd-jp'>先生がいます</span>, nói thành 「先生があります」 là sai. Người nhà cũng vậy: <span class='gd-jp'>妹がいます</span>.<br>・Thực vật dùng <span class='gd-jp'>あります</span>; còn cá hay côn trùng dù nhỏ đến đâu, đã còn sống thì dùng <span class='gd-jp'>います</span>.<br>・Khi nói đồ vật, người, động vật \"ở đâu đó\", địa điểm dùng <span class='gd-jp'>に</span>: đúng là <span class='gd-jp'>部屋に猫がいます</span>, không phải 部屋で猫がいます.<br>・<b>Ngoại lệ</b>: nếu cái \"có\" là một hoạt động, sự kiện (<span class='gd-jp'>テスト</span>、<span class='gd-jp'>パーティー</span>、<span class='gd-jp'>会議</span>…), nghĩa là \"được tổ chức ở đó\", thì địa điểm dùng <span class='gd-jp'>で</span>: <span class='gd-jp'>あした学校でテストがあります。</span>(Ngày mai trường có bài kiểm tra)<br>・<span class='gd-jp'>何も</span> và <span class='gd-jp'>誰も</span> trong \"không có gì\", \"không có ai\" thì phía sau luôn đi với dạng phủ định <span class='gd-jp'>ありません</span>／<span class='gd-jp'>いません</span>.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng là ở công viên, hãy nhìn phía sau đi với gì:<br><b>Tồn tại</b> dùng <span class='gd-jp'>に</span>: <span class='gd-jp'>公園に犬がいます。</span>(Ở công viên có con chó)<br><b>Làm hành động</b> dùng <span class='gd-jp'>で</span>: <span class='gd-jp'>公園で犬と遊びます。</span>(Chơi với chó ở công viên)<br><b>Hoạt động được tổ chức</b> dùng <span class='gd-jp'>で</span>: <span class='gd-jp'>公園でお祭りがあります。</span>(Công viên có lễ hội)</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: nếu phía sau là <span class='gd-jp'>あります</span>／<span class='gd-jp'>います</span> và là đồ vật, người, động vật tồn tại thì dùng <span class='gd-jp'>に</span>; nếu phía sau là hành động, hoặc cái \"có\" là hoạt động, sự kiện thì dùng <span class='gd-jp'>で</span>.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm số lượng: <span class='gd-jp'>猫が二匹います。</span>(Có hai con mèo)<br>Ngoài ra, mẫu \"đang ～\" là <span class='gd-jp'>～ています</span>, chữ <span class='gd-jp'>います</span> bên trong chính là từ bạn vừa học hôm nay.</div>","n5-52":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜ています」gần giống với <b>\"đang ～\", \"～ rồi (và bây giờ vẫn như vậy)\", \"dạo này vẫn đang ～\"</b> trong tiếng Việt. Điểm mấu chốt là nó không nói về một thời điểm, mà là <b>một trạng thái đang kéo dài</b>: hành động đang diễn ra, kết quả còn lưu lại, hoặc dạo gần đây bạn vẫn liên tục làm việc đó.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Trước hết chia động từ sang thể て, rồi thêm <b>います</b> là xong. Cách chia thể て thì bạn có thể quay lại ôn bài \"て形\".<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べています</span></span><br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでいます</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>しています</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て</span> → <span class='gd-jp'>来ています</span>（きています）</span></div><div class='gd-h'>Ba ý nghĩa</div><div class='gd-sec'><span class='gd-tag'>Đang làm</span>Ngay lúc này hành động đang diễn ra, thường đi cùng 「今」.</div><div class='gd-ex-line'>・<span class='gd-jp'>今、洗濯しています。</span>(Bây giờ tôi đang giặt đồ)</div><div class='gd-ex-line'>・<span class='gd-jp'>弟はテレビを見ています。</span>(Em trai đang xem tivi)</div><div class='gd-sec'><span class='gd-tag'>Kết quả còn lưu lại</span>Có những hành động <b>xảy ra và hoàn thành ngay tức thì</b>, ví dụ kết hôn, (cửa, cửa sổ) mở ra (<span class='gd-jp'>開く</span>), dọn đến ở. Động từ kiểu này thêm ています không có nghĩa \"đang\", mà là \"đã làm xong, và bây giờ vẫn ở trạng thái đó\". Muốn tả trạng thái hiện tại của đồ vật, bạn dùng tự động từ như <span class='gd-jp'>開く</span>: nói <span class='gd-jp'>窓が開いています</span>, đừng nói thành <span class='gd-jp'>窓を開けています</span> (nghe sẽ giống \"có người đang mở cửa sổ\").</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が開いています。</span>(Cửa sổ đang mở)</div><div class='gd-ex-line'>・<span class='gd-jp'>京都に住んでいます。</span>(Tôi sống ở Kyoto)</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は結婚しています。</span>(Chị tôi đã kết hôn)</div><div class='gd-sec'><span class='gd-tag'>Dạo này vẫn đang làm</span>Những việc bạn liên tục làm trong thời gian gần đây, hiện tại, như công việc, tình hình dạo này, thói quen mới hình thành.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝走っています。</span>(Sáng nào tôi cũng chạy bộ)</div><div class='gd-ex-line'>・<span class='gd-jp'>父は銀行で働いています。</span>(Bố tôi làm việc ở ngân hàng)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>結婚しています</span> là \"đã kết hôn\", không phải \"đang tổ chức đám cưới\". Tương tự, <span class='gd-jp'>住んでいます</span> là \"đang sống ở\", muốn nói hiện tại bạn sống ở đâu thì nhất định dùng dạng này; còn <span class='gd-jp'>京都に住みます</span> lại thành \"(sau này) sẽ sống ở Kyoto\".<br>・\"Biết\" phải nói là <span class='gd-jp'>知っています</span>, nhưng \"không biết\" là <span class='gd-jp'>知りません</span>, không phải 知っていません.<br>・Khi người khác hỏi <span class='gd-jp'>もう食べましたか</span>, muốn trả lời \"chưa\" thì nói <span class='gd-jp'>まだ食べていません</span>, đừng nói thành まだ食べませんでした.<br>・Chữ 来 trong <span class='gd-jp'>来ています</span> đọc là <b>き</b>.<br>・Giữa bạn bè, người ta hay nuốt chữ い, <span class='gd-jp'>食べています</span> sẽ thành <span class='gd-jp'>食べてる</span>, nghe thấy đừng bỡ ngỡ nhé.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>ます</b> và <b>ています</b> là cặp hay bị nhầm nhất, hãy xem sự khác nhau với cùng một hành động:<br><span class='gd-jp'>本を読みます。</span>(Tôi sẽ đọc sách: thói quen thường ngày, hoặc lát nữa sẽ đọc)<br><span class='gd-jp'>本を読んでいます。</span>(Tôi đang đọc sách)<br><br><span class='gd-jp'>来月結婚します。</span>(Tháng sau tôi sẽ kết hôn)<br><span class='gd-jp'>もう結婚しています。</span>(Tôi đã kết hôn rồi)<br><br>Cả hai đều nói được về thói quen, nhưng sắc thái khác nhau:<br><span class='gd-jp'>毎日コーヒーを飲みます。</span>(Ngày nào tôi cũng uống cà phê: thói quen chung, sự thật)<br><span class='gd-jp'>最近、毎朝走っています。</span>(Dạo này sáng nào tôi cũng chạy: đang duy trì trong thời gian gần đây)</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: khi nói việc đang làm ngay lúc này, \"đã ～ rồi\" / trạng thái còn đó, hoặc \"dạo này, hiện giờ vẫn đang làm\" thì dùng ています; khi nói thói quen chung hoặc việc sắp làm thì dùng ます.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Khi học 「自動詞・他動詞」, bạn sẽ thường gặp cách nói \"kết quả còn lưu lại\" như <span class='gd-jp'>ドアが閉まっています</span> (cửa đang đóng). Lúc đó đối chiếu với bài này sẽ thấy rõ hơn.</div>","n5-53":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Trong tiếng Việt, muốn kể một chuỗi việc rất dễ: 「Sáng tôi thức dậy, đánh răng rồi ra khỏi nhà」, chỉ cần nối bằng dấu phẩy hoặc chữ \"rồi\". Tiếng Nhật thì không nối thẳng như vậy được. Các động từ đứng trước phải đổi sang <b>thể て</b>, nghĩa giống như 「…rồi…」. Chỉ <b>động từ cuối cùng</b> mới quyết định câu ở hiện tại hay quá khứ, lịch sự hay thân mật.</div><div class='gd-h'>Cách chia</div><div class='gd-sec'><b>Động từ</b>: dùng thẳng thể て (cách chia xem bài \"Thể て\").<br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きて</span></span><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行って</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んで</span></span></div><div class='gd-sec'><b>Tính từ い</b>: đổi 「い」 ở cuối thành 「くて」.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → đổi い thành くて → <span class='gd-jp'>安くて</span></span><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よくて</span></span>(trường hợp ngoại lệ này phải học thuộc)</div><div class='gd-sec'><b>Tính từ な, danh từ</b>: thêm 「で」 ngay phía sau.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かで</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生で</span></span></div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Kể theo thứ tự</span>Làm xong việc này rồi mới làm việc kế tiếp, và kể đúng theo thứ tự xảy ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>朝起きて、歯を磨いて、出かけます。</span>(Sáng thức dậy, đánh răng rồi ra khỏi nhà)</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日は家に帰って、すぐ寝ました。</span>(Hôm qua về đến nhà là đi ngủ ngay)</div><div class='gd-sec'><span class='gd-tag'>Nêu nhiều đặc điểm</span>Miêu tả một người hay một vật, nêu hai đặc điểm cùng lúc, giống 「vừa ～ vừa ～」 trong tiếng Việt.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安くて、おいしいです。</span>(Quán này vừa rẻ vừa ngon)</div><div class='gd-ex-line'>・<span class='gd-jp'>私は台湾人で、大学生です。</span>(Tôi là người Đài Loan, là sinh viên đại học)</div><div class='gd-sec'><span class='gd-tag'>Làm bằng cách nào</span>Hành động phía trước là 「cách thức」 hoặc 「trạng thái」 của việc phía sau.</div><div class='gd-ex-line'>・<span class='gd-jp'>歩いて駅へ行きます。</span>(Đi bộ đến ga)</div><div class='gd-ex-line'>・<span class='gd-jp'>傘を持って出かけます。</span>(Cầm ô ra khỏi nhà)</div><div class='gd-sec'><span class='gd-tag'>Nguyên nhân</span>Vế trước là nguyên nhân, vế sau thường là cảm xúc, trạng thái, hoặc 「không thể ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>ニュースを聞いて、びっくりしました。</span>(Nghe tin tức mà giật cả mình)</div><div class='gd-ex-line'>・<span class='gd-jp'>頭が痛くて、何もできませんでした。</span>(Đau đầu quá, chẳng làm được gì cả)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Thì và mức độ lịch sự <b>chỉ nhìn động từ cuối cùng</b>: <span class='gd-jp'>昨日、デパートへ行って、靴を買いました。</span>(Hôm qua tôi đi trung tâm thương mại và mua giày) <span class='gd-jp'>行って</span> ở phía trước không cần đổi sang quá khứ, phần 「quá khứ」 để cho <span class='gd-jp'>買いました</span> ở cuối lo.<br>・Tính từ い là <span class='gd-jp'>安くて</span>, không phải 「安いて」; <span class='gd-jp'>いい</span> phải đổi thành <span class='gd-jp'>よくて</span>. Tính từ な là <span class='gd-jp'>静かで</span>, không phải 「静かくて」.<br>・Khi nêu hai đặc điểm, tốt nhất cả hai nên cùng hướng (cùng là ưu điểm hoặc cùng là nhược điểm). Với kiểu một tốt một xấu như 「rẻ nhưng không ngon」, hãy đổi sang dùng <span class='gd-jp'>が</span>: <span class='gd-jp'>この店は安いですが、おいしくないです。</span>(Quán này rẻ nhưng không ngon)<br>・Với て chỉ nguyên nhân, vế sau <b>không được</b> dùng các ý như 「…nhé/…nào」, 「hãy ～」, 「tôi muốn ～」. Muốn nói 「Trời đang mưa, mình đi taxi nhé」 thì phải đổi sang <span class='gd-jp'>から</span>: <span class='gd-jp'>雨が降っているから、タクシーで行きましょう。</span></div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Cùng là kể chuyện cuối tuần đã làm gì:<br><span class='gd-jp'>映画を見て、ご飯を食べました。</span>(Xem phim, rồi đi ăn cơm: kể theo thứ tự)<br><span class='gd-jp'>映画を見てから、ご飯を食べました。</span>(Xem phim xong <b>rồi mới</b> đi ăn cơm: nhấn mạnh thứ tự trước sau)<br><span class='gd-jp'>映画を見たり、ご飯を食べたりしました。</span>(Nào là xem phim, nào là ăn cơm...: chỉ nêu ví dụ, thứ tự không quan trọng, có thể còn làm những việc khác)</div><div class='gd-warn'>Mẹo nhỏ để chọn: kể từng việc theo thứ tự thì dùng 「て」, nhấn mạnh 「làm xong A rồi mới làm B」 thì dùng 「てから」, nêu đại vài việc làm ví dụ thì dùng 「たり～たり」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Sau thể て còn nối được nhiều mẫu câu thông dụng, ví dụ 「hãy ～」: <span class='gd-jp'>ちょっと待ってください。</span>(Xin chờ một chút), và 「đang ～」: <span class='gd-jp'>今、ご飯を食べています。</span>(Bây giờ tôi đang ăn cơm)</div>","n5-55":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜てください」 tương đương <b>「hãy 〜」「xin hãy 〜」</b> trong tiếng Việt, còn 「〜ないでください」 là <b>「đừng 〜」「vui lòng không 〜」</b>. Bạn bè nói 「Chờ mình chút nhé」 là <span class='gd-jp'>ちょっと待ってください</span>, biển báo ghi 「Vui lòng không chụp ảnh」 là <span class='gd-jp'>写真を撮らないでください</span>, dùng chính hai mẫu câu này.</div><div class='gd-h'>Dùng khi nào</div><div class='gd-sec'><span class='gd-tag'>Nhờ người khác</span>Nhờ đối phương làm giúp bạn một việc.</div><div class='gd-ex-line'>・<span class='gd-jp'>もう一度言ってください。</span>(Xin hãy nói lại một lần nữa)</div><div class='gd-sec'><span class='gd-tag'>Chỉ dẫn, dặn dò</span>Rất hay nghe khi thầy cô giảng bài, bác sĩ dặn dò, hoặc khi hướng dẫn các bước.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに名前を書いてください。</span>(Xin hãy viết tên vào đây)</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を毎日飲んでください。</span>(Thuốc này hãy uống mỗi ngày)</div><div class='gd-sec'><span class='gd-tag'>Nhờ đối phương đừng làm</span>Dùng được khi nhắc nhở, cấm đoán, hay cả khi an ủi.</div><div class='gd-ex-line'>・<span class='gd-jp'>心配しないでください。</span>(Đừng lo lắng nhé)</div><div class='gd-ex-line'>・<span class='gd-jp'>教室で食べないでください。</span>(Xin đừng ăn trong lớp học)</div><div class='gd-h'>Cách chia: hãy làm 〜</div><div class='gd-sec'>Trước hết đổi động từ sang <b>thể て</b> (hình thức đã học ở bài \"Thể て\"), rồi thêm <span class='gd-jp'>ください</span> ngay phía sau.<br><b>Nhóm 1 (động từ 五段)</b>: nhìn âm cuối để biết chia thế nào.<br>・Kết thúc bằng う、つ、る → って：<span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待って</span> → <span class='gd-jp'>待ってください</span></span><br>・Kết thúc bằng む、ぶ、ぬ → んで：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んでください</span></span><br>・Kết thúc bằng く → いて：<span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いてください</span></span><br>・Kết thúc bằng ぐ → いで：<span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急いでください</span></span><br>・Kết thúc bằng す → して：<span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話してください</span></span><br>・Ngoại lệ：<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行ってください</span></span>(không phải 行いて)</div><div class='gd-sec'><b>Nhóm 2 (động từ 一段)</b>: bỏ 「る」 rồi thêm 「て」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べてください</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見てください</span></span></div><div class='gd-sec'><b>Nhóm 3 (する・来る)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>してください</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来てください</span>(きてください)</span></div><div class='gd-h'>Cách chia: đừng làm 〜</div><div class='gd-sec'>Trước hết đổi động từ sang <b>thể ない</b>, rồi thêm <span class='gd-jp'>でください</span> phía sau.<br><b>Nhóm 1 (động từ 五段)</b>: đổi âm cuối sang âm hàng 「あ」 cùng hàng, rồi thêm ない.<br><span class='gd-pair'><span class='gd-jp'>撮る</span> → đổi る thành ら → <span class='gd-jp'>撮らない</span> → <span class='gd-jp'>撮らないでください</span></span><br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書かないでください</span></span><br>Động từ kết thúc bằng う thì đổi thành 「わ」：<span class='gd-pair'><span class='gd-jp'>吸う</span> → <span class='gd-jp'>吸わないでください</span></span></div><div class='gd-sec'><b>Nhóm 2 (động từ 一段)</b>: bỏ 「る」 rồi thêm ない.<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないでください</span></span></div><div class='gd-sec'><b>Nhóm 3 (する・来る)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しないでください</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ないでください</span>(こないでください)</span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・「Đừng ～」 là ない cộng thêm <b>で</b>: <span class='gd-jp'>見ないでください</span>, không phải 「見ないてください」, và cũng không có cách nói 「見ませんでください」.<br>・Động từ kết thúc bằng う khi sang thể ない thì thành 「わ」: <span class='gd-jp'>吸わない</span>, <span class='gd-jp'>買わない</span>, không phải 「吸あない」.<br>・来る có hai cách đọc khác nhau: <span class='gd-jp'>来てください</span> đọc là <b>きて</b>, còn <span class='gd-jp'>来ないでください</span> đọc là <b>こないで</b>.<br>・Dù tiếng Việt dịch là 「xin hãy」, thực chất đây là <b>bảo đối phương làm việc gì đó</b>. Khi nhờ thầy cô hay cấp trên, nói <span class='gd-jp'>〜てくださいませんか</span> (anh/chị có thể ～ giúp tôi được không) sẽ lịch sự hơn.<br>・Giữa bạn bè hay lược bỏ ください: <span class='gd-jp'>ちょっと待って。</span>(Đợi chút) <span class='gd-jp'>見ないで。</span>(Đừng nhìn)<br>・Nhân viên cửa hàng hay nói với khách <span class='gd-jp'>少々お待ちください</span> (xin quý khách chờ một lát), đó là một dạng lịch sự hơn, không phải thể て của bài này, nghe thì nhận ra là được.</div><div class='gd-h'>Phân biệt với các mẫu trông giống nhau</div><div class='gd-sec'>Nếu trước <span class='gd-jp'>ください</span> là <b>đồ vật</b> thì nghĩa là 「xin cho tôi」; nếu trước đó là <b>động từ thể て</b> thì nghĩa là 「xin bạn làm」.</div><div class='gd-ex-line'>・<span class='gd-jp'>水をください。</span>(Cho tôi xin nước)</div><div class='gd-ex-line'>・<span class='gd-jp'>水を飲んでください。</span>(Hãy uống nước đi)</div><div class='gd-warn'>Mẹo nhỏ để chọn: 「danh từ + をください」 là xin người ta đưa đồ, còn 「thể て + ください」 là nhờ người ta làm một hành động.</div>","n5-57":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Trong tiếng Việt, chữ «muốn» gộp hai nghĩa: muốn có một <b>món đồ</b> (tôi muốn có điện thoại mới) và muốn <b>làm</b> một việc (tôi muốn đi Nhật). Tiếng Nhật tách hai trường hợp này ra: muốn đồ vật dùng <b>「欲しい」</b>, muốn làm hành động dùng <b>「〜たい」</b>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'><span class='gd-tag'>Muốn có đồ vật</span>Danh từ ＋ が欲しいです</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいスマホが欲しいです。</span>(Tôi muốn có điện thoại mới)</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日に時計が欲しいです。</span>(Sinh nhật tôi muốn có một chiếc đồng hồ)</div><div class='gd-sec'><span class='gd-tag'>Muốn làm hành động</span>Đổi động từ sang thể ます, bỏ「ます」đi, rồi thêm「たいです」.<br><span class='gd-pair'><span class='gd-jp'>行きます</span> → bỏ ます → <span class='gd-jp'>行きたい</span></span><br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → <span class='gd-jp'>飲みたい</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べたい</span></span><span class='gd-pair'><span class='gd-jp'>見ます</span> → <span class='gd-jp'>見たい</span></span><br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>したい</span></span><span class='gd-pair'><span class='gd-jp'>来ます</span> → <span class='gd-jp'>来たい</span>（きたい）</span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行きたいです。</span>(Tôi muốn đi Nhật)</div><div class='gd-ex-line'>・<span class='gd-jp'>温泉に入りたいです。</span>(Tôi muốn đi ngâm suối nước nóng)</div><div class='gd-h'>Lưu ý về trợ từ</div><div class='gd-sec'>Trước <span class='gd-jp'>欲しい</span> dùng <b>が</b>.<br>Với <span class='gd-jp'>〜たい</span>, chỗ vốn dùng「を」thì có thể giữ「を」hoặc đổi thành「が」, cả hai đều đúng:<br><span class='gd-jp'>水を飲みたいです。</span>／<span class='gd-jp'>水が飲みたいです。</span>(Tôi muốn uống nước)<br>Các trợ từ khác thì không đổi được, vốn là gì thì giữ nguyên: <span class='gd-jp'>友達に会いたいです。</span>(Tôi muốn gặp bạn), ở đây「に」không thể đổi thành が.</div><div class='gd-h'>Phủ định và quá khứ: biến đổi giống tính từ い</div><div class='gd-sec'><span class='gd-jp'>欲しい</span> và <span class='gd-jp'>〜たい</span> đều kết thúc bằng「い」, nên cách biến đổi giống hệt tính từ い:<br><span class='gd-pair'><span class='gd-jp'>欲しいです</span> → <span class='gd-jp'>欲しくないです</span></span>(không muốn có)<span class='gd-pair'><span class='gd-jp'>欲しかったです</span></span>(lúc đó đã muốn có)<br><span class='gd-pair'><span class='gd-jp'>行きたいです</span> → <span class='gd-jp'>行きたくないです</span></span>(không muốn đi)<span class='gd-pair'><span class='gd-jp'>行きたかったです</span></span>(lúc đó đã muốn đi)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は何もしたくないです。</span>(Hôm nay tôi không muốn làm gì cả)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・たい nối sau thể ます, không phải thể từ điển: viết「行くたい」là sai, phải viết <span class='gd-jp'>行きたい</span>.<br>・たい đã là tính từ rồi nên phía sau không thêm ます nữa: nói <span class='gd-jp'>行きたいです</span>, không nói「行きたいます」; phủ định nói <span class='gd-jp'>行きたくないです</span>, không nói「行きたいません」.<br>・<span class='gd-jp'>来たい</span> đọc là <b>きたい</b>.<br>・Cả hai mẫu này đều nói về cảm giác của <b>chính mình</b>. Nói thẳng「田中さんは車が欲しいです」thì người Nhật sẽ thấy lạ, vì bạn không thể cảm nhận thay người khác. Khi nói về người khác, bạn có thể nói <span class='gd-jp'>田中さんは車が欲しいと言っていました。</span>(Anh Tanaka nói là anh ấy muốn có xe). Còn dùng câu hỏi để hỏi đối phương thì được: <span class='gd-jp'>何が欲しいですか。</span>(Bạn muốn gì?)<br>・Hỏi thẳng thầy cô, cấp trên, khách bằng「〜たいですか」nghe như đang dò xem họ muốn làm gì, không lịch sự lắm. Muốn mời đối phương uống gì đó thì nói <span class='gd-jp'>コーヒーはいかがですか。</span>hoặc <span class='gd-jp'>コーヒーを飲みませんか。</span>sẽ lịch sự hơn.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng là một ly cà phê:<br><span class='gd-jp'>コーヒーが欲しいです。</span>(Tôi muốn có cà phê: thứ bạn muốn là «cà phê»)<br><span class='gd-jp'>コーヒーが飲みたいです。</span>(Tôi muốn uống cà phê: việc bạn muốn làm là hành động «uống»)<br>Người Việt hay bị vướng ở câu «Tôi muốn đi Nhật». Trong câu có chữ «muốn», nhưng thứ bạn thật sự muốn làm là hành động «đi», nên phải nói <span class='gd-jp'>日本へ行きたいです。</span>, không dùng 欲しい.</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: bỏ chữ «muốn» trong tiếng Việt đi rồi nhìn phần phía sau. Nếu sau đó là <b>danh từ</b> (điện thoại, cà phê) thì dùng 欲しい; nếu là <b>động từ</b> (đi, ăn, xem) thì dùng たい.</div><div class='gd-h'>Sau khi học xong, bạn có thể học tiếp</div><div class='gd-sec'>Kết hợp với「に (mục đích)」: <span class='gd-jp'>映画を見に行きたいです。</span>(Tôi muốn đi xem phim). Sau này bạn còn học cách nói người khác muốn gì: <span class='gd-jp'>欲しがっている</span>、<span class='gd-jp'>〜たがっている</span>.</div>","n5-59":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜とき」tương đương với <b>«khi / lúc ...»</b> trong tiếng Việt. Điểm khác là tiếng Nhật đặt「とき」ở cuối, còn cả đoạn phía trước đều bổ nghĩa cho「とき」này, ví dụ <span class='gd-jp'>暇なとき</span>(lúc rảnh)、<span class='gd-jp'>子どものとき</span>(hồi nhỏ). Tiếng Việt thì ngược lại: «khi/lúc» đứng trước.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>「とき」bản thân là danh từ, nên cách nối phía trước giống hệt cách bổ nghĩa cho danh từ mà bạn đã học.<br><b>Động từ</b>: nối trực tiếp<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くとき</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないとき</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったとき</span></span><br><b>Tính từ い</b>: nối trực tiếp<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいとき</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いとき</span></span><br><b>Tính từ な</b>: thêm「な」<br><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇なとき</span></span><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なとき</span></span><br><b>Danh từ</b>: thêm「の」<br><span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どものとき</span></span><span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みのとき</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>暇なとき、何をしますか。</span>(Lúc rảnh bạn thường làm gì?)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものとき、よくこの公園で遊びました。</span>(Hồi nhỏ tôi hay chơi ở công viên này)</div><div class='gd-ex-line'>・<span class='gd-jp'>わからないとき、先生に聞きます。</span>(Khi không hiểu thì tôi hỏi thầy cô)</div><div class='gd-ex-line'>・<span class='gd-jp'>時間がないとき、コンビニでご飯を買います。</span>(Lúc không có thời gian, tôi mua cơm ở cửa hàng tiện lợi)</div><div class='gd-h'>Điểm quan trọng nhất: 行くとき và 行ったとき</div><div class='gd-sec'>Động từ đứng trước「とき」dùng dạng nguyên mẫu hay thể た, <b>không phụ thuộc cả câu ở hiện tại hay quá khứ</b>, mà phụ thuộc vào việc hành động đó tại thời điểm ấy <b>đã hoàn thành chưa</b>.<br><span class='gd-tag'>Thể từ điển＋とき</span>Hành động chưa xong, sắp làm hoặc đang làm dở.<br><span class='gd-tag'>Thể た＋とき</span>Hành động đã hoàn thành.</div><div class='gd-ex-line'>・<span class='gd-jp'>出かけるとき、「いってきます」と言います。</span>(Khi ra khỏi nhà thì nói「いってきます」, tức «con đi đây»)</div><div class='gd-ex-line'>・<span class='gd-jp'>家に帰ったとき、「ただいま」と言います。</span>(Khi về đến nhà thì nói「ただいま」, tức «con về rồi»)</div><div class='gd-sec'>Xem thêm một cặp nữa, cả hai câu đều kết thúc ở quá khứ nhưng nghĩa khác nhau khá nhiều:</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に行くとき、辞書を買いました。</span>(Lúc chuẩn bị đi Nhật, tôi đã mua từ điển: mua trước khi đi hoặc trên đường đi)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に行ったとき、辞書を買いました。</span>(Khi đã đến Nhật, tôi đã mua từ điển: đến Nhật rồi mới mua)</div><div class='gd-sec'>Câu đầu rõ ràng là chuyện quá khứ nhưng phía trước vẫn dùng <span class='gd-jp'>行く</span>, vì vào lúc mua từ điển thì người đó chưa đến Nhật.</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Danh từ phải thêm の: <span class='gd-jp'>子どものとき</span>, không phải 子どもとき.<br>・Tính từ な phải thêm な và không dùng だ: <span class='gd-jp'>暇なとき</span>, không phải 暇とき, cũng không phải 暇だとき. Chỉ khi ở quá khứ mới nói được <span class='gd-jp'>暇だったとき</span>.<br>・Sau động từ và tính từ い <b>không</b> thêm の: nhiều bạn nghĩ theo kiểu «danh từ＋の» nên nói thành「行くのとき」, đây là sai.<br>・Trước「とき」không dùng ます、です: <span class='gd-jp'>行くとき、〜ます</span>đã đủ lịch sự rồi, đừng nói「行きますとき」. Mức độ lịch sự do cuối câu quyết định.<br>・Khi nói về thói quen hoặc điều kiện, hay thêm は thành「ときは」, ví dụ <span class='gd-jp'>寒いときは、温かいお茶を飲みます。</span>(Khi trời lạnh tôi uống trà nóng), nghe rất tự nhiên.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><span class='gd-jp'>〜まえに</span>、<span class='gd-jp'>〜たあとで</span> bạn đã học cũng liên quan đến thời gian, dễ bị lẫn với「とき」.<br><b>とき</b>＝ngay lúc đó, trong quá trình đó: <span class='gd-jp'>家に帰るとき、パンを買いました。</span>(Trên đường về nhà tôi đã mua bánh mì)<br><b>まえに</b>＝chỉ nói «trước đó», trước bao lâu cũng được: <span class='gd-jp'>家に帰るまえに、パンを買いました。</span>(Trước khi về nhà tôi đã mua bánh mì)<br><b>たとき</b>＝thời điểm hành động đã xong: <span class='gd-jp'>家に帰ったとき、母はいませんでした。</span>(Khi tôi về đến nhà thì mẹ không có ở đó)<br><b>たあとで</b>＝sau khi làm xong, tiếp theo làm việc khác: <span class='gd-jp'>家に帰ったあとで、宿題をしました。</span>(Sau khi về nhà tôi đã làm bài tập)</div><div class='gd-warn'>Mẹo nhỏ để phán đoán: muốn nói «ngay vào lúc đó» thì dùng とき; muốn nói thứ tự trước sau thì dùng まえに hoặc あとで.</div><div class='gd-h'>Sau khi học xong, bạn có thể học tiếp</div><div class='gd-sec'>Khi muốn nói «lúc hành động đã làm xong» ở phía trước「とき」thì dùng thể た, nên bạn cần quen với cách biến đổi của <span class='gd-jp'>た形</span> trước. Sau này lên N4 bạn sẽ học <span class='gd-jp'>〜たら</span>(nếu ～, sau khi ～), mẫu này thường được đem ra so sánh với「とき」.</div>","n5-63":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Từ nghi vấn là những từ dùng để hỏi, tương đương với 「gì, ai, ở đâu, khi nào, cái nào, bao nhiêu tiền, thế nào」 trong tiếng Việt. Cách dùng cũng khá giống tiếng Việt: <b>muốn hỏi gì thì đặt từ nghi vấn vào đúng vị trí đó, cuối câu thêm か</b>. Ngoài ra, thêm「も」hoặc thêm「か」sau từ nghi vấn sẽ làm nghĩa thay đổi hoàn toàn, và đây là trọng tâm của bài này.</div><div class='gd-h'>Trước hết, làm quen với bảy từ hay dùng nhất</div><div class='gd-ex-line'>・<span class='gd-jp'>これは何ですか。</span>(Đây là cái gì?)</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人は誰ですか。</span>(Người kia là ai?)</div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこですか。</span>(Nhà vệ sinh ở đâu?)</div><div class='gd-ex-line'>・<span class='gd-jp'>誕生日はいつですか。</span>(Sinh nhật bạn là khi nào?)</div><div class='gd-ex-line'>・<span class='gd-jp'>どれがいいですか。</span>(Cái nào tốt?)</div><div class='gd-ex-line'>・<span class='gd-jp'>これはいくらですか。</span>(Cái này bao nhiêu tiền?)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本はどうでしたか。</span>(Nhật Bản thế nào?)</div><div class='gd-sec'>Khi muốn lịch sự hơn với khách hoặc người lớn tuổi: <span class='gd-jp'>誰</span> có thể đổi thành <span class='gd-jp'>どなた</span>, <span class='gd-jp'>どう</span> có thể đổi thành <span class='gd-jp'>いかが</span>. Nhân viên cửa hàng hay nói <span class='gd-jp'>コーヒーはいかがですか。</span>(Bạn dùng một ly cà phê nhé?)</div><div class='gd-h'>「何」đọc là なに hay なん?</div><div class='gd-sec'>Khi theo sau là <span class='gd-jp'>です</span>, <span class='gd-jp'>の</span>, hoặc đơn vị đếm như 「giờ」「người」, ta đọc là <b>なん</b>: <span class='gd-jp'>何ですか</span>、<span class='gd-jp'>何の本</span>、<span class='gd-jp'>何時</span>、<span class='gd-jp'>何人</span>、<span class='gd-jp'>何曜日</span>.<br>Khi theo sau là <span class='gd-jp'>を</span>, <span class='gd-jp'>が</span>, <span class='gd-jp'>も</span>, <span class='gd-jp'>か</span>, ta đọc là <b>なに</b>: <span class='gd-jp'>何を食べますか</span>、<span class='gd-jp'>何も</span>、<span class='gd-jp'>何か</span>.</div><div class='gd-h'>Thêm「も」: không… gì cả</div><div class='gd-sec'><span class='gd-tag'>Từ nghi vấn＋も＋phủ định</span> mang nghĩa 「không… gì cả, không ai…, không… ở đâu cả」.</div><div class='gd-ex-line'>・<span class='gd-jp'>何も飲みませんでした。</span>(Mình không uống gì cả)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰も来ませんでした。</span>(Không ai đến cả)</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日はどこへも行きませんでした。</span>(Chủ nhật mình không đi đâu cả)</div><div class='gd-sec'>Chú ý trợ từ: <span class='gd-jp'>を</span>、<span class='gd-jp'>が</span> vốn có sẽ bị も thay thế (<span class='gd-pair'><span class='gd-jp'>何を</span> → <span class='gd-jp'>何も</span></span>); nhưng <span class='gd-jp'>へ</span>、<span class='gd-jp'>に</span> thì phải giữ lại và đặt trước も: <span class='gd-jp'>どこへも</span>、<span class='gd-jp'>どこにも</span>、<span class='gd-jp'>誰にも</span>.</div><div class='gd-h'>Thêm「か」: cái nào đó, không xác định</div><div class='gd-sec'><span class='gd-tag'>Từ nghi vấn＋か</span> trở thành 「cái gì đó, ai đó, nơi nào đó, hôm nào đó」, tức là có thật, nhưng không nói rõ là cái nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>何か食べたいです。</span>(Mình muốn ăn chút gì đó)</div><div class='gd-ex-line'>・<span class='gd-jp'>誰かいますか。</span>(Có ai ở đó không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>どこか静かな場所へ行きたいです。</span>(Mình muốn đến một nơi yên tĩnh nào đó)</div><div class='gd-ex-line'>・<span class='gd-jp'>いつか日本に住みたいです。</span>(Một ngày nào đó mình muốn sống ở Nhật)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Khi từ nghi vấn là chủ ngữ thì dùng <b>が</b>, không dùng は: <span class='gd-jp'>誰が来ましたか。</span>, không thể nói 誰は来ましたか。<br>・<span class='gd-jp'>いつも</span> không phải 「lúc nào cũng không ~」 mà là 「luôn luôn」. Theo sau có thể là khẳng định hoặc phủ định: <span class='gd-jp'>いつも朝ご飯を食べます。</span>(Mình luôn ăn sáng) / <span class='gd-jp'>いつも朝ご飯を食べません。</span>(Mình luôn không ăn sáng)<br>・<span class='gd-jp'>何も</span> đọc là なにも, không phải なんも.<br>・<span class='gd-jp'>どれ</span> dùng khi chọn một trong ba thứ trở lên; chỉ có hai thứ thì dùng <span class='gd-jp'>どちら</span>.</div><div class='gd-h'>Phân biệt với những cách nói trông giống nhau</div><div class='gd-sec'>Cùng là hỏi bạn đã uống gì, chỉ khác một chữ là nghĩa đã khác:<br><b>何を</b>＝hỏi 「là gì」, người kia phải trả lời bằng tên thứ đã uống: <span class='gd-jp'>何を飲みましたか。</span>(Bạn đã uống gì?) → <span class='gd-jp'>お茶です。</span><br><b>何か</b>＝hỏi 「có hay không」, người kia trả lời はい・いいえ trước: <span class='gd-jp'>何か飲みましたか。</span>(Bạn có uống gì không?) → <span class='gd-jp'>はい、お茶を飲みました。</span><br><b>何も</b>＋phủ định＝「không có gì cả」: <span class='gd-jp'>いいえ、何も飲みませんでした。</span>(Không, mình không uống gì cả)</div><div class='gd-warn'>Mẹo nhỏ: muốn biết 「là gì」 thì dùng 何を; muốn biết 「có hay không」 thì dùng 何か; muốn nói 「hoàn toàn không có」 thì dùng 何も＋phủ định.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Bộ 「này, đó, kia, nào」 nên nhớ cả nhóm cùng lúc thì dễ dùng hơn. Bạn có thể học tiếp về từ chỉ thị (こそあど): <span class='gd-jp'>どの本ですか。</span>(Quyển sách nào?)</div>","n5-64":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt có 「này, đó, kia, nào」, tiếng Nhật cũng chia thành bốn nhóm tương tự: <b>こ</b>＝này (gần tôi)、<b>そ</b>＝đó (gần bạn)、<b>あ</b>＝kia (xa cả hai chúng ta)、<b>ど</b>＝nào. Hãy nhớ trước bốn âm đầu 「こそあど」, rồi đổi phần đuôi là bạn có thể chỉ đồ vật, chỉ địa điểm, chỉ phương hướng.</div><div class='gd-h'>Thử tưởng tượng một khung cảnh</div><div class='gd-sec'>Bạn và một người bạn đang đứng bên đường. Bạn cầm điện thoại, bạn của bạn cầm một ly cà phê, còn ở phía đối diện xa xa có một tòa nhà lớn.<br>Điện thoại ở phía bạn thì dùng <b>こ</b>. Ly cà phê ở phía bạn kia thì dùng <b>そ</b>. Tòa nhà xa cả hai người thì dùng <b>あ</b>. Không biết là cái nào thì dùng <b>ど</b>.</div><div class='gd-h'>Xem bốn nhóm cùng lúc</div><div class='gd-sec'><span class='gd-tag'>Chỉ đồ vật</span><span class='gd-jp'>これ・それ・あれ・どれ</span><br>Những từ này tự đứng làm chủ ngữ được, theo sau có thể gắn trực tiếp「は」「が」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の傘です。</span>(Đây là cây dù của mình)</div><div class='gd-ex-line'>・<span class='gd-jp'>それ、何ですか。</span>(Cái bạn đang cầm đó là gì vậy?)</div><div class='gd-ex-line'>・<span class='gd-jp'>あれは東京タワーです。</span>(Kia là Tháp Tokyo)</div><div class='gd-sec'><span class='gd-tag'>Theo sau là danh từ</span><span class='gd-jp'>この・その・あの・どの</span><br>Những từ này không dùng đứng một mình được, phía sau nhất định phải có một danh từ.</div><div class='gd-ex-line'>・<span class='gd-jp'>この本、おもしろいですよ。</span>(Quyển sách này hay lắm đó)</div><div class='gd-ex-line'>・<span class='gd-jp'>そのかばん、かわいいですね。</span>(Cái túi của bạn dễ thương quá)</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人はだれですか。</span>(Người kia là ai vậy?)</div><div class='gd-sec'><span class='gd-tag'>Chỉ địa điểm</span><span class='gd-jp'>ここ・そこ・あそこ・どこ</span></div><div class='gd-ex-line'>・<span class='gd-jp'>トイレはどこですか。</span>(Nhà vệ sinh ở đâu?)</div><div class='gd-ex-line'>・<span class='gd-jp'>あそこにコンビニがあります。</span>(Ở đằng kia có cửa hàng tiện lợi)</div><div class='gd-sec'><span class='gd-tag'>Dạng lịch sự</span><span class='gd-jp'>こちら・そちら・あちら・どちら</span><br>Dùng để chỉ phương hướng, địa điểm, và cũng dùng để giới thiệu người một cách lịch sự. Nhân viên cửa hàng và quầy tiếp tân rất hay dùng. Khi nói chuyện với bạn bè thì sẽ thành <span class='gd-jp'>こっち・そっち・あっち・どっち</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>受付はあちらです。</span>(Quầy tiếp tân ở bên kia ạ)</div><div class='gd-ex-line'>・<span class='gd-jp'>こちらは田中さんです。</span>(Đây là anh Tanaka)</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>この・その・あの・どの</span> không dùng đứng một mình được. 「Cái này là của mình」 phải nói <span class='gd-jp'>これは私のです</span>, không thể nói このは私のです。<br>・「Chỗ kia」 là <b>あそこ</b>, không phải あこ. Dạng của từ này khác với các từ còn lại trong nhóm, nên cần học thuộc riêng.<br>・Cùng là 「đó / kia」, tiếng Nhật phải phân biệt rõ: đồ vật ở cạnh hoặc trên tay người đối diện thì dùng <b>それ</b>; xa cả hai người thì mới dùng <b>あれ</b>.<br>・Đứng ở vị trí khác nhau thì từ dùng cũng đổi. Khi người kia chỉ vào đồ trên tay mình và hỏi <span class='gd-jp'>これは何ですか</span>, bạn trả lời phải nói <span class='gd-jp'>それは～です</span>, vì món đồ đó ở phía họ.<br>・Chuyện người kia vừa nhắc đến cũng được chỉ bằng từ bắt đầu bằng「そ」: <span class='gd-jp'>それ、いいですね。</span>(Cái đó hay đó nhỉ)<br>・Khi giới thiệu người phải dùng <span class='gd-jp'>こちら</span>. Dùng <span class='gd-jp'>これ</span> để chỉ người thì giống như coi người ta là đồ vật, rất bất lịch sự.</div><div class='gd-h'>Phân biệt với những từ trông giống nhau</div><div class='gd-sec'><b>これ</b> và <b>この</b>: nghĩa đều là 「này」, khác nhau ở chỗ phía sau là gì.<br><span class='gd-jp'>これは私の本です。</span>(Đây là sách của mình)<br><span class='gd-jp'>この本は私のです。</span>(Quyển sách này là của mình)<br>Ở câu đầu, sau <span class='gd-jp'>これ</span> là「は」. Ở câu sau, sau <span class='gd-jp'>この</span> là「本」.</div><div class='gd-sec'><b>どれ</b> và <b>どちら</b>: đều là 「cái nào」, khác nhau ở số lựa chọn.<br><span class='gd-jp'>この三つの中で、どれがいいですか。</span>(Trong ba cái này, bạn thấy cái nào được?)<br><span class='gd-jp'>コーヒーと紅茶、どちらがいいですか。</span>(Cà phê hay trà đen, bạn muốn cái nào?)<br>Chọn 「cái nào」 trong ba thứ trở lên thì dùng どれ; chỉ có hai thứ, chọn một, thì dùng どちら.</div><div class='gd-warn'>Mẹo nhỏ: phía sau là danh từ ngay thì dùng この; phía sau là「は」「が」thì dùng これ. Chọn một trong ba thứ trở lên dùng どれ; chọn một trong hai dùng どちら.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Nhóm bắt đầu bằng「ど」thật ra chính là những từ dùng để đặt câu hỏi, nên bạn có thể học tiếp bài 「từ nghi vấn」, để học luôn <span class='gd-jp'>だれ</span>、<span class='gd-jp'>なに</span>、<span class='gd-jp'>いつ</span> cùng lúc.</div>","n5-60":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜でしょう」giống với “chắc là ~ nhỉ / ~ đúng không?” trong tiếng Việt. Xuống giọng là bạn tự đoán: “Ngày mai chắc trời sẽ mưa nhỉ”. Lên giọng là bạn hỏi để xác nhận với đối phương: “Ngon đúng không?” Cùng một cách nói nhưng <b>nhờ ngữ điệu mà tách thành hai nghĩa</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Đoán (xuống giọng ↓)</span>Bạn không chắc chắn 100%, chỉ tự suy đoán. Thường dùng cùng <span class='gd-jp'>たぶん</span> (có lẽ), dự báo thời tiết cũng rất hay dùng.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日はたぶん雨でしょう。</span>(Ngày mai chắc trời sẽ mưa nhỉ)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんはもう帰ったでしょう。</span>(Anh Tanaka chắc đã về rồi nhỉ)</div><div class='gd-sec'><span class='gd-tag'>Xác nhận (lên giọng ↑)</span>Bạn nghĩ đối phương cũng sẽ nghĩ như vậy, nên hỏi một câu và chờ họ gật đầu đồng ý.</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしいでしょう？</span>(Cái bánh này ngon đúng không?)</div><div class='gd-ex-line'>・<span class='gd-jp'>ほら、言ったでしょう？</span>(Thấy chưa, tôi đã nói rồi mà?)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'><b>Động từ, tính từ い</b>: nối thẳng vào phía sau. Phủ định và quá khứ cũng nối thẳng như vậy.<br><span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るでしょう</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないでしょう</span></span><span class='gd-pair'><span class='gd-jp'>降った</span> → <span class='gd-jp'>降ったでしょう</span></span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いでしょう</span></span><span class='gd-pair'><span class='gd-jp'>寒くない</span> → <span class='gd-jp'>寒くないでしょう</span></span></div><div class='gd-sec'><b>Tính từ な, danh từ</b>: phải bỏ「だ」trước rồi mới nối.<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → bỏ だ → <span class='gd-jp'>静かでしょう</span></span><br><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生でしょう</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨でしょう</span></span><br>Với quá khứ,「だった」phải giữ lại：<span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったでしょう</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Sau danh từ và tính từ な không được giữ lại「だ」：<span class='gd-jp'>学生でしょう</span> mới đúng, nói 「学生だでしょう」 là sai.<br>・Đừng thêm です ở phía trước：chỉ cần <span class='gd-jp'>寒いでしょう</span>, không được nói 「寒いですでしょう」. でしょう vốn là “dạng suy đoán” của です, nên đã lịch sự sẵn rồi.<br>・Không dùng để nói về việc <b>chính mình định làm</b>. 「私は明日行くでしょう」nghe rất lạ; dự định của bản thân thì nói thẳng <span class='gd-jp'>明日行きます</span>.<br>・「でしょう？」khi xác nhận mang sắc thái “chắc bạn cũng biết rồi nhỉ”, dùng với thầy cô, cấp trên sẽ hơi thiếu khách sáo. Muốn hỏi lịch sự với người trên, hãy dùng <span class='gd-jp'>〜でしょうか</span> (xin hỏi ~ ạ?), ví dụ <span class='gd-jp'>駅はどこでしょうか。</span> (Xin hỏi ga tàu ở đâu ạ?)<br>・Giữa bạn bè, câu xác nhận hay được rút gọn thành <span class='gd-jp'>でしょ？</span>, nghe thấy đừng bối rối, nghĩa vẫn y như vậy.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>ましょう</b> và <b>でしょう</b> đều kết thúc bằng「しょう」, nhưng nghĩa hoàn toàn khác:<br>・<span class='gd-jp'>一緒に行きましょう。</span>(Chúng ta cùng đi nhé: rủ rê)<br>・<span class='gd-jp'>田中さんも行くでしょう。</span>(Chắc anh Tanaka cũng sẽ đi nhỉ: suy đoán)<br>Cách nối cũng khác: ましょう nối sau dạng ます (<span class='gd-jp'>行き</span>＋ましょう), còn でしょう nối sau dạng thường như dạng từ điển (<span class='gd-jp'>行く</span>＋でしょう).</div><div class='gd-sec'><b>でしょう？</b> và <b>ね</b> đều có thể dịch là “nhỉ”, khác nhau ở chỗ đối phương có cùng cảm nhận với bạn hay không:<br>・Hai người cùng đi ngoài đường：<span class='gd-jp'>寒いですね。</span>(Lạnh quá nhỉ: cả hai cùng cảm nhận ngay lúc đó, thuận miệng đồng tình)<br>・Bạn bè vừa từ ngoài vào, bạn đang ở trong nhà hỏi：<span class='gd-jp'>外、寒いでしょう？</span>(Bên ngoài lạnh lắm đúng không?: bạn không ở ngoài, chỉ đoán là họ thấy lạnh và muốn họ xác nhận)</div><div class='gd-warn'>Mẹo phân biệt nhanh: “Cùng làm ~ nhé” là ましょう; “chắc là ~”, “~ đúng không?” là でしょう; hai người cùng cảm nhận ngay lúc đó và chỉ đồng tình thì dùng ね.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Muốn nói với mức chắc chắn thấp hơn nữa, kiểu “biết đâu ~”, bạn có thể dùng <span class='gd-jp'>〜かもしれません</span>：<span class='gd-jp'>明日は雨かもしれません。</span>(Biết đâu ngày mai trời sẽ mưa)</div>","n5-61":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「〜からです」chính là <b>“Vì ~ / Bởi vì ~”</b> trong tiếng Việt. Khi đối phương hỏi bạn bằng <span class='gd-jp'>どうして</span> (tại sao), bạn chỉ cần nói lý do ra rồi thêm「からです」ở cuối để trả lời.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Trả lời “tại sao”</span>Đối phương hỏi “tại sao” trước, bạn chỉ cần trả lời lý do, không cần nhắc lại chuyện đã xảy ra.</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして休んだんですか。</span>(Tại sao bạn nghỉ vậy?)</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったからです。</span>(Vì tôi bị sốt)</div><div class='gd-ex-line'>・<span class='gd-jp'>どうして日本語を勉強しているんですか。</span>(Tại sao bạn học tiếng Nhật?)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本のアニメが好きだからです。</span>(Vì tôi thích anime Nhật)</div><div class='gd-sec'><span class='gd-tag'>Tự bổ sung lý do</span>Nói một việc trước, rồi dùng câu tiếp theo để giải thích lý do.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はパーティーに行きません。忙しいからです。</span>(Hôm nay tôi không đi tiệc. Vì tôi bận)</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Phía trước「から」dùng <b>dạng không có ます, không có です</b> (dạng nói chuyện với bạn bè), còn phần lịch sự giao cho「です」ở cuối câu.<br><b>Động từ</b>: nối thẳng.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くからです</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったからです</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないからです</span></span><br><b>Tính từ い</b>: nối thẳng.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いからです</span></span><br><b>Tính từ な, danh từ</b>: ở giữa phải thêm「だ」.<br><span class='gd-pair'><span class='gd-jp'>好き</span> → <span class='gd-jp'>好きだからです</span></span><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だからです</span></span></div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Quên thêm「だ」sau tính từ な và danh từ：<span class='gd-jp'>好きからです</span>、<span class='gd-jp'>雨からです</span> đều sai, phải nói <span class='gd-jp'>好きだからです</span>、<span class='gd-jp'>雨だからです</span>.<br>・Ngược lại, tính từ い <b>không được</b> thêm「だ」：nói <span class='gd-jp'>高いからです</span>, không phải 高いだからです.<br>・Trước「から」đừng để ます：<span class='gd-jp'>熱がありましたからです</span> là sai, phải nói <span class='gd-jp'>熱があったからです</span>.<br>・Tiếng Việt quen đặt “vì” ở đầu câu, còn「から」trong tiếng Nhật đặt ở <b>sau</b> lý do. Đừng nói thành から熱があった.<br>・Nói với bạn bè thì chỉ cần bỏ です：<span class='gd-jp'>熱があったから。</span>(Vì bị sốt mà)</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Bạn đã học trợ từ「から」(nguyên nhân・lý do), nghĩa của nó giống「からです」, khác nhau ở <b>cách sắp xếp câu</b>. Cùng một việc:<br><span class='gd-tag'>〜から、〜</span>Lý do ở trước, kết quả ở sau, nói gọn trong một câu.</div><div class='gd-ex-line'>・<span class='gd-jp'>熱があったから、休みました。</span>(Vì bị sốt nên tôi đã nghỉ)</div><div class='gd-sec'><span class='gd-tag'>〜からです</span>Nói kết quả trước, rồi bổ sung lý do bằng một câu riêng; hoặc khi bị hỏi “tại sao” thì chỉ trả lời lý do.</div><div class='gd-ex-line'>・<span class='gd-jp'>休みました。熱があったからです。</span>(Tôi đã nghỉ. Vì tôi bị sốt)</div><div class='gd-warn'>Mẹo phân biệt nhanh: sau lý do còn phải nói tiếp “nên làm gì” thì dùng「〜から、」; lý do tự nó là phần kết thúc của cả câu thì dùng「〜からです」.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Đặt kết quả lên trước và thêm「のは」, bạn có thể nói rõ lý do hơn：<span class='gd-jp'>昨日休んだのは、熱があったからです。</span>(Hôm qua tôi nghỉ là vì bị sốt)</div>","n5-65":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Tiếng Việt nói “một <b>tờ</b> giấy, một <b>cây</b> bút, một <b>con</b> mèo”, khi đếm đồ vật thì giữa số và danh từ phải có “tờ, cây, con”. Tiếng Nhật cũng vậy, loại từ này gọi là <b>量詞</b> (lượng từ) và cách chia cũng khá giống tiếng Việt: vật mỏng dùng <span class='gd-jp'>枚</span>, vật nhỏ và dài dùng <span class='gd-jp'>本</span>. Muốn nói “khoảng”, bạn thêm <span class='gd-jp'>くらい</span> sau số lượng.</div><div class='gd-h'>Nhớ trước mấy lượng từ này</div><div class='gd-sec'><span class='gd-tag'>つ</span>Dùng được cho đồ vật nói chung, rất “đa năng” khi bạn không biết nên dùng lượng từ nào, gọi món cũng hay dùng. Từ 1 đến 10 phải học thuộc riêng: <span class='gd-jp'>ひとつ、ふたつ、みっつ、よっつ、いつつ、むっつ、ななつ、やっつ、ここのつ、とお</span>. Từ 11 trở đi thì không dùng つ nữa.</div><div class='gd-ex-line'>・<span class='gd-jp'>りんごを3つ買いました。</span>(Mình đã mua 3 quả táo)</div><div class='gd-sec'><span class='gd-tag'>人</span>Dùng để đếm người. Cách đọc 1 và 2 người khá đặc biệt: <span class='gd-jp'>ひとり、ふたり</span>. Từ 3 người trở đi là <span class='gd-jp'>さんにん</span>, 4 người là <span class='gd-jp'>よにん</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>家族は4人です。</span>(Gia đình mình có 4 người)</div><div class='gd-sec'><span class='gd-tag'>本</span>Vật nhỏ và dài: bút, chai, ô, chuối.</div><div class='gd-ex-line'>・<span class='gd-jp'>鉛筆を1本貸してください。</span>(Cho mình mượn một cây bút chì nhé)</div><div class='gd-sec'><span class='gd-tag'>枚</span>Vật mỏng và phẳng: giấy, tem, áo sơ mi, đĩa.</div><div class='gd-ex-line'>・<span class='gd-jp'>切手を5枚ください。</span>(Cho tôi 5 con tem)</div><div class='gd-sec'><span class='gd-tag'>匹</span>Động vật nhỏ như mèo, chó, cá.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちに猫が2匹います。</span>(Nhà mình có 2 con mèo)</div><div class='gd-sec'>Ngoài ra còn hay gặp: sách dùng <span class='gd-jp'>冊</span>, máy móc như xe, tivi dùng <span class='gd-jp'>台</span>, đồ uống từng ly dùng <span class='gd-jp'>杯</span>.</div><div class='gd-h'>Đặt vào câu như thế nào</div><div class='gd-sec'>Thứ tự tự nhiên nhất là: <b>vật + を (hoặc が) + số lượng + động từ</b>. Số lượng đặt ngay trước động từ, phía sau không cần thêm trợ từ nữa.<br>Tiếng Việt nói “mua ba quả táo”, tiếng Nhật là <span class='gd-jp'>りんごを3つ買います</span>: nói vật trước, số lượng sau.<br>Muốn hỏi “bao nhiêu”, bạn thay số bằng <span class='gd-jp'>何</span>: <span class='gd-jp'>何人</span>(なんにん)、<span class='gd-jp'>何本</span>(なんぼん)、<span class='gd-jp'>何枚</span>(なんまい). Với đồ vật đếm bằng つ thì hỏi <span class='gd-jp'>いくつ</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄弟は何人いますか。</span>(Bạn có mấy anh chị em?)</div><div class='gd-h'>Nói về thời gian</div><div class='gd-sec'><span class='gd-jp'>時</span> là “mấy giờ”, còn <span class='gd-jp'>時間</span> là “mấy tiếng”: <span class='gd-jp'>2時</span> là hai giờ, <span class='gd-jp'>2時間</span> là hai tiếng.<br>Cách đọc của <span class='gd-jp'>分</span> (phút) thay đổi, bạn cần học thuộc: <span class='gd-jp'>いっぷん、にふん、さんぷん、よんぷん、ごふん、ろっぷん、ななふん、はっぷん、きゅうふん、じゅっぷん</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日7時間寝ます。</span>(Mỗi ngày mình ngủ 7 tiếng)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩いて10分くらいです。</span>(Đi bộ đến ga khoảng 10 phút)</div><div class='gd-ex-line'>・<span class='gd-jp'>1時間くらいかかります。</span>(Mất khoảng 1 tiếng)</div><div class='gd-sec'><span class='gd-jp'>くらい</span> và <span class='gd-jp'>ぐらい</span> có nghĩa giống nhau, dùng cái nào cũng được.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Vị trí của “khoảng” ngược với tiếng Việt</b>: tiếng Việt nói “khoảng một tiếng”, đặt “khoảng” ở trước; còn tiếng Nhật là <span class='gd-jp'>1時間くらい</span>, くらい đứng <b>sau</b>.<br>・Sau số lượng đừng thêm を nữa: đúng là <span class='gd-jp'>りんごを3つ買いました</span>, không phải “りんごを3つを買いました”.<br>・Cách đọc của <span class='gd-jp'>本</span> và <span class='gd-jp'>匹</span> thay đổi: <span class='gd-jp'>1本</span>いっぽん、<span class='gd-jp'>3本</span>さんぼん、<span class='gd-jp'>6本</span>ろっぽん; <span class='gd-jp'>1匹</span>いっぴき、<span class='gd-jp'>3匹</span>さんびき.<br>・1 và 2 người là ひとり、ふたり, không phải “いちにん”, “ににん”.<br>・4 giờ là <span class='gd-jp'>4時</span>(よじ), 9 giờ là <span class='gd-jp'>9時</span>(くじ), đừng đọc thành よんじ、きゅうじ.<br>・Đếm người nhất định dùng <span class='gd-jp'>人</span>, không dùng つ.</div><div class='gd-h'>Phân biệt với từ trông giống nhau</div><div class='gd-sec'>Tiếng Việt đều nói “khoảng, tầm”, nhưng tiếng Nhật phải xem nó đi sau từ nào:<br><b>くらい</b> đi sau <b>khoảng thời gian, số lượng</b>: <span class='gd-jp'>3時間くらい待ちました。</span>(Mình đã đợi khoảng 3 tiếng)<br><b>ごろ</b> đi sau <b>thời điểm</b> như mấy giờ, ngày nào: <span class='gd-jp'>3時ごろ着きます。</span>(Khoảng 3 giờ thì đến)<br>Trong khẩu ngữ bạn cũng sẽ nghe “3時くらい”, nhưng ngược lại, nói “3時間ごろ” là sai.</div><div class='gd-warn'>Mẹo nhỏ: “khoảng bao lâu, bao nhiêu” dùng くらい, “khoảng mấy giờ” dùng ごろ.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thêm <span class='gd-jp'>だけ</span> sau số lượng = chỉ cần chừng đó thôi: <span class='gd-jp'>1つだけください。</span>(Cho tôi một cái thôi)</div>","n5-66":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Phó từ là những từ nhỏ đặt trước động từ hoặc tính từ để bổ sung ý <b>“như thế nào ～”, “bao nhiêu”, “thường xuyên ra sao”</b>. “Rất” trong “rất ngon”, “thường” trong “thường đi”, “không… lắm” trong “không uống lắm” trong tiếng Nhật đều là phó từ. Thẻ này chia làm ba nhóm chính: <b>mức độ</b>, <b>số lượng</b>, <b>tần suất</b>.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Mức độ: rất</span><span class='gd-jp'>とても</span> = rất, vô cùng, đặt trước tính từ.</div><div class='gd-ex-line'>・<span class='gd-jp'>とても楽しかったです。</span>(Rất vui)</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメンはとてもおいしいです。</span>(Tô ramen này rất ngon)</div><div class='gd-sec'><span class='gd-tag'>Số lượng: nhiều</span><span class='gd-jp'>たくさん</span> = nhiều, nói về “lượng”. Đặt trước động từ, hoặc dùng “たくさんの＋danh từ”.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はたくさん食べました。</span>(Hôm qua mình đã ăn nhiều)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅にたくさんの人がいます。</span>(Ở ga có rất nhiều người)</div><div class='gd-sec'><span class='gd-tag'>Tần suất: làm thường xuyên đến đâu</span>Xếp thành một hàng, từ thường xuyên nhất đến hoàn toàn không làm:<br><b>いつも＞よく＞ときどき＞たまに＞あまり～ない＞全然～ない</b></div><div class='gd-ex-line'>・<span class='gd-jp'>いつも7時に起きます。</span>(Mình luôn dậy lúc 7 giờ)</div><div class='gd-ex-line'>・<span class='gd-jp'>よくこの店に来ます。</span>(Mình hay đến quán này)</div><div class='gd-ex-line'>・<span class='gd-jp'>ときどき料理をします。</span>(Thỉnh thoảng mình nấu ăn)</div><div class='gd-ex-line'>・<span class='gd-jp'>たまに映画を見ます。</span>(Lâu lâu mình mới xem phim)</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビはあまり見ません。</span>(Mình không xem tivi mấy)</div><div class='gd-ex-line'>・<span class='gd-jp'>お酒は全然飲みません。</span>(Mình hoàn toàn không uống rượu)</div><div class='gd-sec'><span class='gd-tag'>Một nghĩa khác của よく</span><span class='gd-jp'>よく</span> ngoài nghĩa “thường xuyên” còn có nghĩa “kỹ, đầy đủ, thật tốt”. Nhìn động từ phía sau là biết nghĩa nào.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日はよく寝ました。</span>(Hôm qua mình ngủ rất ngon)</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、よく分かりません。</span>(Xin lỗi, mình không hiểu rõ lắm)</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<span class='gd-jp'>あまり</span> và <span class='gd-jp'>全然</span> phải đi với <b>phủ định</b>: nói “<span class='gd-jp'>あまり好きです</span>” là sai, phải nói <span class='gd-jp'>あまり好きじゃないです</span> (không thích lắm).<br>・Muốn nói “không ngon lắm”, đừng dùng “とても” rồi thêm phủ định, mà phải dùng <span class='gd-jp'>あまりおいしくないです</span>.<br>・Tiếng Việt có “rất” và “nhiều” là hai từ khác nhau, tiếng Nhật cũng vậy: “rất ngon” dùng とても, “nhiều người” dùng たくさん. Nói “とても人がいます” là sai, phải nói <span class='gd-jp'>人がたくさんいます</span>.<br>・Có thể bạn sẽ nghe giới trẻ Nhật nói “<span class='gd-jp'>全然大丈夫</span>” (hoàn toàn không sao), đây là cách nói khẩu ngữ. Trong sách giáo khoa và đề thi, hãy nhớ trước là “全然＋phủ định”.<br>・Phó từ thường đặt trước động từ, tính từ mà nó bổ nghĩa: <span class='gd-jp'>よく行きます</span>, đừng đặt よく ở cuối câu.</div><div class='gd-h'>Phân biệt với từ trông giống nhau</div><div class='gd-sec'><b>あまり～ない</b> = không ～ lắm, vẫn có một chút: <span class='gd-jp'>お酒はあまり飲みません。</span>(Không uống rượu mấy, thỉnh thoảng uống một chút)<br><b>全然～ない</b> = hoàn toàn không ～, không có chút nào: <span class='gd-jp'>お酒は全然飲みません。</span>(Hoàn toàn không uống rượu)<br>Khi được hỏi <span class='gd-jp'>よく行きますか。</span>(Bạn có hay đi không?), nếu thỉnh thoảng mới đi thì đáp <span class='gd-jp'>いいえ、あまり行きません。</span>, còn chưa bao giờ đi mới đáp <span class='gd-jp'>いいえ、全然行きません。</span></div><div class='gd-warn'>Mẹo nhỏ: muốn nói “không… lắm” dùng あまり, muốn nói “hoàn toàn không” dùng 全然, cả hai đều phải đi với phủ định.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Tính từ cũng có thể biến thành phó từ, ví dụ <span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早く</span></span>: <span class='gd-jp'>早く起きます。</span>(Dậy sớm). Bạn có thể học tiếp bài “Cách dùng phó từ của tính từ”.</div>","n5-67":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Thẻ này gồm ba loại từ nhỏ giúp tiếng Nhật của bạn nghe <b>giống người thật nói chuyện</b> hơn:<br><b>Từ nối</b> ＝ giống “rồi, và, nhưng, nên” trong tiếng Việt, đặt ở đầu câu thứ hai để nối hai câu lại.<br><b>Thán từ / từ đáp</b> ＝ những âm thanh khi đáp lời hoặc mở lời như “vâng, không, à thì…, ừm…”.<br><b>Từ tượng thanh, tượng hình</b> ＝ những từ mô phỏng âm thanh hoặc dáng vẻ như “gâu gâu, ào ào, cười tươi rói”. Tiếng Nhật dùng loại từ này nhiều hơn tiếng Việt rất nhiều.</div><div class='gd-h'>Từ nối: nối hai câu lại với nhau</div><div class='gd-sec'>Cách dùng rất đơn giản: nói xong câu thứ nhất, đặt từ nối ở đầu câu thứ hai, phía sau thường thêm dấu phẩy「、」.</div><div class='gd-sec'><span class='gd-tag'>そして</span>Và, rồi thì. Bổ sung nội dung cùng hướng.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いです。そして、おいしいです。</span>（Quán này rẻ, mà lại còn ngon）</div><div class='gd-sec'><span class='gd-tag'>それから</span>Sau đó, còn nữa. Dùng khi nói việc làm tiếp theo, hoặc bổ sung “còn có ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>パンを買いました。それから、牛乳も買いました。</span>（Mình đã mua bánh mì, rồi mua thêm cả sữa）</div><div class='gd-sec'><span class='gd-tag'>でも</span>Nhưng. Phía sau nói điều trái ngược với phía trước.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は難しいです。でも、おもしろいです。</span>（Tiếng Nhật khó, nhưng thú vị）</div><div class='gd-sec'><span class='gd-tag'>だから</span>Nên, vì vậy. Phía trước là nguyên nhân, phía sau là kết quả.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りました。だから、行きませんでした。</span>（Trời mưa, nên mình đã không đi）</div><div class='gd-h'>Thán từ: đáp lời và mở lời</div><div class='gd-sec'><span class='gd-tag'>はい・いいえ</span>Vâng, đúng／Không.</div><div class='gd-ex-line'>・<span class='gd-jp'>「学生ですか。」「はい、そうです。」</span>（“Bạn là học sinh à?” “Vâng, đúng vậy”）</div><div class='gd-sec'><span class='gd-tag'>あのう</span>Dùng khi muốn gọi ai đó hoặc mở lời hỏi chuyện, mang cảm giác “xin lỗi làm phiền một chút”.</div><div class='gd-ex-line'>・<span class='gd-jp'>あのう、すみません。駅はどこですか。</span>（Dạ… xin lỗi, ga ở đâu vậy ạ?）</div><div class='gd-sec'><span class='gd-tag'>ええと</span>Vừa nghĩ vừa nói, giống “ừm…” hay “để xem…” trong tiếng Việt.</div><div class='gd-ex-line'>・<span class='gd-jp'>ええと、三つください。</span>（Ừm… cho mình ba cái）</div><div class='gd-h'>Từ tượng thanh, tượng hình: mô phỏng âm thanh và dáng vẻ</div><div class='gd-sec'><b>Từ tượng thanh</b> mô phỏng âm thanh thật, còn <b>từ tượng hình</b> dùng âm thanh để diễn tả dáng vẻ hoặc cảm giác. Thường là một âm lặp lại hai lần.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨がザーザー降っています。</span>（Mưa rơi ào ào: tượng thanh）</div><div class='gd-ex-line'>・<span class='gd-jp'>犬がワンワン鳴いています。</span>（Chó sủa gâu gâu: tượng thanh）</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がぺこぺこです。</span>（Đói meo cả bụng: tượng hình）</div><div class='gd-sec'>Ngoài ra, <span class='gd-jp'>ゆっくり</span>（chậm rãi）và <span class='gd-jp'>はっきり</span>（rõ ràng）là phó từ miêu tả cách thực hiện hành động, không phải mô phỏng âm thanh, nhưng cũng cực kỳ hay dùng:</div><div class='gd-ex-line'>・<span class='gd-jp'>ゆっくり話してください。</span>（Hãy nói chậm một chút）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Từ nối phải đặt ở <b>đầu câu thứ hai</b>, không được nhét vào giữa câu: <span class='gd-jp'>高いです。でも、買います。</span> là đúng, còn 「高いでも買います」 là sai.<br>・Khi <span class='gd-jp'>だから</span> đứng đầu câu rồi nối ngay với 「言ったでしょう」, như 「だから、言ったでしょう」, thì đó là giọng sốt ruột kiểu “đã bảo rồi mà”, đừng dùng với người lớn tuổi hơn.<br>・Khi chỉ muốn nói “nên” thông thường, với người trên hoặc trong hoàn cảnh trang trọng, bạn có thể đổi <span class='gd-jp'>だから</span> thành <span class='gd-jp'>ですから</span> lịch sự hơn.<br>・Thán từ <span class='gd-jp'>あのう</span> (cũng viết là <span class='gd-jp'>あの</span>, <span class='gd-jp'>あのー</span>) và từ chỉ định <span class='gd-jp'>あの</span> (“cái ... kia” + danh từ) có chung nguồn gốc nhưng cách dùng khác nhau. Khi gọi người, nói 「あの、すみません」 hoặc kéo dài một chút 「あのう…」 đều được; kéo dài sẽ thêm chút ngập ngừng, ngại làm phiền.<br>・<span class='gd-jp'>はい</span> không chỉ là “vâng”; khi bị điểm danh, đáp <span class='gd-jp'>はい</span> nghĩa là “có mặt, dạ có”.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>Cùng một tình huống “đắt, nhưng mình vẫn mua”, có hai cách nói:<br><span class='gd-jp'>高いです。でも、買います。</span>（hai câu, dùng <b>でも</b> mở đầu câu thứ hai）<br><span class='gd-jp'>高いですが、買います。</span>／<span class='gd-jp'>高いけど、買う。</span>（một câu, <b>が・けど</b> dính vào cuối vế trước）<br><br>“Trời mưa nên không đi” cũng vậy:<br><span class='gd-jp'>雨が降りました。だから、行きませんでした。</span>（hai câu, dùng <b>だから</b>）<br><span class='gd-jp'>雨が降ったから、行きませんでした。</span>（một câu, <b>から</b> dính vào sau nguyên nhân）</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: <b>でも・だから</b> đứng ở đầu câu mới; <b>が・けど・から</b> dính vào cuối câu trước. Nhìn xem phía trước có dấu chấm câu hay không là biết nên dùng từ nào.</div>","n5-68":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「AというB」nghĩa là <b>“B có tên là A”</b>. Giống như khi bạn nói với bạn bè “Ở Sài Gòn có một quán tên là ‘Phúc Long’”, tiếng Nhật dùng 「という」 để nối tên quán với chữ “quán”. Khi <b>người nghe có thể chưa biết</b> cái tên đó, bạn dùng mẫu này để giới thiệu.</div><div class='gd-h'>Cách nối</div><div class='gd-sec'>Tên (danh từ A) ＋ という ＋ đó là loại gì (danh từ B)<br><span class='gd-pair'><span class='gd-jp'>村田</span> ＋ <span class='gd-jp'>人</span> → <span class='gd-jp'>村田という人</span></span>（một người tên là Murata）<br><span class='gd-pair'><span class='gd-jp'>さくら</span> ＋ <span class='gd-jp'>店</span> → <span class='gd-jp'>さくらという店</span></span>（một quán tên là さくら）<br>B phía sau thường là những từ như 「人、店、町、食べ物、ドラマ、本」, tức từ cho người nghe biết “đây là loại gì”.</div><div class='gd-h'>Khi nào dùng</div><div class='gd-sec'><span class='gd-tag'>Giới thiệu tên</span>Dùng khi nhắc đến người, quán, tác phẩm, món ăn mà người nghe có thể chưa từng nghe.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の前に「さくら」という喫茶店があります。</span>（Trước ga có một quán cà phê tên là “さくら”）</div><div class='gd-ex-line'>・<span class='gd-jp'>山田という人から電話がありました。</span>（Có một người tên là Yamada gọi điện đến）</div><div class='gd-ex-line'>・<span class='gd-jp'>小籠包という食べ物を知っていますか。</span>（Bạn có biết món ăn tên là tiểu long bao không?）</div><div class='gd-sec'><span class='gd-tag'>Hỏi tên</span>Khi không biết một thứ tên là gì, dùng <span class='gd-jp'>何という</span> để hỏi; ở đây 「何」 đọc là <b>なん</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは何という花ですか。</span>（Loài hoa này tên là gì?）</div><div class='gd-h'>Những chỗ dễ nhầm</div><div class='gd-warn'>・Sau という <b>nhất định phải có danh từ</b>. Không được nói 「さくらというです」, phải nói đầy đủ: <span class='gd-jp'>さくらという店です</span>.<br>・Đừng thêm vào với những thứ ai cũng biết. Nói với người Nhật 「富士山という山」 nghe như “có một ngọn núi tên là Phú Sĩ, chắc bạn chưa nghe bao giờ”, rất kỳ.<br>・「いう」 thực tế thường được đọc thành <b>ゆう</b>, nhưng khi viết vẫn viết 「いう」, đừng viết thành 「とゆう」.<br>・「いう」 này quen viết bằng hiragana, ít khi viết bằng kanji 「言う」.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>という</b> ＝ có tên là ～: <span class='gd-jp'>村田という人</span>（một người tên là Murata）<br><b>の</b> ＝ thuộc về ～, của ～: <span class='gd-jp'>村田さんの友達</span>（bạn của anh Murata）<br>Vì の thường được dịch là “của”, nên bạn rất dễ viết “người tên Murata” thành 「村田の人」. Nhưng 「村田の人」 lại có nghĩa là “người nhà Murata / người bên phía Murata”, chứ không phải “tên là Murata”.</div><div class='gd-sec'>Ngoài ra, câu <span class='gd-jp'>林といいます。</span>（Tôi tên là Lâm）hay nghe khi tự giới thiệu đặt “có tên là” ở <b>cuối câu</b>, phía sau không nối danh từ.<br><span class='gd-jp'>林といいます。</span>（Tôi tên là Lâm）<br><span class='gd-jp'>林という人がいます。</span>（Có một người tên là Lâm）<br>Khi nói tên mình thì <b>không được thêm さん</b>: nói 「林さんといいます」 là sai.</div><div class='gd-warn'>Mẹo nhỏ để phân biệt: nếu trong tiếng Việt là “<b>tên là</b> ～” thì dùng という; còn chỉ là “của ai, thuộc nơi nào” thì dùng の.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Hỏi “cái này tiếng Nhật gọi là gì”: <span class='gd-jp'>これは日本語で何といいますか。</span>（Cái này tiếng Nhật gọi là gì?）</div>","n5-21":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>Khi 「で」 đứng sau phương tiện giao thông, nó có nghĩa là <b>「đi bằng ～」</b>. Tiếng Việt phải đổi động từ theo phương tiện: bắt xe buýt, đi tàu, đạp xe, lái xe... Tiếng Nhật thì dùng chung một khuôn cho mọi phương tiện: 「phương tiện＋で」, rồi nối với <span class='gd-jp'>行きます</span>, <span class='gd-jp'>来ます</span> hoặc <span class='gd-jp'>帰ります</span> là xong.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Phương tiện＋で＋行きます／来ます／帰ります. Danh từ đứng ngay phía trước, không cần biến đổi gì.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で会社に行きます。</span>（Tôi đi đến công ty bằng tàu điện.）</div><div class='gd-ex-line'>・<span class='gd-jp'>自転車で学校へ行きます。</span>（Tôi đạp xe đến trường.）</div><div class='gd-ex-line'>・<span class='gd-jp'>バスで帰ります。</span>（Tôi đi xe buýt về nhà.）</div><div class='gd-ex-line'>・<span class='gd-jp'>飛行機で来ました。</span>（Tôi đến đây bằng máy bay.）</div><div class='gd-sec'>Bạn thấy không: dù tiếng Việt nói “bắt, đạp, ngồi, lái” khác nhau, tiếng Nhật chỉ dùng đúng một chữ 「で」. Câu <span class='gd-jp'>車で行きます</span> cũng vậy: có thể là tự lái, cũng có thể là ngồi xe người khác, tiếng Nhật không phân biệt.</div><div class='gd-h'>Muốn hỏi “đến bằng gì?”</div><div class='gd-sec'>Chỉ cần thay phương tiện bằng 「何」:</div><div class='gd-ex-line'>・<span class='gd-jp'>何で来ましたか。</span>（Bạn đến bằng gì vậy?）</div><div class='gd-ex-line'>・<span class='gd-jp'>タクシーで来ました。</span>（Tôi đến bằng taxi.）</div><div class='gd-sec'>「何で」 ở đây đọc là <b>なにで</b>. Nếu đọc thành なんで thì rất dễ bị nghe thành “Tại sao lại đến?”.</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・<b>Đi bộ thì không dùng で</b>. Đừng nói 「足で行きます」, hãy nói <span class='gd-jp'>歩いて行きます</span> (đi bộ đến). Câu này cứ học thuộc cả câu là được.<br>・Hành động “lên xe buýt” phải dùng 「に」: <span class='gd-jp'>バスに乗ります</span> (lên xe buýt). Nhiều bạn nói thành 「バスで乗ります」, đây là sai.<br>・Thứ tự có thể đổi: <span class='gd-jp'>電車で東京へ行きます</span> và <span class='gd-jp'>東京へ電車で行きます</span> đều đúng, miễn là 「で」 đi liền ngay sau phương tiện.</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'><b>で (phương tiện)</b> ＝ “di chuyển” bằng gì: <span class='gd-jp'>バスで駅へ行きます。</span>（Tôi đi bằng xe buýt đến nhà ga.）<br><b>に＋乗ります</b> ＝ “lên” chiếc xe nào: <span class='gd-jp'>駅でバスに乗ります。</span>（Tôi lên xe buýt ở nhà ga.）<br><b>で (nơi diễn ra hành động)</b> ＝ làm việc gì ở đâu: <span class='gd-jp'>駅で</span> trong câu trên nghĩa là “ở nhà ga”. Phía trước nó là địa điểm chứ không phải phương tiện.</div><div class='gd-warn'>Mẹo phân biệt: phía sau là “đi, đến, về” thì sau phương tiện dùng で; phía sau là 「乗ります」 thì dùng に; còn nếu phía trước là địa điểm chứ không phải phương tiện thì で đó nghĩa là “ở ～”.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Thật ra 「で」 này mang nghĩa “bằng ～”, không chỉ dùng cho phương tiện mà còn cho cả đũa, ngôn ngữ... : <span class='gd-jp'>はしで食べます。</span>（Ăn bằng đũa.）Đó chính là bài tiếp theo: trợ từ で (phương tiện・dụng cụ).</div>","n5-22":"<div class='gd-h'>Hiểu nhanh trong một câu</div><div class='gd-sec'>「と」 nghĩa là <b>「cùng ～」「với ～」</b>. Muốn nói “Tôi xem phim với bạn”, bạn chỉ cần thêm と sau 「bạn」: <span class='gd-jp'>友達と映画を見ます</span>. Phía trước と là <b>người cùng làm việc đó với bạn</b>.</div><div class='gd-h'>Cách ghép</div><div class='gd-sec'>Rất đơn giản: <b>người＋と＋việc cần làm</b>. Muốn nhấn mạnh “cùng nhau”, bạn có thể thêm <span class='gd-jp'>一緒に</span> (cùng nhau) sau と. Nghĩa vẫn vậy, chỉ là cảm giác “cùng nhau” rõ hơn.<br><span class='gd-pair'><span class='gd-jp'>友達と</span> → <span class='gd-jp'>友達と一緒に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>友達と映画を見ました。</span>（Tôi đã xem phim với bạn.）</div><div class='gd-ex-line'>・<span class='gd-jp'>母と一緒に料理を作ります。</span>（Tôi cùng mẹ nấu ăn.）</div><div class='gd-ex-line'>・<span class='gd-jp'>毎朝、犬と散歩します。</span>（Sáng nào tôi cũng đi dạo với chó.）</div><div class='gd-sec'>Hỏi “đi với ai” thì dùng <span class='gd-jp'>誰と</span>, câu trả lời có thể nói gọn là 「người＋とです」.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰と行きますか。</span>（Bạn đi với ai?）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達とです。</span>（Với bạn.）</div><div class='gd-sec'>Nếu muốn nói rõ cả “tôi”, chủ ngữ dùng は, người đi cùng dùng と: <span class='gd-jp'>私は友達と京都へ行きます。</span>（Tôi đi Kyoto với bạn.）</div><div class='gd-h'>Chỗ dễ nhầm</div><div class='gd-warn'>・Tự làm một mình thì nói <span class='gd-jp'>一人で</span>, không phải 一人と. Khi nói số người hoặc cả nhóm cũng dùng で: <span class='gd-jp'>二人で</span>、<span class='gd-jp'>家族で</span>、<span class='gd-jp'>みんなで</span>.<br>・一緒に chỉ là phần thêm vào, có hay không đều được, vì chỉ riêng と đã có nghĩa “cùng với ai” rồi. Ngược lại, khi chỉ nói 一緒に mà không nói với ai là vì ai cũng biết đối tượng là ai: <span class='gd-jp'>一緒に帰りましょう。</span>（Cùng về nhé.）<br>・Những việc bắt buộc phải có hai người như <span class='gd-jp'>結婚する</span> cũng dùng と, và thường không thêm 一緒に: <span class='gd-jp'>田中さんと結婚しました。</span>（Tôi đã kết hôn với anh Tanaka.）</div><div class='gd-h'>Phân biệt với những mẫu trông giống nhau</div><div class='gd-sec'>と còn một cách dùng khác: nối hai thứ lại với nhau, giống “A và B” (liệt kê). Hãy xem hai câu này:<br><span class='gd-jp'>母とケーキを食べました。</span>（Tôi đã ăn bánh kem với mẹ.）→ Mẹ là <b>người cùng ăn</b><br><span class='gd-jp'>パンとケーキを食べました。</span>（Tôi đã ăn bánh mì và bánh kem.）→ Bánh mì và bánh kem đều là <b>thứ được ăn</b></div><div class='gd-warn'>Mẹo phân biệt: nếu trước と là “người cùng làm”, đó là nghĩa “cùng với ai” của bài này; nếu hai bên と là hai thứ đứng song song thì đó là “A và B”.</div><div class='gd-h'>Học xong có thể học tiếp</div><div class='gd-sec'>Kết hợp với 「〜ませんか」 là bạn có thể rủ người khác: <span class='gd-jp'>週末、私と映画を見ませんか。</span>（Cuối tuần này bạn có muốn đi xem phim với tôi không?）</div>"});
